def audit_hdk_refresh(args):
    """Publish only the bounded static HDK observation through the shared receipt."""
    audit = HostLocalAudit()
    a = audit.a
    report = {"recorded_at_utc": a.stamp(), "parser": audit.parser_versions, "failures": [],
              "source_chain_complete": False, "studio_to_hdk_refresh_complete": False,
              "target_execution": False, "real_device_operations": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("host.py", "frontend.py", "analysis.py", "evidence.py", "families.py"):
            audit.artifact(a.ROOT / "tools" / name)
        report.update(collect_hdk_refresh(audit))
    except (OSError, ValueError, KeyError, TypeError, StopIteration) as error:
        report["failures"].append(str(error))
    report["complete_originals"] = list(audit.sources.values())
    report["complete_source_owners"] = list(audit.owners.values())
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["failures"].extend("Audit artifact changed during query: " + name for name in report["changed_during_query"])
    report["bounded_observation_complete"] = not report["failures"]
    destination = a.ROOT / ".analysis/results/host-current/local-audit.json"
    publish_host_static_query(report, destination, a, "hdk_refresh")
    print(json.dumps({"receipt": a.rel(destination), "query": args.query,
                      "complete_source_owners": len(audit.owners), "failures": report["failures"]}), flush=True)
    if report["failures"]:
        raise ValueError("HDK refresh source query remains unresolved")


def collect_product_chroma_publisher(audit, originals):
    """Resolve the actual publisher imports without assuming minified aliases."""
    matches = [row for row in originals if Path(row["path"]).suffix == ".js"
               and b"generateUpdateChromaStudioPayload(" in audit.read(row)
               and b"updateChromaStudio(" in audit.read(row)]
    if len(matches) != 1:
        raise ValueError("Product Chroma publisher source is absent or ambiguous")
    source, = matches
    root = audit.tree(source).root_node
    selected, nodes = {}, {}
    for role, name in (
        ("engine_actual_chroma_devices_publisher", "updateChromaStudio"),
        ("engine_published_payload_actual_filter_and_order", "generateUpdateChromaStudioPayload"),
        ("engine_update_caller", "updateChromaDevice"),
        ("engine_refresh_caller", "handleRefreshDevices"),
        ("engine_add_caller", "addChromaDevice"),
        ("engine_remove_caller", "removeDeviceChromaEngine"),
        ("engine_remove_lighting_engine", "destroyDeviceLightingEngine"),
        ("engine_position_payload_consumer", "getDevicePositions"),
        ("engine_region_quick_effect", "applyRegionQuickEffect"),
        ("engine_hardware_quick_effect", "applyQuickEffect"),
        ("engine_hardware_effect_sync", "syncHWEffect"),
        ("engine_software_quick_effect", "applyCustomQuickEffect"),
        ("engine_device_storage_consumer", "onStorageChange_device"),
        ("engine_exit_restore", "onExit"),
    ):
        node, owner = audit.callable_member(role, source, root, name)
        nodes[name], selected[role] = node, [owner]

    stores = [node for node in _help_nodes(nodes["updateChromaStudio"])
              if node.type == "call_expression"
              and node.child_by_field_name("function").type == "member_expression"
              and node.child_by_field_name("function").child_by_field_name("property").text == b"setMemoryStorageItem"]
    if len(stores) != 1 or stores[0].parent.type != "await_expression":
        raise ValueError("Product Chroma publisher has no unique awaited memory write")
    store, = stores
    arguments = store.child_by_field_name("arguments").named_children
    if len(arguments) != 2 or arguments[0].type != "identifier":
        raise ValueError("Product Chroma publisher memory arguments require analysis")
    key_binding = audit.binding("engine_publisher_memory_key_argument", source,
                                arguments[0].text.decode(), arguments[0].start_byte)
    key = _help_binding_node(audit, source, key_binding).child_by_field_name("value")
    selected["engine_publisher_memory_key_argument"] = [key_binding["owner_id"]]
    api = store.child_by_field_name("function").child_by_field_name("object")
    quick_calls = [node for node in _help_nodes(nodes["applyQuickEffect"])
                   if node.type == "call_expression"
                   and node.child_by_field_name("function").type == "member_expression"
                   and node.child_by_field_name("function").child_by_field_name("property").text == b"setChromaEffectCommon"]
    if len(quick_calls) != 1:
        raise ValueError("Product Quick effect has no unique common-effect writer")
    quick_api = quick_calls[0].child_by_field_name("function").child_by_field_name("object")

    exports = []
    for role, access in (("engine_actual_memory_key", key), ("engine_actual_memory_api", api),
                         ("engine_quick_common_effect_api", quick_api)):
        if access is None or access.type != "member_expression":
            raise ValueError("Product Chroma publisher import is not a static export: " + role)
        namespace = access.child_by_field_name("object")
        imported, factory, owner = javascript_import_namespace(audit, originals, source, namespace, role=role)
        binding = audit.binding(role + "_namespace", source, namespace.text.decode(), namespace.start_byte)
        selected[role + "_namespace"] = [binding["owner_id"]]
        selected[role + "_factory"] = [owner]
        exported = audit.webpack_export(role, originals, _help_factory(factory)["module_id"],
                                        access.child_by_field_name("property").text.decode())
        exports.append({"role": role, **exported})
    exported_key = _help_binding_node(audit, exports[0]["original"], exports[0]["binding"])
    value = exported_key.child_by_field_name("value")
    if value is None or value.type != "string" or json.loads(value.text) != "lighting-engine-chroma-devices":
        raise ValueError("Product Chroma publisher memory key changed")

    for exported, methods in (
        (exports[1], (("engine_actual_host_memory_bridge", "getMemoryStorageItem"),
                      ("engine_actual_host_memory_publisher_bridge", "setMemoryStorageItem"))),
        (exports[2], (("engine_quick_common_effect_writer", "setChromaEffectCommon"),
                      ("engine_quick_common_effect_parameters", "generateSetChromaEffectCommonData"))),
    ):
        singleton = _help_binding_node(audit, exported["original"], exported["binding"])
        instance = singleton.child_by_field_name("value")
        constructor = instance.child_by_field_name("constructor") if instance is not None and instance.type == "new_expression" else None
        if constructor is None or constructor.type not in {"identifier", "class"}:
            raise ValueError("Product Chroma API has no static instance owner: " + exported["role"])
        if constructor.type == "identifier":
            binding = audit.binding(exported["role"] + "_class", exported["original"],
                                    constructor.text.decode(), constructor.start_byte)
            api_owner = _help_binding_node(audit, exported["original"], binding)
        else:
            api_owner = constructor
        for role, name in methods:
            _, owner = audit.callable_member(role, exported["original"], api_owner, name)
            selected[role] = [owner]
    return {"selected": selected, "exports": exports, "memory_key": json.loads(value.text),
            "awaited_memory_write": {"original": source, "byte_start": store.start_byte, "byte_end": store.end_byte}}


def product_chroma_reducer(audit, source, initial_owner, role):
    """Follow the reducer's actual initial-state return through lexical scope."""
    initial = audit.owners[initial_owner]
    root = audit.tree(source).root_node
    node = root.descendant_for_byte_range(initial["byte_start"], initial["byte_end"] - 1)
    while node is not None and (node.start_byte, node.end_byte) != (initial["byte_start"], initial["byte_end"]):
        node = node.parent
    if node is None or node.type != "variable_declarator":
        raise ValueError("Product Chroma reducer initial state is not a complete declaration")
    name = node.child_by_field_name("name").text
    matches = []
    for candidate in _help_nodes(root):
        if candidate.type != "return_statement" or candidate.named_child_count != 1:
            continue
        value = candidate.named_children[0]
        if value.type != "identifier" or value.text != name:
            continue
        binding = audit.binding(role + "_initial_reference", source, name.decode(), value.start_byte)
        if binding.get("owner_id") != initial_owner:
            continue
        function = candidate.parent
        while function is not None and function.type not in {"function_expression", "arrow_function", "function_declaration"}:
            function = function.parent
        if (function is not None and function.type == "function_expression"
                and function.parent.type == "variable_declarator"
                and any(child.type == "switch_statement" for child in function.child_by_field_name("body").named_children)):
            matches.append(function.parent)
    if len(matches) != 1:
        raise ValueError("Product Chroma reducer is absent or ambiguous for its real initial state")
    reducer, = matches
    return audit.retain_range(role, source, reducer.start_byte, reducer.end_byte, reducer.type)


def nsis_unicode_string(strings, offset):
    """Decode the observed UTF-16 NSIS tokens without expanding VM variables."""
    if type(offset) is not int or offset < 0 or offset * 2 >= len(strings) or len(strings) % 2:
        raise ValueError("Unicode NSIS string offset or table length is invalid")
    cursor, literal, tokens = offset * 2, bytearray(), []

    def flush():
        if literal:
            try:
                value = literal.decode("utf-16le")
            except UnicodeDecodeError as error:
                raise ValueError("Unicode NSIS literal is invalid UTF-16") from error
            tokens.append({"kind": "literal", "value": value})
            literal.clear()

    while cursor + 2 <= len(strings):
        code = struct.unpack_from("<H", strings, cursor)[0]
        cursor += 2
        if code == 0:
            flush()
            return tokens
        if code in (1, 2, 3, 4):
            if cursor + 2 > len(strings):
                raise ValueError("Unicode NSIS token is truncated")
            following = struct.unpack_from("<H", strings, cursor)[0]
            cursor += 2
            if following == 0:
                raise ValueError("Unicode NSIS token has no encoded value")
            if code == 4:
                literal.extend(struct.pack("<H", following))
            else:
                flush()
                tokens.append({"kind": {1: "language", 2: "shell", 3: "variable"}[code],
                    "index": (following & 127) | (((following >> 8) & 127) << 7),
                    "encoded": following})
        else:
            literal.extend(struct.pack("<H", code))
    raise ValueError("Unicode NSIS string is unterminated")


def interhaptics_service_calls(header, strings):
    """Retain only actual SimpleSC calls and the arguments each export pops."""
    arity = {"ExistsService": 1, "GetServiceStatus": 1, "StopService": 3, "RemoveService": 1}
    calls = []
    for index, entry in enumerate(header["entries"]):
        if entry[0] != 44:
            continue
        module = nsis_unicode_string(strings, entry[1])
        if not any(token.get("value", "").endswith("\\SimpleSC.dll") for token in module):
            continue
        name = nsis_unicode_string(strings, entry[2])
        if len(name) != 1 or name[0]["kind"] != "literal" or name[0]["value"] not in arity:
            raise ValueError("Unreviewed InterHaptics SimpleSC export")
        export = name[0]["value"]
        count = arity[export]
        arguments = []
        for distance in range(1, count + 1):
            if index < distance:
                raise ValueError("InterHaptics SimpleSC argument stack is incomplete")
            push = header["entries"][index - distance]
            if push[0] != 31 or push[2] != 0:
                raise ValueError("InterHaptics SimpleSC arguments are not contiguous pushes")
            arguments.append({"entry": index - distance, "instruction": push,
                              "tokens": nsis_unicode_string(strings, push[1])})
        consumers = []
        for following in range(index + 1, min(len(header["entries"]), index + 5)):
            row = header["entries"][following]
            if row[0] != 31 or row[2] != 1:
                break
            consumers.append({"entry": following, "variable_index": row[1], "instruction": row})
        expected = 2 if export == "GetServiceStatus" else 1
        if len(consumers) != expected:
            raise ValueError("InterHaptics SimpleSC result stack differs")
        calls.append({"entry": index, "instruction": entry, "module": module, "export": export,
            "arguments_in_pop_order": arguments, "result_consumers_in_pop_order": consumers})
    if not calls:
        raise ValueError("No InterHaptics SimpleSC calls were found")
    return calls


def interhaptics_file_path_projection(binary_path):
    """Project the reviewed UTF-16 string operations without executing the plugin."""
    if not isinstance(binary_path, str):
        raise ValueError("InterHaptics binary path must be a string")
    end = max(binary_path.rfind("\\"), binary_path.rfind(":")) + 1
    return binary_path[:end] + binary_path[end:].split(" ", 1)[0]


def interhaptics_file_path_proof(retained):
    """Bind the assembly-based path conclusion to its complete reviewed owners."""
    reviewed = {
        0x203e4: "f4cb1fb5e58421afb6da601a14fa319e01c590e148545e863303ecc76a931d02",
        0x2ac84: "3fcda2db0a33852ff5f717a6efbec113fae43b3008158e12b6e5d2a4c00af4e6",
        0xa8a0: "36bacffc75cd9a6bb2edf12d7729b7b3d56e729495ab43ce3d2722c7d63d4d5e",
        0xa9f8: "2e6e7f6ce91a40a801e10c77df8ab05966c04baae0fbf0fc9ebcaa1247f5e26e",
        0xa730: "b4bc237d0700a2b21994e1dcef17a13248ed0f42e1426199da0747cb9fec55b6",
        0xe8f38: "f8cfdfb1a1a16dd2b16101e67ccfe4580897c990caa91f5c6ca04655bbf514f3",
        0x2034c: "eb0c5abdf1763cd04cf33007e28f99531121c098094a535f9a6d297d9873983f",
        0xe9028: "f7c5e46ab051a3a5b183f0af8e73e3fe6c593b8d807a1472e78ec30cf154c1a0",
    }
    functions = {int(row["capture"]["rva"], 16): row for row in retained["complete_functions"]}
    owners = []
    for rva, expected in reviewed.items():
        row = functions.get(rva)
        if row is None or row.get("input_chunks_verified") is not True:
            raise ValueError("InterHaptics reviewed path owner is absent: " + hex(rva))
        digest = hashlib.sha256(b"".join(bytes.fromhex(chunk["raw_hex"])
            for chunk in row["capture"]["chunks"])).hexdigest()
        if digest != expected:
            raise ValueError("InterHaptics reviewed path owner bytes differ: " + hex(rva))
        owners.append({"rva": hex(rva), "artifact": row["artifact"], "logical_chunks_sha256": digest})
    regions = {row["role"]: row for row in retained["verified_data_regions"]}
    for role, rva, raw_hex in (("binary_path_directory_separators", "0x20494", "5c003a000000"),
                               ("binary_path_argument_separator", "0xe9024", "20000000")):
        row = regions.get(role)
        if row is None or row["rva"] != rva or row["raw_hex"] != raw_hex:
            raise ValueError("InterHaptics reviewed path separator differs: " + role)
    return {"reviewed_owners": owners, "basis": "Complete assembly and actual PE chunks; not an executable ABI or DLL result",
        "directory_search": {"owner_rva": "0x203e4", "search_rva": "0x2ac84",
            "separators_rva": "0x20494", "result": "Last backslash or colon, zero-based; -1 if absent"},
        "tail_copy": {"owner_rva": "0xe8f38", "copy_rva": "0xa8a0", "search_rva": "0xa9f8",
            "result": "Keep prefix through separator, truncate tail at its first ASCII space, concatenate without quote or environment expansion"},
        "existence_gate": {"owner_rva": "0x2034c", "caller_rva": "0xe9028",
            "false_result": "Return0 without attempting the exclusive file-open loop"},
        "decompiler_limitation": "0x203e4 retains the bad-stack warning; complete assembly establishes argument setup and Copy bounds",
        "static_path_semantics_complete": True, "official_execution_verified": False}


def collect_interhaptics_services(audit):
    """Join the retained official NSIS caller to its byte-verified SCM plugin."""
    a = audit.a
    acquisition_path = a.ROOT / ".analysis/inputs/official-native-current/acquisition.json"
    acquisition = json.loads(audit.artifact(acquisition_path))
    candidates = [row for row in acquisition["resources"] if row.get("status") == "verified"
                  and any(item.get("resource_name") == "Skip_RzInterHaptics" for item in row.get("manifests", []))]
    if len(candidates) != 1:
        raise ValueError("Current InterHaptics package is absent or ambiguous")
    package = candidates[0]
    raw = audit.read(package)
    if package["sha256"] != package["declared_sha256"] or package["bytes"] != package["declared_bytes"]:
        raise ValueError("Current InterHaptics package declaration differs")
    manifests = [item for item in package["manifests"] if item.get("resource_name") == "Skip_RzInterHaptics"]
    for manifest in manifests:
        current = json.loads(audit.artifact(a.ROOT / manifest["path"], manifest))
        declarations = [row for row in current["resourceManifest"]["resources"]
                        if row.get("resourceName") == "Skip_RzInterHaptics"]
        if (len(declarations) != 1 or declarations[0]["sha256"].lower() != package["sha256"]
                or declarations[0]["size"] != package["bytes"] or declarations[0]["url"] != package["url"]
                or declarations[0]["resourceVersion"] != manifest["resource_version"]):
            raise ValueError("Current InterHaptics manifest declaration differs")
        stability = [row for row in acquisition["stability"] if row["url"] == manifest["url"]]
        if (len(stability) != 1 or stability[0].get("unchanged") is not True
                or stability[0]["before_sha256"] != manifest["sha256"]
                or stability[0]["after_sha256"] != manifest["sha256"]):
            raise ValueError("Current InterHaptics deployment stability is unverified")
    inspection_path = a.ROOT / ".analysis/results/native-packages" / package["sha256"] / "inspection.json"
    inspection = json.loads(audit.artifact(inspection_path))
    if (inspection["container"] != {key: package[key] for key in ("path", "bytes", "sha256")}
            or inspection.get("extracted") is not True or inspection.get("extraction_exit_code") != 0
            or inspection.get("listing_exit_code") != 0 or inspection.get("input_bytes_unchanged") is not True
            or inspection.get("duplicate_entry_paths") or inspection.get("target_execution") is not False):
        raise ValueError("Current InterHaptics static extraction is incomplete")

    def member(name):
        members = [row for row in inspection["files"] if Path(row["path"]).name == name]
        if len(members) != 1:
            raise ValueError("InterHaptics package member is absent or ambiguous: " + name)
        original = members[0]
        if (original.get("container") != package["path"] or original.get("container_sha256") != package["sha256"]
                or original.get("declared_container_sha256") != package["sha256"]
                or original.get("container_extraction_complete") is not True
                or original.get("verified_against_manifest") is not True):
            raise ValueError("InterHaptics member package identity differs: " + name)
        audit.read(original)
        return original

    callers = []
    for role, original, body in (("installer", package, raw), ("uninstaller", member("Uninstall.exe"), None)):
        header, strings = audit.families.driver_install_nsis_header(
            body if body is not None else audit.read(original), 0x9200)
        calls = interhaptics_service_calls(header, strings)
        callers.append({"role": role, "original": audit.sources[original["path"]],
            "header": header, "string_encoding": "UTF-16LE code units; preserved NSIS tokens",
            "simple_sc_calls": calls,
            "interpreter": audit.native_slice(original, (), depth=0, rvas=(0x1389, 0x1434, 0x30a9, 0x65b9))})
    plugin = audit.native_slice(member("SimpleSC.dll"),
        ("ExistsService", "GetServiceStatus", "StopService", "RemoveService"), depth=0,
        rvas=(0xe923c, 0xe9b04, 0xe966c, 0xeafa4, 0xe9148, 0xe9028, 0xe9bc0, 0xe8f38, 0xeb664,
              0x37bb8, 0x37c34, 0x37c68, 0xb578, 0xe8e84, 0x22554, 0x22028, 0x2215c,
              0x22130, 0x220f4, 0x22174, 0x221ec, 0x2206c, 0x220b4, 0x22390,
              0x203e4, 0x2ac84, 0x2034c, 0x2030c, 0xa8a0, 0xa9f8, 0xa730, 0x9e40, 0xa4e0),
        regions=({"role": "stop_wait_file_flag_literal", "rva": 0xeb6c4, "bytes": 4},
                 {"role": "binary_path_argument_separator", "rva": 0xe9024, "bytes": 4},
                 {"role": "binary_path_directory_separators", "rva": 0x20494, "bytes": 6},
                 {"role": "date_time_milliseconds_per_day", "rva": 0xf45e4, "bytes": 8}))
    failures = [row for result in [plugin] + [caller["interpreter"] for caller in callers]
                for row in result["failures"]]
    if failures:
        raise ValueError("InterHaptics selected native functions are unavailable: " + str(failures))
    region_bytes = {row["role"]: bytes.fromhex(row["raw_hex"]) for row in plugin["verified_data_regions"]}
    if (region_bytes["stop_wait_file_flag_literal"] != "1\0".encode("utf-16le")
            or region_bytes["binary_path_argument_separator"] != " \0".encode("utf-16le")
            or struct.unpack("<fI", region_bytes["date_time_milliseconds_per_day"]) != (86400000.0, 86400000)):
        raise ValueError("InterHaptics reviewed stop flag or deadline constants differ")
    for caller in callers:
        for call in caller["simple_sc_calls"]:
            if call["export"] == "StopService" and [row["tokens"] for row in call["arguments_in_pop_order"]][1:] != [
                    [{"kind": "literal", "value": "1"}], [{"kind": "literal", "value": "30"}]]:
                raise ValueError("InterHaptics reviewed stop arguments differ")
    return {"acquisition": audit.families.identity(acquisition_path), "package": package,
        "inspection": audit.families.identity(inspection_path), "manifests": manifests,
        "callers": callers, "plugin": plugin, "file_path_proof": interhaptics_file_path_proof(plugin),
        "semantics": {
            "actual_scope": "The installer calls ExistsService, GetServiceStatus, StopService and RemoveService; the uninstaller calls the latter three. StartService and InstallService are not SimpleSC calls in these headers.",
            "result_stack": "GetServiceStatus pushes currentState then Win32 error, so the first script Pop is error and the second is state. State starts at zero and is only assigned after successful QueryServiceStatus; error plus zero is not an observed service state.",
            "exists": "OpenSCManagerW access1 and OpenServiceW access1; return0 means both opens succeeded. Missing service, access and query failures remain Win32 errors, not a Boolean absence observation. Acquired service/SCM handles close.",
            "stop_arguments": "Both callers push 30,1,serviceName; the export pops serviceName,waitForFileFlag,timeoutSeconds. Only the literal UTF-16 string1 enables the flag.",
            "stop": "Open SCM access5 and service access0x28. Enumerate active dependent services with a size probe and buffer, recursively stop each with flag0 and the same timeout; a dependent error prevents the parent ControlService. ControlService(STOP) success is followed by QueryServiceStatus until state1. Close service and SCM handles before the optional file wait.",
            "stop_buffer": "The selected StopService assembly allocates the dependent-services buffer at0xe9702 and advances its pointer by0x24 per row; its normal/finally paths contain no matching buffer free. Do not claim full original buffer release.",
            "wait": "Each wait constructs its own deadline from GetLocalTime-based date/time plus timeoutSeconds*1000 milliseconds. State mismatch sleeps250ms; query errors return immediately; expired state wait returns1053. This is neither a shared end-to-end30-second deadline nor cancellation.",
            "file_path": "Keep the prefix through the last backslash or colon anywhere in the input; truncate only the remaining tail at its first ASCII space. Quotes, tabs and environment variables are preserved, and a later separator in an argument participates in the prefix. This is not Windows command-line parsing.",
            "file_wait": "If stop result is0 and flag1, QueryServiceConfigW obtains the binary path using a temporary buffer that is freed. GetFileAttributesW errors2,3,123 return false at the existence gate; other errors can probe FindFirstFileW. Directories return false; the reparse branch checks read access with share1 and treats error32 as present. A false gate returns0 without the exclusive-open loop. A true gate repeatedly calls CreateFileW(GENERIC_READ|GENERIC_WRITE,share0,OPEN_EXISTING). A successful handle closes; the loop has no sleep and returns250 on its own deadline. Return0 alone is not file-release, process-exit or device-stop confirmation.",
            "remove": "Open SCM0xf003f and service0xf01ff; LockServiceDatabase, DeleteService, UnlockServiceDatabase, close both handles. Return0 only confirms DeleteService accepted; there is no stop or wait for final deletion. Unlock/Close results are not promoted to the operation result.",
            "nsis_stack": "Pop copies and unlinks a GlobalAlloc stack node then GlobalFree; Push allocates a capacity-bounded UTF-16 node and links it at the head. Managed plugin strings release through their finally paths. Decompiler register arguments are not a callable export ABI.",
            "caller_consumers": "Stop and Remove return values are popped and logged; later status/process and directory branches decide continuation and RunOnce3010. Installer and uninstaller retain their distinct final process barriers; neither logging nor a plugin return establishes actual device stop.",
        },
        "remaining_chains": [
            "Current SynesthesiaStop.exe and Interhaptics.HidProvider.dll remain absent from this package; their internal behavior is not closed by SimpleSC analysis.",
            "SCM service changes, official plugin execution, independent Rust behavior and runtime installation acceptance remain unverified.",
        ], "selected_scm_paths_observed": True, "native_semantics_complete": False,
        "target_execution": False, "real_device_operations": False}


def audit_interhaptics_services(args):
    audit = HostLocalAudit()
    report = {"recorded_at_utc": audit.a.stamp(), "failures": [], "source_chain_complete": False,
              "product_code_modified": False, "target_execution": False,
              "real_device_operations": False, "runtime_acceptance": "unverified"}
    try:
        for name in ("tools/host.py", "tools/families.py", "tools/analysis.py", "tools/workspace.py"):
            audit.artifact(audit.a.ROOT / name)
        report.update(collect_interhaptics_services(audit))
    except (OSError, ValueError, KeyError, TypeError, StopIteration) as error:
        report["failures"].append(str(error))
    report["complete_originals"] = list(audit.sources.values())
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["failures"].extend("Audit artifact changed during query: " + name for name in report["changed_during_query"])
    report["bounded_observation_complete"] = not report["failures"]
    destination = audit.a.ROOT / ".analysis/results/host-current/local-audit.json"
    publish_host_static_query(report, destination, audit.a, "interhaptics_services")
    print(json.dumps({"receipt": audit.a.rel(destination), "query": args.query,
        "callers": len(report.get("callers", [])), "failures": report["failures"]}), flush=True)
    if report["failures"]:
        raise ValueError("InterHaptics service source query remains unresolved")


def audit_product_chroma_observation(args):
    """Rebuild product host observation evidence from current original bytes."""
    audit = HostLocalAudit()
    a = audit.a
    report = {"recorded_at_utc": a.stamp(), "parser": audit.parser_versions,
              "source_sets": [], "selected": {}, "exports": [], "failures": [],
              "source_chain_complete": False, "target_execution": False,
              "real_device_operations": False, "runtime_acceptance": "unverified"}
    selected = report["selected"]
    try:
        for name in ("tools/host.py", "tools/workspace.py", "tools/families.py", "tools/evidence.py", "tools/frontend.py", "tools/analysis.py"):
            audit.artifact(a.ROOT / name)
        sources = {}
        for name in ("synapse-lighting-engine-current", "mouse-226-current", "keyboard-756-current", "mouse-162-current"):
            source_set, originals = audit.current_source_set(name)
            source_set["verified_complete_capture"] = (audit.frontend_capture(source_set["name"], originals)
                                                        if source_set["capture"] is not None else None)
            report["source_sets"].append(source_set)
            sources[name] = originals

        def source(name, anchor):
            matches = [row for row in sources[name] if Path(row["path"]).suffix == ".js"
                       and anchor.encode() in audit.read(row)]
            if len(matches) != 1:
                raise ValueError("Product Chroma source is absent or ambiguous: " + anchor)
            return matches[0]

        def retain(role, original, anchor, kinds, unique=True):
            selected[role] = audit.retain(role, original, anchor, set(kinds), unique=unique)
            return selected[role]

        publisher = collect_product_chroma_publisher(audit, sources["synapse-lighting-engine-current"])
        selected.update(publisher["selected"])
        report["exports"].extend(publisher["exports"])
        report["publisher_binding"] = {key: value for key, value in publisher.items() if key not in {"selected", "exports"}}

        for family, name in (("mouse", "mouse-226-current"), ("keyboard", "keyboard-756-current")):
            lighting = source(name, "checkSyncQuickEffect(e){")
            for role, anchor in (("quick_memory_consumers_complete_classes", "this.checkSyncQuickEffect("),
                                 ("installation_consumers_complete_classes", "e.checkIsFullyInstall().then(")):
                retain(family + "_" + role, lighting, anchor, ("class_declaration", "class"), False)
            for index, anchor in enumerate(("loadActiveProfileSettings(){", "this.loadActiveProfileSettings=")):
                root = source(name, anchor)
                retain(family + "_local_profiles_projection_branch_" + str(index), root, anchor,
                       ("method_definition", "assignment_expression"))
            main = source(name, "this.getMemoryStorageItem=")
            retain(family + "_actual_get_memory_storage_bridge", main, "this.getMemoryStorageItem=", ("assignment_expression",))
            retain(family + "_local_projection_keys", main, "{DEVICE_TYPE:", ("variable_declarator",))
            initial, = retain(family + "_lighting_reducer_initial_state", main,
                              "{selectedEffectId:3,effectSettings:[]", ("variable_declarator",))
            selected[family + "_profiles_reducer_dispatch"] = [
                product_chroma_reducer(audit, main, initial, family + "_profiles_reducer_dispatch")]
            checker = source(name, "async checkIsFullyInstall(){")
            retain(family + "_fully_installed_complete_owner", checker, "async checkIsFullyInstall(){", ("class", "class_declaration"))

        babel = source("mouse-162-current", "r.loadActiveProfileSettings=function()")
        retain("babel_local_profiles_projection", babel, "r.loadActiveProfileSettings=function()", ("assignment_expression",))
        retain("babel_quick_memory_complete_component", babel, "uJ=function(e){", ("variable_declarator",))
        retain("babel_advanced_complete_component", babel, "_J=function(e){", ("variable_declarator",))
        retain("babel_advanced_connected_component", babel, "fJ=(0,L.connect)", ("variable_declarator",))
        retain("babel_effects_complete_component", babel, "OJ=function(e){", ("variable_declarator",))
        advanced = audit.owners[selected["babel_advanced_complete_component"][0]]["body"]
        if "checkIsFullyInstall" in advanced or "this.props.isChromaInstalled" not in advanced:
            raise ValueError("Current Babel installation branch changed")
        connected = audit.owners[selected["babel_advanced_connected_component"][0]]["body"]
        if 'commonReducer.installedModules||[]' not in connected or '"chroma-app"===e' not in connected:
            raise ValueError("Current Babel module-status projection changed")
        report["host_provenance"] = verified_host_owners(audit, (
            "electron/modules/memory_storage/index.js", "electron/modules/window_storage/index.js"))
        for name, item in report["host_provenance"].items():
            row = item["original"]
            key = audit.retain_range("host_" + name.split("/")[-2] + "_complete_owner", row, 0,
                                     len(audit.read(row)), "program")
            selected["host_" + name.split("/")[-2] + "_complete_owner"] = [key]
        report["semantics"] = {
            "independent_observations": "Local Chroma configuration, module state, dynamic-lighting state, installation probes and the lighting-engine memory publisher have independent producers and failure results.",
            "publisher": "updateChromaStudio publishes generateUpdateChromaStudioPayload through its actual lexical import of lighting-engine-chroma-devices. Preserve actual device filters, ordering and empty-payload distinction.",
            "publisher_filters": "The current publisher preserves Map order and excludes the exact removed product/instance, powered-off power-button devices, unsupported Chroma and invalid region/strip/Glitter branches. A duplicate ID for the requested key aborts publication; another duplicate is skipped. Empty add is unpublished; update/remove can publish an empty device list.",
            "publisher_identity": "Each published device omits rzDevice, rzDeviceConstructor and quickEffectOnExit before cloning; clone failure skips the item. Region identity is rewritten before isNaN(instanceId)?0:instanceId: nonnumeric identities become zero, otherwise the actual value is preserved, including numeric strings. containerId preserves the region/instance identity. localStoragePId, deviceId, WDL and mirror-region fields come from their real owners. Non-blob ledConfig is published as an object URL.",
            "publisher_result": "The memory write is awaited, but its try/catch also covers post-write log cloning and returns no success/confirmation result. A caught error therefore cannot establish whether storage was already written. Removal first awaits destruction of the lighting engine. Position lookup also consumes the payload producer directly without publishing memory storage.",
            "quick_effect_completion": "applyQuickEffect schedules an async setChromaEffectCommon call after 50 ms without retaining the timer handle. Awaiting this method only completes timer scheduling, not the hardware SET, acknowledgement or readback. Region hardware/battery branches await this scheduling boundary; software rendering and exit restoration have separate owners.",
            "memory_getter": "The host stores publisher URL entries in Map order; QuickEffects reads only the first returned value, subscribes to memorystorageevent, and removes its handler on unmount. Absent and published-empty remain separate observations.",
            "local_profiles": "Current product roots select the matching source-local Chroma record and dispatch enabled, profiles and currentProfile independently of installation and memory results. Missing or failed reads cannot establish default or old device state.",
            "babel": "PID162 loads local Chroma profiles in loadActiveProfileSettings. Its connected advanced component derives isChromaInstalled from commonReducer.installedModules. Its complete advanced component contains no checkIsFullyInstall call; this branch must not run the newer installation probe.",
            "installation": "Newer advanced components call the complete checker, which combines the actual app-engine product observation and local Apps folder existence. This proves host installation facts only.",
        }
        report["remaining_chains"] = [
            "Reuse the retained ordinary Quick storage, region/hardware/software and exit owners; close remaining product/accessory consumers and native response/recovery dependencies before independent Rust migration.",
            "These complete owners cover PID162, PID226 and PID756 host observation boundaries; they do not establish the entire mounted UI/backend checklist for all products.",
            "Frontend capture failures and missing source maps remain recorded in each source set; retained source owners are not complete reconstructed-source or runtime acceptance.",
        ]
    except (OSError, ValueError, KeyError, TypeError, StopIteration) as error:
        report["failures"].append(str(error))
    report["complete_originals"] = list(audit.sources.values())
    report["complete_source_owners"] = list(audit.owners.values())
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["failures"].extend("Audit artifact changed during query: " + name for name in report["changed_during_query"])
    report["bounded_observation_complete"] = not report["failures"]
    destination = a.ROOT / ".analysis/results/host-current/local-audit.json"
    publish_host_static_query(report, destination, a, "product_chroma_observation")
    print(json.dumps({"receipt": a.rel(destination), "query": args.query,
                      "complete_source_owners": len(audit.owners), "failures": report["failures"]}), flush=True)
    if report["failures"]:
        raise ValueError("Product Chroma source observation query remains unresolved")


def collect_chroma_dashboard_launch(audit, host_originals):
    """Join the current Chroma hidden-start/restore page to URL-keyed host storage."""
    source_set, originals = audit.source_set("chroma-app-dashboard-current")
    names = ("main.e5fe7086.js", "332.780bf0e1.chunk.js", "3874.4172ec87.chunk.js",
             "4461.7a5efde4.chunk.js", "6883.53d122e0.chunk.js")
    files = [source for source in originals if Path(source["path"]).name in names]
    if len(files) != len(names):
        raise ValueError("Current Chroma launch originals are absent or ambiguous")
    main = next(source for source in files if Path(source["path"]).name == names[0])
    chunk = next(source for source in files if Path(source["path"]).name == names[1])
    installer = next(source for source in files if Path(source["path"]).name == names[3])
    content = next(source for source in files if Path(source["path"]).name == names[4])
    selected, exports, bindings = {}, {}, {}

    def binding(role, source, name, reference):
        result = audit.binding("chroma_launch_" + role, source, name, reference)
        if result["resolution"] != "declaration":
            raise ValueError("Current Chroma launch has an unresolved binding: " + role)
        selected[role], bindings[role] = result["owner_id"], result
        return audit.tree(source).root_node.descendant_for_byte_range(result["start_byte"], result["end_byte"] - 1)

    def export(role, module, name, *, sources=None):
        result = audit.webpack_export("chroma_launch_" + role, files if sources is None else sources, module, name)
        exports[role] = result
        selected[role] = result["binding"]["owner_id"]
        result_binding = result["binding"]
        return audit.tree(result["original"]).root_node.descendant_for_byte_range(
            result_binding["start_byte"], result_binding["end_byte"] - 1)

    selected["entry_mount"] = audit.retain("chroma_launch_entry_mount", main,
        "Promise.all([T.e(7714),T.e(3874),T.e(332)])", {"arrow_function"})[0]
    export("entry_export", 11078, "default")
    binding("language_wrapper", chunk, "Ne", 332540)
    page = binding("page_class", chunk, "ge", 332000)
    binding("install_gate", chunk, "Ce", 330800)
    binding("hidden_flag", chunk, "De", 330800)
    binding("auto_start_query", chunk, "Se", 328470)
    binding("force_hidden_query", chunk, "Ie", 328470)
    for name in ("handleAppHiddenStart", "handleOnUserRestoreWindow", "componentDidMount", "render"):
        _, selected[name] = audit.callable_member("chroma_launch_" + name, chunk, page, name)
    for role, name in (("error_boundary_connect", "B"), ("error_boundary", "F"),
                       ("user_gate_connect", "z"), ("user_gate_class", "x"),
                       ("page_store_namespace", "o"), ("lazy_namespace", "de")):
        binding(role, chunk, name, 331400)
    export("store_export", 58837, "A")
    for role, name, reference in (("store_constructor", "ut", 1371540),
                                  ("root_reducers", "dt", 1371478),
                                  ("user_initial", "X", 1369800),
                                  ("store_redux_namespace", "a", 1371478),
                                  ("installer_initial", "Ve", 1359450),
                                  ("installer_reducer", "Ke", 1369400),
                                  ("installer_phase_namespace", "ke", 1359450)):
        binding(role, chunk, name, reference)
    for role, module, name in (("create_store", 17863, "y$"), ("combine_reducers", 17863, "HY"),
                              ("lazy_component", 13545, "kg"),
                              ("installer_phase_type", 19581, "TM"),
                              ("installation_wrapper", 34461, "default"),
                              ("content_export", 23322, "default")):
        export(role, module, name)
    binding("installation_ui", installer, "x", 24700)
    binding("installer_events_namespace", installer, "U", 15590)
    # This route requests chunk 4461. Another retained, unrequested chunk has
    # the same module number; keep the reviewed factory's actual source owner.
    export("installer_events", 20682, "A", sources=[installer])
    for role, name in (("content_wrapper", "ja"), ("content_page", "ka"),
                       ("content_window_listener", "Pa")):
        binding(role, content, name, 157900)
    descriptors = export("hidden_descriptors", 60336, "Oc")
    for name in ("l", "d"):
        binding("descriptor_" + name, chunk, name, descriptors.start_byte)
    for role, module, name in (("tab_helper", 87893, "A"), ("tab_manager", 28648, "A"),
                              ("visualizer_key", 69937, "XrU"), ("host_facade", 37226, "A")):
        export(role, module, name)
    tab_helper = audit.owners[selected["tab_helper"]]
    tab_root = audit.tree(chunk).root_node.descendant_for_byte_range(tab_helper["byte_start"], tab_helper["byte_end"] - 1)
    _, selected["getTabInfo"] = audit.callable_member("chroma_launch_getTabInfo", chunk, tab_root, "getTabInfo")
    manager = audit.owners[selected["tab_manager"]]
    manager_root = audit.tree(chunk).root_node.descendant_for_byte_range(manager["byte_start"], manager["byte_end"] - 1)
    _, selected["forceOpenHiddenTab"] = audit.callable_member(
        "chroma_launch_forceOpenHiddenTab", chunk, manager_root, "forceOpenHiddenTab")
    facade = binding("facade_class", main, "R", exports["host_facade"]["binding"]["start_byte"])
    for name in ("callElectronAction", "getWindowStorageItem", "setWindowStorageItem", "getWindowServiceClients"):
        _, selected[name] = audit.callable_member("chroma_launch_" + name, main, facade, name)
    for role, relative, name in (("host_storage", "modules/window_storage/index.js", "callFunction"),):
        source = host_originals["electron/" + relative]
        _, selected[role] = audit.callable_member("chroma_launch_" + role, source, audit.tree(source).root_node, name)
    preload = host_originals["electron/preload.js"]
    for role, name in (("preload_response", "response"), ("preload_invoke", "doElectronAction")):
        _, selected[role] = audit.callable_member("chroma_launch_" + role, preload, audit.tree(preload).root_node, name)
    selected["preload_pagehide"] = audit.retain("chroma_launch_preload_pagehide", preload,
        'window.addEventListener("pagehide",', {"call_expression"})[0]
    dispatch = host_originals["electron/main.js"]
    selected["host_dispatch"] = audit.retain("chroma_launch_host_dispatch", dispatch,
        'n.handle("electronAction",', {"call_expression"})[0]
    report = {"source_set": source_set, "selected": selected, "exports": exports, "bindings": bindings,
        "mount_boundaries": chroma_dashboard_mount_boundaries(),
        "semantics": {
            "hidden_start": "Only autoStart=1 together with forceHidden=1 initializes hidden. The page requests background-manager and notification-manager through the shared lock-based hidden-tab helper.",
            "visualizer": "Hidden start reads the saved synapseAudioVisualizerProfiles visualizerState and the actual window-client list. It opens the existing local Visualizer URL only when no matching tab was found and the saved state is truthy; this is not a device getter or confirmed engine start.",
            "restore": "visibleChange with isVisible, changeActiveTab for chroma-app, focus with isFocus and USER_CLICK_DESKTOP_ICON request restore. An empty status array or no value.windowName containing chroma-app returns before unhiding. The selected URL row with installing status blocks only the running publication; the page still clears its hidden state afterwards. A rejected initial storage await occurs before the try block and does not reach that clear.",
            "storage_result": "The Chroma facade forwards through preload electronAction into URL-keyed WindowStorage. GET returns JSON rows for truthy values; SET returns the previous value and emits change events. hidden/running publication is not awaited, and neither state acknowledges installation, a native worker or device settings.",
            "cleanup": "The hidden-tab helper removes its create listener on existing-tab, create-event and ten-second timeout paths; a rejection is caught and does not itself remove that listener. ge has no componentWillUnmount and discards the tab-message disposer and internal desktop-icon listener. Preload pagehide separately removes IPC listeners. Ce has an empty-dependency effect with an initial-hidden early return; prop changes alone do not re-run that same effect instance.",
            "mount_identity": "The store starts with an empty user.item. The connected x renders span/renderView only while user.id is truthy; shouldLogin false-to-true only calls the account adapter. ge supplies no changing React key. If Ce first mounts after hidden has cleared it requests the installation wrapper. If Ce already mounted while hidden and user.id stays truthy, clearing hidden preserves that instance and does not restart its empty-dependency effect. A user-gate unmount/remount, error boundary or whole-page recreation is a separate path, not a guaranteed restore effect. Account behavior is retained source context and is excluded from this local-first product.",
            "installation_consumer": "The requested installation wrapper begins with showInstallation=true, checks Chroma and then background-manager and returns the actual page children only after showInstallation becomes false. WindowStorage installer-status events and initial first-row reads feed the phase reducer. Changed restart-required/skipped/completed values map to completed; the initial read normalizes only skipped/completed. These are coordinator states, not a device readback or verified installation result. Online installation/update orchestration is excluded from the product.",
            "lazy_consumer": "The actual lazy component depends on the lazy callback, returns its selected default export after resolution and records errors separately. Its effect cleanup only clears state; it does not cancel the promise or reject stale completions. The mounted content is module 23322's connected ja(ka), not the installation wrapper itself.",
            "content_cleanup": "ka removes dependent-app-status and its storage listener on unmount. Its exitApp response disposer and anonymous DOM listeners are not retained or removed there. The ja hook registers window-list-change and schedules a delayed close update without a returned cleanup. These selected source paths do not establish full callback release.",
        }, "selected_static_semantics_reviewed": True, "source_chain_complete": False,
        "target_execution": False, "actual_dll_comparison": "unverified",
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "runtime_acceptance": "unverified"}
    verify_chroma_dashboard_launch(audit, report)
    return report


def chroma_dashboard_mount_boundaries():
    """Keep conditional mount facts separate from execution or installation results."""
    return {
        "initial_user_has_id": False,
        "gate_renders_when": "truthy_user_id",
        "hidden_state_rekeys_gate": False,
        "should_login_update": "account_call_without_explicit_remount",
        "install_effect_dependencies": [],
        "hidden_install_effect": "clear_component_and_return_before_chunk_request",
        "restore_existing_instance_restarts_install_effect": False,
        "first_visible_mount": "request_install_wrapper",
        "installation_children": "show_installation_false_only",
        "installer_phase_source": "window_storage_event_or_initial_first_row",
        "changed_completed_statuses": ["restart-required", "skipped", "completed"],
        "initial_completed_statuses": ["skipped", "completed"],
        "installer_removed_events_ignored": True,
        "installer_listener_cleanup": "off_windowstorageevent",
        "installer_initial_read_canceled_on_cleanup": False,
        "lazy_effect_dependencies": ["lazy"],
        "lazy_cleanup_cancels_inflight": False,
        "content_removes_status_and_storage_listener": True,
        "content_retains_exit_response_disposer": False,
        "content_removes_anonymous_dom_listeners": False,
        "window_list_hook_returns_cleanup": False,
        "account_and_online_orchestration_in_product": False,
        "runtime_behavior_executed": False,
    }


