def _lighting_media_calculation_projection(report):
    return {name: report[name] for name in ("current_native_release", "native", "instruction_evidence",
        "boundaries", "fixed_vectors", "dependencies", "remaining_dependencies")}


def _verify_lighting_media_calculations(report):
    if report.get("boundaries") != _lighting_media_calculation_boundaries():
        raise ValueError("Media calculation boundary requires semantic review")
    if (report.get("schema_version") != 1 or report.get("query") != "lighting-media-calculations"
            or report.get("selected_calculations_reviewed") is not True
            or any(report.get(name) is not False for name in ("source_chain_complete", "target_execution",
                "product_code_modified", "real_device_operations"))
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "runtime_acceptance", "ui_backend_wiring"))
            or report.get("rust_independent_implementation") != "existing_not_revalidated"
            or report.get("failures") or report.get("changed_during_query") or report.get("snapshot_stable") is not True):
        raise ValueError("Media calculation static boundary was promoted or snapshot failed")
    native = report["native"]
    if (native["selected_pseudocode_failures"] or native["all_pseudocode_captured"] is not False
            or len(native["failures"]) != 10):
        raise ValueError("Media calculation capture failure was hidden")
    digest = hashlib.sha256(json.dumps(_lighting_media_calculation_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if digest != "044b35303c9822ce33bd7e545c9d4b20a8b52f207c92cba4d4e25b84fc95da68" or report.get("reviewed_selection_sha256") != digest:
        raise ValueError("Media calculation selected bytes require semantic review: " + digest)
    return {"selected_native_functions": len(native["complete_selected_functions"]),
        "selected_native_failures": 0, "global_native_failures_retained": 10,
        "pattern_ids_reviewed": list(range(1, 10)), "codec_resampler_complete": False,
        "actual_dll_comparison": "unverified", "reviewed_selection_sha256": digest}


