def _lighting_media_resampler_projection(report):
    return {name: report[name] for name in ("current_native_release", "native", "instruction_evidence",
        "boundaries", "reviewed_semantics", "fixed_vectors", "dependencies", "remaining_dependencies")}


def _verify_lighting_media_resampler(report):
    if report.get("boundaries") != _lighting_media_resampler_boundaries():
        raise ValueError("Media resampler boundary requires semantic review")
    if (report.get("schema_version") != 1 or report.get("query") != "lighting-media-resampler"
            or report.get("kind") != "current_lighting_media_resampler"
            or report.get("selected_resampler_semantics_reviewed") is not True
            or any(report.get(name) is not False for name in ("source_chain_complete", "target_execution",
                "product_code_modified", "real_device_operations"))
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "runtime_acceptance", "ui_backend_wiring"))
            or report.get("rust_independent_implementation") != "existing_not_revalidated"
            or report.get("failures") or report.get("changed_during_query") or report.get("snapshot_stable") is not True):
        raise ValueError("Media resampler static boundary was promoted or snapshot failed")
    native = report["native"]
    if (native["selected_pseudocode_failures"] or native["all_pseudocode_captured"] is not False
            or len(native["failures"]) != 10):
        raise ValueError("Media resampler capture failure was hidden")
    digest = hashlib.sha256(json.dumps(_lighting_media_resampler_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if digest != "cb5edf2721c2e677dffd060d5e9bf8ce490c29cd741266d56430821da1f5201c" or report.get("reviewed_selection_sha256") != digest:
        raise ValueError("Media resampler selected bytes require semantic review: " + digest)
    return {"selected_native_functions": len(native["complete_selected_functions"]),
        "verified_pointer_slots": len(native["verified_indirect_slots"]),
        "verified_direct_call_edges": len(native["verified_call_edges"]),
        "selected_native_failures": 0, "global_native_failures_retained": 10,
        "current_32x32_resampler_semantics_reviewed": True,
        "generic_resampler_codec_ai_complete": False, "actual_dll_comparison": "unverified",
        "reviewed_selection_sha256": digest}


