def _lighting_audio_effect_scope(catalog, routes):
    if (catalog.get("audio", {}).get("effect_id") != 12
            or routes.get("audio", {}).get("module_id") != 9120
            or routes.get("audio", {}).get("chunk_ids") != [606, 412]):
        raise ValueError("Audio effect mounted route requires semantic review")
    return {"effect_id": 12, "module_id": 9120, "chunk_ids": [606, 412],
        "mounted_controls": ["color_stops", "boost", "auto_boost", "decay"],
        "flow_control_mounted": False, "playback_control_mounted": False,
        "pcm_capture_inferred": False}


