def _lighting_ambient_screen_projection(report):
    owners = {row["id"]: row for row in report["complete_source_owners"]}
    selected = {}
    for role, key in report["selected"].items():
        row = owners[key]
        if hashlib.sha256(row["body"].encode("utf-8")).hexdigest() != row["body_sha256"]:
            raise ValueError("Ambient complete owner body differs")
        selected[role] = {name: row[name] for name in (
            "original", "syntax", "byte_start", "byte_end", "body_sha256")}
    return {"selected": selected, **{name: report[name] for name in (
        "exports", "bindings", "studio_catalog", "mounted_routes", "studio_scope", "current_native_release",
        "native", "region_native_provenance", "instruction_evidence", "boundaries", "reviewed_semantics", "dependencies")},
        "source_acquisitions": [row["acquisition"] for row in report["source_sets"]]}


def _verify_lighting_ambient_screen_claims(report):
    if report["boundaries"] != _lighting_ambient_screen_boundaries():
        raise ValueError("Ambient failure/lifecycle boundary differs")
    if (report.get("schema_version") != 1 or report.get("query") != "lighting-ambient-screen-chain"
            or report.get("selected_effect_semantics_reviewed") is not True
            or any(report.get(name) is not False for name in ("source_chain_complete", "target_execution",
                "product_code_modified", "real_device_operations"))
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "runtime_acceptance",
                "ui_backend_wiring")) or report.get("rust_independent_implementation") != "existing_not_revalidated"
            or report.get("failures") or report.get("changed_during_query") or report.get("snapshot_stable") is not True):
        raise ValueError("Ambient static review was promoted or its snapshot failed")
    if (report["native"]["selected_pseudocode_failures"]
            or report["native"]["all_pseudocode_captured"] is not False
            or len(report["native"]["failures"]) != 10):
        raise ValueError("Ambient native capture failure was hidden or a selected body failed")
    digest = hashlib.sha256(json.dumps(_lighting_ambient_screen_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if digest != "a5a0e1dfbf96c2b0962a46cd4bf8787b41b99ba691b9058920fc61b57cd1d9a8" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Ambient selected bytes require complete semantic review: " + digest)
    return {"selected_source_owners": len(report["selected"]),
        "selected_native_functions": len(report["native"]["complete_selected_functions"]),
        "actual_mounted_effect_ids": [11], "target_execution": False, "runtime_acceptance": "unverified"}


def collect_lighting_ambient_screen_chain(audit):
    """Trace mounted screen11 controls, the capture input and cached frame calculation."""
    import frontend
    studio = frontend.current_source_selection("https://apps.razer.com/synapse/chroma-studio/", audit,
        candidates=sorted((audit.a.ROOT / ".analysis/inputs/frontend").glob("synapse-chroma-studio*/acquisition.json")))
    originals = studio.pop("originals")
