    selected["native_wrapper_initialization"], = audit.retain("lighting_ambient_wrapper_initialization",
        initialization[0], "chromaStudioNative=new", {"function_declaration"})

    engine_set, engine_originals = audit.current_source_set("synapse-lighting-engine-current")
    mains = [row for row in engine_originals if Path(row["path"]).name.startswith("main.") and row["path"].endswith(".js")]
    if len(mains) != 1:
        raise ValueError("Ambient LE source is absent or ambiguous")
    main, = mains
    members = {}
    for role, module, name in (("engine_add_effect", 2578, "addEffect"), ("native_add_effect", 2198, "AddEffect")):
        factory, = audit.webpack_factories([main], module)
