def _profile_alternate_icon_calls(audit, originals, consumers):
    """Find actual named Alt calls, checking their complete consumers and sizes."""
    calls = []
    for original in originals:
        if Path(original["path"]).suffix != ".js" or b"getApplicationIconsAlt" not in audit.read(original):
            continue
        pending = [audit.tree(original).root_node]
        while pending:
            node = pending.pop()
            pending.extend(reversed(node.named_children))
            if node.type != "call_expression":
                continue
            callee = node.child_by_field_name("function")
            if callee.type == "member_expression":
                key = callee.child_by_field_name("property")
                name = key.text.decode("utf-8") if key is not None else None
            elif callee.type == "subscript_expression":
                key = callee.child_by_field_name("index")
                parts = key.named_children if key is not None and key.type == "string" else []
                name = parts[0].text.decode("utf-8") if len(parts) == 1 else None
            else:
                continue
            if name != "getApplicationIconsAlt":
                continue
            matches = [(role, owner, size) for role, (owner, size) in consumers.items()
                if owner["original"]["path"] == original["path"]
                and owner["byte_start"] <= node.start_byte < node.end_byte <= owner["byte_end"]]
            arguments = node.child_by_field_name("arguments").named_children
            if len(matches) != 1 or len(arguments) != 3:
                raise ValueError("Profile Alt call has an unreviewed consumer or arguments")
            role, owner, size = matches[0]
            if ([part.type for part in arguments[1:]] != ["number", "number"]
                    or [part.text.decode("ascii") for part in arguments[1:]] != [str(value) for value in size]):
                raise ValueError("Profile Alt consumer dimensions require semantic review: " + role)
            calls.append({"consumer": role, "owner_id": owner["id"], "original": original["path"],
                "byte_start": node.start_byte, "byte_end": node.end_byte, "size": list(size),
                "body_sha256": hashlib.sha256(node.text).hexdigest()})
    if sorted(row["consumer"] for row in calls) != sorted(consumers):
        raise ValueError("Profile Alt calls are missing or duplicated")
    return calls


