def _profile_alternate_icons_projection(report):
    owners = {row["id"]: row for row in report["complete_source_owners"]}
    selected = {}
    for role, key in report["selected"].items():
        row = owners[key]
        if hashlib.sha256(row["body"].encode("utf-8")).hexdigest() != row["body_sha256"]:
            raise ValueError("Profile Alt complete owner body differs")
        selected[role] = {name: row[name] for name in ("original", "syntax", "byte_start", "byte_end", "body_sha256")}
    return {"selected": selected, "bindings": report["bindings"], "exports": report["cross_chunk_exports"],
        "native": report["native"], "calls": report["actual_alt_calls"], "ffi": report["ffi_declarations"],
        "host_release": report["host_release"], "frontend_acquisition": report["source_set"]["acquisition"],
        "macos_native": report["macos_native"], "dependencies": report["dependencies"]}


def _verify_profile_alternate_icons_claims(report):
    if report["boundaries"] != _profile_alternate_icons_boundaries():
        raise ValueError("Profile Alt failure/platform boundary differs")
    if (report.get("schema_version") != 1 or report.get("query") != "profile-alternate-icons"
            or report.get("windows_source_chain_complete") is not True or report.get("source_chain_complete") is not False
            or report.get("whole_profiles_complete") is not False or report.get("target_execution") is not False
            or report.get("real_device_operations") is not False or report.get("product_code_modified") is not False
            or any(report.get(field) != "unverified" for field in ("actual_dll_comparison",
                "rust_independent_implementation", "ui_backend_wiring", "runtime_acceptance"))
            or report.get("failures") or report.get("changed_during_query") or report.get("snapshot_stable") is not True):
        raise ValueError("Profile Alt static review was promoted or its snapshot failed")
    native = report["native"]
    if (native["selected_pseudocode_failures"] or native["all_pseudocode_captured"] is not False
            or [row["stage"] for row in native["failures"]] != ["abcbc:hexrays"]):
        raise ValueError("Profile Alt native capture failure was hidden or a selected body failed")
    digest = hashlib.sha256(json.dumps(_profile_alternate_icons_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if digest != "04416f52c6de2f18faee6165f354ab24b9a00a6b45644206b13794fa258338f9" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Profile Alt selected bytes require complete semantic review: " + digest)
    return {"selected_source_owners": len(report["selected"]),
        "selected_native_functions": len(native["complete_selected_functions"]),
        "actual_alt_consumers": len(report["actual_alt_calls"]), "target_execution": False,
        "scope": report["boundaries"]["scope"], "macos_native": "unverified", "runtime_acceptance": "unverified"}


