def _profile_scanner_method_key(row):
    header = row["complete_il"].split("// Method begins at RVA", 1)[0]
    return "/".join(row["class_ancestry"]) + "|" + " ".join(header.split())


def _profile_scanner_user_heap(metadata):
    import struct
    raw = metadata["read"](int(metadata["pe"]["clr"]["metadata_rva"], 16), metadata["pe"]["clr"]["metadata_bytes"])
    position = (16 + struct.unpack_from("<I", raw, 12)[0] + 3) & ~3
    count = struct.unpack_from("<H", raw, position + 2)[0]
    position += 4
    heaps = []
    for _ in range(count):
        offset, size = struct.unpack_from("<II", raw, position)
        finish = raw.index(0, position + 8)
        if raw[position + 8:finish] == b"#US":
            heaps.append(raw[offset:offset + size])
        position = (finish + 4) & ~3
    if len(heaps) != 1:
        raise ValueError("Scanner version original user-string heap is absent or ambiguous")
    return heaps[0]


def _profile_scanner_user_string(heap, token):
    if token >> 24 != 0x70:
        raise ValueError("Scanner version ldstr token is not a user string")
    offset = token & 0xffffff
    lead = heap[offset]
    if lead < 0x80:
        size, start = lead, offset + 1
    elif lead < 0xc0:
        size, start = ((lead & 0x3f) << 8) | heap[offset + 1], offset + 2
    elif lead < 0xe0:
        size, start = ((lead & 0x1f) << 24) | int.from_bytes(heap[offset + 1:offset + 4], "big"), offset + 4
    else:
        raise ValueError("Scanner version original string length is invalid")
    data = heap[start:start + size]
    if size < 1 or size % 2 != 1 or len(data) != size or data[-1] not in (0, 1):
        raise ValueError("Scanner version original user string is truncated or invalid")
    return {"token": hex(token), "heap_offset": offset, "raw_utf16_hex": data[:-1].hex(),
            "value": data[:-1].decode("utf-16-le"), "terminal_flag": data[-1]}


def _profile_scanner_token_ranges(row, heap):
    """Mask only independently checked ECMA-335 metadata-token operands."""
    encodings = {"jmp": "27", "call": "28", "calli": "29", "callvirt": "6f", "cpobj": "70", "ldobj": "71",
        "ldstr": "72", "newobj": "73", "castclass": "74", "isinst": "75", "unbox": "79", "ldfld": "7b",
        "ldflda": "7c", "stfld": "7d", "ldsfld": "7e", "ldsflda": "7f", "stsfld": "80", "stobj": "81",
        "box": "8c", "newarr": "8d", "ldelema": "8f", "ldelem": "a3", "stelem": "a4", "unbox.any": "a5",
        "refanyval": "c2", "mkrefany": "c6", "ldtoken": "d0", "ldftn": "fe06", "ldvirtftn": "fe07",
        "initobj": "fe15", "constrained.": "fe16", "sizeof": "fe1c"}
    code = bytes.fromhex(row["raw_code_hex"])
    if len(code) != row["code_size"] or hashlib.sha256(code).hexdigest() != row["raw_code_sha256"]:
        raise ValueError("Scanner version original method code identity differs")
    masked = bytearray(code)
    ranges = []
    for index, instruction in enumerate(row["instructions"]):
        if instruction["opcode"] not in encodings:
            continue
        encoded = bytes.fromhex(encodings[instruction["opcode"]])
        start = instruction["offset"]
        finish = row["instructions"][index + 1]["offset"] if index + 1 < len(row["instructions"]) else len(code)
        if code[start:start + len(encoded)] != encoded or finish != start + len(encoded) + 4:
            raise ValueError("Scanner version token operand opcode or extent differs")
        at = start + len(encoded)
        token = int.from_bytes(code[at:at + 4], "little")
        entry = {"offset": start, "operand_start": at, "operand_end": at + 4,
            "opcode": instruction["opcode"], "token": hex(token), "captured_operand": instruction["operand"]}
        if instruction["opcode"] == "ldstr":
            entry["original_user_string"] = _profile_scanner_user_string(heap, token)
        ranges.append(entry)
        masked[at:at + 4] = b"\x00" * 4
    return {"token_operands": ranges, "masked_code_hex": masked.hex(),
            "masked_code_sha256": hashlib.sha256(masked).hexdigest()}


def _profile_scanner_compare(old, new):
    def semantics(row):
        exceptions = [{key: clause[key] for key in ("flags", "try_offset", "try_length", "handler_offset", "handler_length")}
            for section in row["exception_sections"] for clause in section["clauses"]]
        strings = [(entry["offset"], entry["original_user_string"]["value"]) for entry in row["token_operands"]
                   if "original_user_string" in entry]
        return {"instructions": row["instructions"], "exception_ranges": exceptions, "user_strings": strings,
            "call_targets": [{key: call["resolved_method"].get(key) for key in ("name", "declaring_type", "generic_type_arguments")}
                if call["resolved_method"] else None for call in row["calls"]]}
    left, right = semantics(old), semantics(new)
    instructions_same = left["instructions"] == right["instructions"]
    ranges_same = left["exception_ranges"] == right["exception_ranges"]
    strings_same = left["user_strings"] == right["user_strings"]
    calls_same = left["call_targets"] == right["call_targets"]
    masked_same = old["masked_code_hex"] == new["masked_code_hex"]
    normalize = lambda row: re.sub(r"// Method begins at RVA 0x[0-9a-fA-F]+", "// Method begins at reviewed RVA", row["complete_il"])
    declarations_same = normalize(old) == normalize(new)
    return {"key": _profile_scanner_method_key(old), "old_token": old["token"], "new_token": new["token"],
        "old_rva": old["rva"], "new_rva": new["rva"], "old_code_sha256": old["raw_code_sha256"],
        "new_code_sha256": new["raw_code_sha256"], "original_code_identical": old["raw_code_hex"] == new["raw_code_hex"],
        "instructions_identical": instructions_same, "exception_ranges_identical": ranges_same,
        "original_user_strings_identical": strings_same, "resolved_call_targets_identical": calls_same,
        "non_token_bytes_identical": masked_same, "complete_il_except_rva_identical": declarations_same,
        "classification": "same_selected_method_after_metadata_relocation" if all((instructions_same, ranges_same,
            strings_same, calls_same, masked_same, declarations_same)) else "changed_selected_method"}


def _profile_scanner_review_changes(assemblies):
    current = [row for assembly in assemblies if assembly["version"] == "3.15.0.1200" for row in assembly["complete_methods"]]
    edges = []

    def select(root, name):
        rows = [row for row in current if row["class_ancestry"][0].split(".")[-1] == root
                and len(row["class_ancestry"]) == 1 and row["name"] == name]
        if len(rows) != 1:
            raise ValueError("Scanner version changed complete method is absent or ambiguous: " + root + "." + name)
        return rows[0]

    def require(root, name, target, *, expected_count=None):
        method = select(root, name)
        calls = [row for row in method["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == target]
        if not calls or expected_count is not None and len(calls) != expected_count:
            raise ValueError("Scanner version changed actual call edge differs: " + root + "." + name + " -> " + target)
        edges.extend({"caller_token": method["token"], "caller_rva": method["rva"], "caller": root + "." + name,
                      "offset": row["offset"], "bytes": row["bytes"], "target": row["resolved_method"]} for row in calls)

    riot, uplay = "GameScannerStrategyRiotPlatformSearch", "GameScannerStrategyUplayConfigurationSearch"
    for method, target in (("DecodeUnicodeEscapes", "DecodeUnicodeEscapeMatch"),
            ("DecodeUnicodeEscapeMatch", "ToUInt16"), ("DecodeUnicodeEscapeMatch", "ToInt32"),
            ("DecodeUnicodeEscapeMatch", "ConvertFromUtf32")):
        require(riot, method, target)
    for method, target in (("GetInstalledUplayGames", "GetUplayGameDirectories"),
            ("FindMatchingUplayData", "FirstOrDefault"), ("TryAddUplayGame", "ResolveUplayLaunchExe"),
            ("TryAddUplayGame", "FileExists"), ("TryAddUplayGame", "CreateUplayEntryGuid"),
            ("TryAddUplayGame", "GetUplayLaunchUrl"), ("TryAddUplayGame", "AddFoundGame"),
            ("ResolveUplayLaunchExe", "TryResolveConfiguredLaunchExe"), ("ResolveUplayLaunchExe", "TryFindFallbackLaunchExe"),
            ("TryResolveConfiguredLaunchExe", "GetConfiguredExecutablePath"), ("GetConfiguredExecutablePath", "GetFullPath"),
            ("TryFindFallbackLaunchExe", "GetFiles"), ("TryFindFallbackLaunchExe", "OrderBy"),
            ("TryFindFallbackLaunchExe", "ThenBy"), ("GetFallbackLaunchExeRank", "NormalizeFallbackExeName")):
        require(uplay, method, target)
    matching = select(uplay, "FindMatchingUplayData")
    if len([row for row in matching["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == "FirstOrDefault"]) != 5:
        raise ValueError("Scanner version Uplay matching priority is not five actual passes")
    rank = select(uplay, "GetFallbackLaunchExeRank")
    returns = []
    code = bytes.fromhex(rank["raw_code_hex"])
    for previous, instruction in zip(rank["instructions"], rank["instructions"][1:]):
        if instruction["opcode"] == "ret" and previous["opcode"] in {"ldc.i4." + str(index) for index in range(5)}:
            value = int(previous["opcode"][-1])
            if code[previous["offset"]:instruction["offset"] + 1] != bytes((0x16 + value, 0x2a)):
                raise ValueError("Scanner version Uplay ranking return is not original constant IL")
            returns.append(value)
    if returns != [0, 1, 2, 3, 4]:
        raise ValueError("Scanner version Uplay ranking constant order differs")
    display = select(uplay, "GetUplayDisplayName")
    display_strings = [row["original_user_string"] for row in display["token_operands"] if "original_user_string" in row]
    if [row["value"] for row in display_strings] != ["?", "?", "?", "?"]:
        raise ValueError("Scanner version current Uplay display markers require new review")
    regex = select(riot, ".cctor")
    patterns = [row["original_user_string"] for row in regex["token_operands"] if "original_user_string" in row]
    if len(patterns) != 1 or patterns[0]["value"] != r"\\u([dD][89aAbB][0-9a-fA-F]{2})\\u([dD][c-fC-F][0-9a-fA-F]{2})|\\(?:x([0-9a-fA-F]{2})|u([0-9a-fA-F]{4})|U([0-9a-fA-F]{8}))":
        raise ValueError("Scanner version current Riot original regex differs")
    return {"verified_changed_call_edges": edges,
        "riot": {"regex_from_original_user_heap": patterns[0], "decoder_token": select(riot, "DecodeUnicodeEscapeMatch")["token"],
            "decoder_exception_sections": select(riot, "DecodeUnicodeEscapeMatch")["exception_sections"],
            "complete_method_names": [row["name"] for row in current if row["class_ancestry"][0].split(".")[-1] == riot]},
        "uplay": {"matching_method_token": matching["token"], "matching_passes": 5,
            "rank_method_token": rank["token"], "original_rank_returns": returns, "display_literals": display_strings,
            "complete_method_names": [row["name"] for row in current if row["class_ancestry"][0].split(".")[-1] == uplay]},
        "shared_unselected": "GetAllPossibleFilenames owner has span Contains change; selected GetComponents compared separately",
        "service_source_difference": "10 retained C# diagnostics, including RegisterService analytics casts; selected RegisterService IL comparison retained separately"}


def _profile_scanner_boundaries():
    return {
        "scope": "Seven previously reviewed Windows strategies from GMS 3.14 to 3.15; GOG and shared lifecycle reused",
        "equivalence": {"whole_dll_or_product_equivalence": False, "rva_or_class_name_sufficient": False,
            "original_bytes_masked_only_at_checked_token_operands": True,
            "changed_strings_masked_as_equivalent": False, "whole_IL_independently_decoded": False,
            "all_field_type_signature_or_TypeSpec_metadata_independently_decoded": False,
            "framework_runtime_equivalence_proven": False},
        "riot": {"old_escape": "single backslash-u plus four hex UTF-16 unit", "new_escape": "surrogate pair, x2, u4, U8",
            "pair": "two validated surrogate UTF-16 chars in a new string", "scalar": "Convert.ToInt32 hex then Char.ConvertFromUtf32",
            "argument_or_overflow": "return original matched text", "format_exception_caught": False,
            "file_read_error": "return collected prefix without later normalization", "stop_or_disposal_added": False},
        "uplay": {"preload_order": ["GetUplayData(false)", "GetInstalledUplayGames", "GetUplayRegistryGuids"],
            "installed_nonempty": "iterate installed records only", "installed_empty": "iterate configuration records only",
            "matched_config_reused": True, "config_match_order": ["GameId exact", "Name exact", "GameNameIdentifier exact",
                "Name contains either direction", "GameNameIdentifier contains either direction"],
            "comparison": "CurrentCultureIgnoreCase", "unmatched_installed": "new config Name=DisplayName GameId=installed.GameId",
            "configured_executables": "only first offline then first online", "installed_path": "installed.GetFullPath(DirectoryAppend,RelativePath)",
            "fallback_condition": "configured path null/empty/missing; installed entry present; no preceding exception",
            "fallback_enumeration": "recursive *.exe; exclude unins prefix/uninstall contains/UbisoftConnect.exe/Uplay.exe",
            "fallback_order": ["normalized displayname+game", "normalized displayname", "non-EAC name contains displayname",
                "other non-EAC", "EAC or EasyAntiCheat"], "fallback_tiebreak": "separator count then string length, then existing enumeration order",
            "normalization": "UTF-16 char.IsLetterOrDigit; no separate sort or existence inference",
            "fallback_directory_check_inside_catch": False, "fallback_file_query_has_stop_token": False,
            "registry_null_guard_added": True, "empty_launch_url_mapping_skipped": True,
            "display_name_removed_marks": ["?", "?"], "helper_TryUpdate_result_checked": False,
            "stop": "before each installed/config item; preloads and recursive fallback not cancellable",
            "clear": "only configuration list on normal tail; not finally", "per_item_path_and_publish_catches": True,
            "rollback_or_atomic_mapping_publish_added": False},
        "dependencies": {"gog_and_shared_dispatch_reanalyzed": False, "native_icons_reanalyzed": False,
            "unselected_GetAllPossibleFilenames_changed": "Enumerable Contains to ReadOnlySpan Contains; outside selected GetComponents",
            "service_all_csharp_resolved": False, "service_diagnostic_count": 10,
            "device_or_disk_success_from_version_match": False}}


def _profile_scanner_projection(report):
    return {key: report[key] for key in ("host_release", "capture", "assemblies", "comparisons", "source_comparisons",
        "registration", "dependencies", "reviewed_changes", "boundaries")}


def _verify_profile_scanner_version_differences(report):
    if report.get("boundaries") != _profile_scanner_boundaries():
        raise ValueError("Scanner version failure, equivalence or lifecycle boundary differs")
    if (report.get("query") != "profile-scanner-version-differences" or report.get("schema_version") != 1
            or report.get("selected_version_comparison_complete") is not True or report.get("source_chain_complete") is not False
            or report.get("whole_profiles_complete") is not False or report.get("target_execution") is not False
            or report.get("product_code_modified") is not False or report.get("real_device_operations") is not False
            or report.get("snapshot_stable") is not True or report.get("changed_during_query") or report.get("failures")
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "rust_independent_implementation",
                "ui_backend_wiring", "runtime_acceptance"))):
        raise ValueError("Scanner version static evidence was promoted or snapshot failed")
    digest = hashlib.sha256(json.dumps(_profile_scanner_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if digest != "8e78ac3e39a7969d0b715e022cacf4fa8cd28c1bf57cba00b0f0d466af3a3037" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Scanner version selected bytes require complete semantic review: " + digest)
    classifications = {}
    for row in report["comparisons"]:
        classifications[row["classification"]] = classifications.get(row["classification"], 0) + 1
    return {"strategy_branches": 7, "newly_compared_strategies": 6, "reused_gog_strategy": True,
        "complete_managed_methods": sum(len(row["complete_methods"]) for row in report["assemblies"]),
        "comparison_classes": classifications, "reviewed_changes": ["Riot Unicode decoding", "Uplay installed-game scanning"],
        "target_execution": False, "runtime_acceptance": "unverified"}


def collect_profile_scanner_version_differences(audit):
    """Compare the retained local strategies without repeating GOG or shared dispatch."""
    import difflib
    upstream = json.loads((audit.a.ROOT / ".analysis/results/host-current/local-audit.json").read_bytes())["profile_gog_scanner"]
    _verify_profile_gog_claims(upstream)
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    if release["version"] != upstream["host_release"]["version"]:
        raise ValueError("Scanner version shared-chain host release changed")
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    package = upstream["host_release"]["official_gms_package"]
    if not any(row.get("path") == package["path"] and row.get("sha256") == package["sha256"]
               and row.get("manifest_identity_verified") for row in release["files"]):
        raise ValueError("Scanner version current GMS package ancestry differs")
    audit.artifact(audit.a.ROOT / package["path"], package)
    for dependency in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / dependency["path"], dependency)
    capture_path = audit.a.ROOT / ".analysis/results/host-current/managed/capture.json"
    capture = json.loads(audit.artifact(capture_path))
    if capture.get("target_execution") is not False:
        raise ValueError("Scanner version managed capture is not static")
    scope, strategies = _profile_scanner_scope()
    old_digests = {"GameManagerServiceLib.dll": "955d4bbd372fab1e582da5ce955a3a94baeb0b6d1c17be976fe391cfc19513cc",
        "GameScannerCommon.dll": "e07813af888b037b686216246e4f4c4484c9b609b731e66bea5c1047410a5d15",
        "GameManagerService3.dll": "3aa42301ef787b3eedc56f699830212cc339d90841c97014ddd7a6f9364877d6"}
    assemblies, source_maps = [], {}
    for version, is_current in (("3.14.0.1109", False), ("3.15.0.1200", True)):
        for filename, selectors in scope.items():
            if is_current:
                originals = [row for row in current_host_extracted_inputs(indexed, release)
                    if row["container_sha256"] == package["sha256"] and Path(row["path"]).name == filename]
            else:
                originals = [row for row in indexed["inputs"] if row["sha256"] == old_digests[filename]
                    and row["path"].startswith(".analysis/inputs/host-current/extracted/")]
            if len(originals) != 1:
                raise ValueError("Scanner version original is absent or ambiguous: " + version + "/" + filename)
            original, = originals
            raw = audit.read(original)
            parents = [row for row in indexed["inputs"] if row["path"] == original["container"]
                       and row["sha256"] == original["container_sha256"]]
            if len(parents) != 1:
                raise ValueError("Scanner version original official package ancestor is absent or ambiguous")
            parent, = parents
            audit.read(parent)
            bindings = [row for row in capture["assemblies"] if row["input_sha256"] == original["sha256"]]
            if len(bindings) != 1:
                raise ValueError("Scanner version selected capture is absent")
            record, = bindings
            acquired = [row for row in record["acquisition_bindings"] if row["path"] == original["path"]]
            if len(acquired) != 1 or any(acquired[0][key] != original[key] for key in ("bytes", "sha256", "container", "container_sha256")):
                raise ValueError("Scanner version captured acquisition identity differs")
            if not record["capture_complete"] or not record["input_bytes_unchanged"]:
                raise ValueError("Scanner version selected managed capture failed")
            metadata = _profile_gog_clr(raw)
            if [row["tree"].get("file_version") for row in metadata["pe"]["version_resources"]] != [version]:
                raise ValueError("Scanner version original file version differs")
            il_artifact, = [row for row in record["outputs"] if row["path"].endswith("/il.stdout.txt")]
            sources = []
            for class_name in selectors:
                artifact, = [row for row in record["outputs"] if row["path"].endswith("/" + class_name + ".cs")]
                body = audit.artifact(audit.a.ROOT / artifact["path"], artifact).decode("utf-8-sig")
                sources.append({"class": class_name, "artifact": artifact, "complete_source": body})
                source_maps[version, class_name] = sources[-1]
            selections = {name: choices if choices is not None else tuple(sorted({row["name"] for row in metadata["methods"].values()
                if row["declaring_type"].endswith("." + name)})) + ("<",) for name, choices in selectors.items()}
            if is_current and filename == "GameManagerService3.dll":
                retained = upstream["managed"]["assemblies"][-1]
                if retained["original"] != original:
                    raise ValueError("Scanner version reused service original differs")
                methods = retained["complete_methods"]
                il_reused = True
            else:
                il = audit.artifact(audit.a.ROOT / il_artifact["path"], il_artifact).decode("utf-8-sig")
                methods = _profile_gog_il_methods(original, il, metadata, selections)
                il_reused = False
            heap = _profile_scanner_user_heap(metadata)
            methods = [{**row, **_profile_scanner_token_ranges(row, heap)} for row in methods]
            if set(selectors) != {row["class_ancestry"][0].split(".")[-1] for row in methods}:
                raise ValueError("Scanner version selected complete method set is missing a class")
            assemblies.append({"version": version, "original": original,
                "official_package_original": parent,
                "capture_input": {key: record[key] for key in ("input", "input_sha256", "input_bytes", "capture_complete", "all_csharp_resolved", "diagnostics")},
                "complete_source_owners": sources, "complete_methods": methods, "il_artifact": il_artifact,
                "service_methods_reused_from_gog": il_reused})
    comparisons = []
    for filename in scope:
        old, new = [next(row for row in assemblies if row["version"] == version and Path(row["original"]["path"]).name == filename)
                    for version in ("3.14.0.1109", "3.15.0.1200")]
        before = {_profile_scanner_method_key(row): row for row in old["complete_methods"]}
        after = {_profile_scanner_method_key(row): row for row in new["complete_methods"]}
        if len(before) != len(old["complete_methods"]) or len(after) != len(new["complete_methods"]):
            raise ValueError("Scanner version complete method identity is ambiguous")
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after:
                method = after.get(key, before.get(key))
                comparisons.append({"assembly": filename, "key": key, "token": method["token"], "rva": method["rva"],
                    "classification": "added_selected_method" if key not in before else "removed_selected_method"})
            else:
                comparisons.append({"assembly": filename, **_profile_scanner_compare(before[key], after[key])})
    source_comparisons = []
    for class_name in sorted({name for _, name in source_maps}):
        old, new = (source_maps[version, class_name] for version in ("3.14.0.1109", "3.15.0.1200"))
        source_comparisons.append({"class": class_name, "old_artifact": old["artifact"], "new_artifact": new["artifact"],
            "complete_source_bytes_equal": old["artifact"]["sha256"] == new["artifact"]["sha256"],
            "complete_diff": "\n".join(difflib.unified_diff(old["complete_source"].splitlines(), new["complete_source"].splitlines(),
                fromfile=old["artifact"]["path"], tofile=new["artifact"]["path"], n=3))})
    current_service = assemblies[-1]["complete_methods"][0]
    registration = []
    for strategy in strategies + ["GameScannerStrategyGogRegistrySearch"]:
        calls = [row for row in current_service["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == "AddScoped"
            and row["resolved_method"].get("generic_type_arguments") == ["Razer.GameManagerServiceLib.IGameScannerStrategy",
                "Razer.GameManagerServiceLib." + strategy]]
        if len(calls) != 1:
            raise ValueError("Scanner version actual current strategy registration differs: " + strategy)
        registration.append({"strategy": strategy, "caller_token": current_service["token"], **calls[0]})
    report = {"schema_version": 1, "query": "profile-scanner-version-differences", "kind": "current_profile_scanner_version_differences",
        "host_release": {"version": release["version"], "receipt": release["receipt"], "official_gms_package": package},
        "capture": {"identity": audit.families.identity(capture_path), "analyzer": capture["tool"]},
        "assemblies": assemblies, "comparisons": comparisons, "source_comparisons": source_comparisons,
        "registration": registration, "boundaries": _profile_scanner_boundaries(),
        "reviewed_changes": _profile_scanner_review_changes(assemblies),
        "dependencies": [{"receipt": ".analysis/results/host-current/local-audit.json", "section": "profile_gog_scanner",
            "section_sha256": hashlib.sha256(json.dumps(upstream, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest(),
            "reused": ["GOG strategy", "shared dispatch/stop/post-scan dedup", "actual current frontend list consumers", "icon boundary"],
            "remaining_chains": upstream["remaining_chains"]}],
        "selected_version_comparison_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "target_execution": False, "product_code_modified": False, "real_device_operations": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified", "failures": [],
        "complete_originals": list(audit.sources.values()), "complete_source_owners": [], "selected": {},
        "verified_artifacts": list(audit.artifacts.values()), "changed_during_query": audit.final_snapshot()}
    report["snapshot_stable"] = not report["changed_during_query"]
    report["remaining_chains"] = ["Other current GMS scan strategies and their actual input/Reader dependencies",
        "Unselected GameSignatureHelper.GetAllPossibleFilenames span comparison and affected callers",
        "Independent Rust implementation, UI/backend wiring and automated behavior tests",
        "Actual DLL/service/device comparison and runtime acceptance"]
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_scanner_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    report["verification"] = _verify_profile_scanner_version_differences(report)
    return report


def _profile_store_scope():
    strategies = ["GameScannerStrategy" + name for name in (
        "SteamLibrarySearch", "SteamShortcutsSearch", "BattleNetSearchV2", "EpicLauncherInstalledList")]
    lib = {name: None for name in strategies[1:]}
    lib[strategies[0]] = (".ctor", ".cctor", "<>n__0", "ScanAsync", "<ScanAsync>", "GetLibraryFolders",
        "GetEntryGuid", "GetNewGuid", "FindExactMatch", "GetPossibleExePath", "IsLaunchExeExists",
        "GetSteamGameInfoFromSteamServer", "<GetSteamGameInfoFromSteamServer>")
    lib.update({name: None for name in ("GameScannerStrategySteamBase", "SteamHelper", "SteamAppInfoData",
        "SteamAppManifest", "SteamLibraryFolders", "SteamLibraryFolders2", "BattleNetAgentLogParser",
        "BattleNetGameDataV2", "EpicLauncherInstalledGamesReader", "EpicGameManifest", "EpicInstalledGame",
        "EpicLauncherInstalledData")})
    lib["SteamCmdProcessor"] = (".ctor", ".cctor", "IsSupportedSteamAppAGame", "<IsSupportedSteamAppAGame>",
        "GetSteamInfoFromSqlite", "<GetSteamInfoFromSqlite>", "AddSteamInfoToSqlite", "<AddSteamInfoToSqlite>",
        "SteamAppInfoToDBAdapter", "<SteamAppInfoToDBAdapter>", "SteamAppForDBToAppInfoAdapter",
        "<SteamAppForDBToAppInfoAdapter>", "LaunchDataDBToSteamAppInfoLaunch", "<LaunchDataDBToSteamAppInfoLaunch>")
    common = {name: None for name in ("SteamDataDeserializers", "SteamDataToJsonConvertSerializer",
        "SteamShortcutsDeserializer", "SteamShortcut")}
    common["NewtonsoftJsonSerializer"] = (".ctor", "DeserializePath", "DeserializeString")
    return {"GameManagerServiceLib.dll": lib, "GameScannerCommon.dll": common}, strategies


def _profile_store_managed(audit, previous):
    """Reuse verified complete captures; select only this store/launcher group."""
    import difflib
    capture_path = audit.a.ROOT / ".analysis/results/host-current/managed/capture.json"
    capture = json.loads(audit.artifact(capture_path, previous["capture"]["identity"]))
    if capture.get("target_execution") is not False:
        raise ValueError("Store scanner managed capture is not static")
    index = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=index)
    if (release["version"] != previous["host_release"]["version"]
            or release["receipt"] != previous["host_release"]["receipt"]):
        raise ValueError("Store scanner current host release differs")
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for artifact in [previous["host_release"]["official_gms_package"], *release["verified_dependencies"]]:
        audit.artifact(audit.a.ROOT / artifact["path"], artifact)
    scope, _ = _profile_store_scope()
    assemblies, source_maps = [], {}
    for version in ("3.14.0.1109", "3.15.0.1200"):
        for filename, selectors in scope.items():
            retained, = [row for row in previous["assemblies"] if row["version"] == version
                         and Path(row["original"]["path"]).name == filename]
            original = retained["original"]
            indexed, = [row for row in index["inputs"] if row["path"] == original["path"]]
            if indexed != original:
                raise ValueError("Store scanner original index identity differs")
            raw = audit.read(original)
            parent = retained["official_package_original"]
            audit.read(parent)
            record, = [row for row in capture["assemblies"] if row["input_sha256"] == original["sha256"]]
            acquired, = [row for row in record["acquisition_bindings"] if row["path"] == original["path"]]
            if (any(acquired[key] != original[key] for key in ("bytes", "sha256", "container", "container_sha256"))
                    or not record["capture_complete"] or not record["input_bytes_unchanged"]
                    or not record["all_csharp_resolved"] or record["diagnostics"]):
                raise ValueError("Store scanner selected managed capture failed")
            metadata = _profile_gog_clr(raw)
            if [row["tree"].get("file_version") for row in metadata["pe"]["version_resources"]] != [version]:
                raise ValueError("Store scanner original file version differs")
            sources = []
            for class_name in selectors:
                artifact, = [row for row in record["outputs"] if row["path"].endswith("/" + class_name + ".cs")]
                source = audit.artifact(audit.a.ROOT / artifact["path"], artifact).decode("utf-8-sig")
                sources.append({"class": class_name, "artifact": artifact, "complete_source": source})
                source_maps[version, class_name] = sources[-1]
            il_artifact, = [row for row in record["outputs"] if row["path"].endswith("/il.stdout.txt")]
            il = audit.artifact(audit.a.ROOT / il_artifact["path"], il_artifact).decode("utf-8-sig")
            selections = {name: choices if choices is not None else tuple(sorted({row["name"]
                for row in metadata["methods"].values() if row["declaring_type"].endswith("." + name)})) + ("<",)
                for name, choices in selectors.items()}
            methods = _profile_gog_il_methods(original, il, metadata, selections)
            heap = _profile_scanner_user_heap(metadata)
            methods = [{**row, **_profile_scanner_token_ranges(row, heap)} for row in methods]
            if set(selectors) != {row["class_ancestry"][0].split(".")[-1] for row in methods}:
                raise ValueError("Store scanner complete method selection omits a class")
            assemblies.append({"version": version, "original": original, "official_package_original": parent,
                "capture_input": {key: record[key] for key in ("input", "input_sha256", "input_bytes",
                    "capture_complete", "all_csharp_resolved", "diagnostics")}, "il_artifact": il_artifact,
                "complete_source_owners": sources, "complete_methods": methods})
    comparisons = []
    for filename in scope:
        old, new = [next(row for row in assemblies if row["version"] == version
                        and Path(row["original"]["path"]).name == filename) for version in ("3.14.0.1109", "3.15.0.1200")]
        before = {_profile_scanner_method_key(row): row for row in old["complete_methods"]}
        after = {_profile_scanner_method_key(row): row for row in new["complete_methods"]}
        if len(before) != len(old["complete_methods"]) or len(after) != len(new["complete_methods"]):
            raise ValueError("Store scanner complete method identity is ambiguous")
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after:
                method = after.get(key, before.get(key))
                comparisons.append({"assembly": filename, "key": key, "token": method["token"], "rva": method["rva"],
                    "classification": "added_selected_method" if key not in before else "removed_selected_method"})
            else:
                comparisons.append({"assembly": filename, **_profile_scanner_compare(before[key], after[key])})
    sources = []
    for name in sorted({name for _, name in source_maps}):
        old, new = (source_maps[version, name] for version in ("3.14.0.1109", "3.15.0.1200"))
        sources.append({"class": name, "old_artifact": old["artifact"], "new_artifact": new["artifact"],
            "complete_source_bytes_equal": old["artifact"]["sha256"] == new["artifact"]["sha256"],
            "complete_diff": "\n".join(difflib.unified_diff(old["complete_source"].splitlines(), new["complete_source"].splitlines(),
                fromfile=old["artifact"]["path"], tofile=new["artifact"]["path"], n=3))})
    return {"assemblies": assemblies, "comparisons": comparisons, "source_comparisons": sources,
        "capture": {"identity": audit.families.identity(capture_path), "analyzer": capture["tool"]}}


def _profile_store_registration(audit, previous):
    service, = [row for row in previous["assemblies"] if row["version"] == "3.15.0.1200"
                and row["original"]["path"].endswith("/GameManagerService3.dll")]
    audit.read(service["original"])
    audit.read(service["official_package_original"])
    audit.artifact(audit.a.ROOT / service["il_artifact"]["path"], service["il_artifact"])
    for source in service["complete_source_owners"]:
        audit.artifact(audit.a.ROOT / source["artifact"]["path"], source["artifact"])
    method, = service["complete_methods"]
    _, current = _profile_store_scope()
    prior = {row["strategy"] for row in previous["registration"]}
    expected = ["GameScannerStrategy" + name for name in ("ArcRegistrySearch", "BattleNetSearchV2", "BethesdaRegistry",
        "DefaultExeSearch", "DefaultRegistryKey", "EARegistrySearch", "EpicLauncherInstalledList", "RiotPlatformSearch",
        "MihoyoPlatformSearch", "FeverPlatformSearch", "GameUXInfoSearch", "GameUXRegistrySearch", "GogRegistrySearch",
        "ItchIoSearch", "RegistrySearch", "SteamLibrarySearch", "SteamShortcutsSearch", "TwitchSearch", "UninstallSearch",
        "UplayConfigurationSearch", "UserFolderExeSearch", "UwpSearch")]
    calls = [row for row in method["calls"] if row["resolved_method"]
        and row["resolved_method"]["name"] == "AddScoped"
        and (row["resolved_method"].get("generic_type_arguments") or [None])[0] == "Razer.GameManagerServiceLib.IGameScannerStrategy"]
    if [row["resolved_method"]["generic_type_arguments"][1].split(".")[-1] for row in calls] != expected:
        raise ValueError("Store scanner actual current registration set or order differs")
    rows = [{"strategy": name, "review_scope": "this_store_group" if name in current else
        "previous_seven_strategy_group" if name in prior else "remaining_current_strategy",
        "condition": "OS major >= 6" if name.endswith("UwpSearch") else "unconditional",
        "caller_token": method["token"], **call} for name, call in zip(expected, calls)]
    return {"original": service["original"], "capture_input": service["capture_input"],
        "complete_register_method": method, "registrations": rows}


def _profile_store_review_changes(assemblies):
    current = [row for assembly in assemblies if assembly["version"] == "3.15.0.1200"
               for row in assembly["complete_methods"]]
    edges = []

    def select(root, name, *, nested=None):
        rows = [row for row in current if row["class_ancestry"][0].split(".")[-1] == root and row["name"] == name
                and (len(row["class_ancestry"]) == 1 if nested is None else any(nested in owner for owner in row["class_ancestry"][1:]))]
        if len(rows) != 1:
            raise ValueError("Store scanner selected changed method is absent or ambiguous: " + root + "." + name)
        return rows[0]

    def require(method, target, *, count=None):
        calls = [row for row in method["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == target]
        if not calls or count is not None and len(calls) != count:
            raise ValueError("Store scanner actual changed call differs: " + method["label"] + " -> " + target)
        edges.extend({"caller_token": method["token"], "caller_rva": method["rva"], "caller": method["label"],
            "offset": row["offset"], "bytes": row["bytes"], "target": row["resolved_method"]} for row in calls)
        return calls

    epic = "GameScannerStrategyEpicLauncherInstalledList"
    scan = select(epic, "MoveNext", nested="<ScanAsync>")
    converter = select(epic, "CreateEpicManifestFromInstalledGame")
    getter, constructor = select("EpicGameManifest", "get_LaunchExecutable"), select("EpicGameManifest", ".ctor")
    setter_names = [row["resolved_method"]["name"] for row in converter["calls"] if row["resolved_method"]
        and row["resolved_method"]["declaring_type"] == "Razer.GameManagerServiceLib.EpicGameManifest"
        and row["resolved_method"]["name"].startswith("set_")]
    if (setter_names != ["set_AppName", "set_DisplayName", "set_InstallLocation", "set_IsApplication",
            "set_MainGameAppName", "set_InstallSize", "set_BaseURLs"]
            or [row["opcode"] for row in getter["instructions"]] != ["ldarg.0", "ldfld", "ret"]
            or "'<LaunchExecutable>k__BackingField'" not in getter["instructions"][1]["operand"]
            or [row["opcode"] for row in constructor["instructions"]] != ["ldarg.0", "call", "ret"]
            or len(constructor["calls"]) != 1 or constructor["calls"][0]["resolved_method"]["declaring_type"] != "System.Object"):
        raise ValueError("Store scanner Epic synthesized LaunchExecutable producer differs")
    code = bytes.fromhex(scan["raw_code_hex"])
    gate = next(row for row in scan["instructions"] if row["offset"] == 0x22f)
    if (require(scan, "get_LaunchExecutable", count=1)[0]["offset"] != 0x225
            or gate["opcode"] != "brtrue" or gate["operand"] != "IL_0aed"
            or code[0x22f:0x234] != bytes.fromhex("3ab9080000")
            or require(scan, "GetLaunchUrl", count=1)[0]["offset"] <= 0x22f
            or require(scan, "TryFindEpicFallbackLaunchExe", count=1)[0]["offset"] <= 0x22f):
        raise ValueError("Store scanner Epic empty LaunchExecutable gate or original branch differs")
    matching = select(epic, "FindMatchingInstalledGame")
    require(matching, "FirstOrDefault", count=3)
    require(scan, "FindMatchingInstalledGame", count=1)
    require(scan, "CreateEpicManifestFromInstalledGame", count=1)
    fallback = select(epic, "TryFindEpicFallbackLaunchExe")
    for target in ("DirectoryExists", "get_LaunchExecutable", "EnumerateFiles", "OrderBy", "ThenBy", "FileExists"):
        require(fallback, target)
    rank = select(epic, "GetEpicFallbackLaunchExeRank")
    returns = []
    raw = bytes.fromhex(rank["raw_code_hex"])
    for previous, instruction in zip(rank["instructions"], rank["instructions"][1:]):
        if instruction["opcode"] == "ret" and previous["opcode"] in {"ldc.i4." + str(index) for index in range(4)}:
            value = int(previous["opcode"][-1])
            if raw[previous["offset"]:instruction["offset"] + 1] != bytes((0x16 + value, 0x2a)):
                raise ValueError("Store scanner Epic ranking return differs from original constant")
            returns.append(value)
    if returns != [0, 1, 2, 3]:
        raise ValueError("Store scanner Epic ranking constant order differs")
    require(select(epic, "NormalizeEpicName"), "IsLetterOrDigit", count=1)
    invariant = [row for row in current if row["class_ancestry"][0].split(".")[-1] == epic
                 and any((call["resolved_method"] or {}).get("name") == "ToLowerInvariant" for call in row["calls"])]
    if len(invariant) != 4:
        raise ValueError("Store scanner Epic old identity comparer differs")
    steam = select("SteamAppInfoData", "GetLaunchExe")
    recursive = select("SteamAppInfoData", "FindLaunchExe")
    old_steam, = [row for assembly in assemblies if assembly["version"] == "3.14.0.1109"
        for row in assembly["complete_methods"] if row["class_ancestry"] == ["Razer.GameManagerServiceLib.SteamAppInfoData"]
        and row["name"] == "GetLaunchExe"]
    if steam["exception_sections"] or not old_steam["exception_sections"]:
        raise ValueError("Store scanner Steam launch exception boundary differs")
    require(steam, "ContainsKey", count=2)
    require(steam, "FindLaunchExe", count=1)
    require(select("SteamAppInfoData", "GetAppType"), "ContainsKey", count=2)
    for target in ("get_Children", "FindLaunchExe", "Dispose", "EndsWith"):
        require(recursive, target, count=1)
    if bytes.fromhex(recursive["raw_code_hex"])[0x21] != 0x1b or bytes.fromhex(recursive["raw_code_hex"])[0x44] != 0x1b:
        raise ValueError("Store scanner Steam executable comparison is not original OrdinalIgnoreCase")
    if [clause["flags"] for section in recursive["exception_sections"] for clause in section["clauses"]] != [2]:
        raise ValueError("Store scanner recursive launch search has an unreviewed exception handler")
    battle = select("GameScannerStrategyBattleNetSearchV2", ".ctor")
    frozen = require(battle, "ToFrozenSet", count=1)
    literals = [row["original_user_string"]["value"] for row in battle["token_operands"] if "original_user_string" in row]
    if literals[:3] != ["bna", "agent", "clnt"]:
        raise ValueError("Store scanner BattleNet blacklist constants differ")
    require(battle, "get_CurrentCultureIgnoreCase", count=1)
    return {"verified_changed_call_edges": edges,
        "epic": {"scan_token": scan["token"], "scan_rva": scan["rva"], "converter_token": converter["token"],
            "converter_setters": setter_names, "launch_getter_token": getter["token"], "constructor_token": constructor["token"],
            "empty_launch_branch": {"offset": 0x22f, "bytes": code[0x22f:0x234].hex(), "target": gate["operand"]},
            "matching_passes": 3, "original_rank_returns": returns, "invariant_identity_methods": [row["token"] for row in invariant],
            "fallback_exception_sections": fallback["exception_sections"]},
        "steam": {"get_launch_token": steam["token"], "get_launch_rva": steam["rva"],
            "old_get_launch_exception_sections": old_steam["exception_sections"], "current_get_launch_exception_sections": steam["exception_sections"],
            "recursive_token": recursive["token"], "recursive_rva": recursive["rva"],
            "recursive_exception_sections": recursive["exception_sections"],
            "generated_owner_rename": {"old": "<ReadAsync>d__13", "current": "<ReadAsync>d__14",
                "raw_method_comparison_classification_preserved": True}},
        "battle_net": {"constructor_token": battle["token"], "frozen_set_call": frozen[0], "blacklist_literals": literals[:3]}}


