def _profile_store_projection(report):
    return {key: report[key] for key in ("host_release", "capture", "assemblies", "comparisons", "source_comparisons",
        "registration", "dependencies", "reviewed_changes", "boundaries")}


def _verify_profile_store_scanner_versions(report):
    if report.get("boundaries") != _profile_store_boundaries():
        raise ValueError("Store scanner failure, registration or lifecycle boundary differs")
    if (report.get("query") != "profile-store-scanner-versions" or report.get("schema_version") != 1
            or report.get("selected_version_comparison_complete") is not True or report.get("source_chain_complete") is not False
            or report.get("whole_profiles_complete") is not False or report.get("target_execution") is not False
            or report.get("product_code_modified") is not False or report.get("real_device_operations") is not False
            or report.get("snapshot_stable") is not True or report.get("changed_during_query") or report.get("failures")
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "rust_independent_implementation",
                "ui_backend_wiring", "runtime_acceptance"))):
        raise ValueError("Store scanner static evidence was promoted or snapshot failed")
    digest = hashlib.sha256(json.dumps(_profile_store_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if digest != "49e70f8cbbd50ccae72b9c3fb5ef24699f60199c7872bb811fffa55a6a047009" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Store scanner selected bytes require complete semantic review: " + digest)
    counts = {}
    for row in report["comparisons"]:
        counts[row["classification"]] = counts.get(row["classification"], 0) + 1
    return {"registered_strategies": 22, "selected_strategies": 4, "previously_reviewed_strategies": 7,
        "remaining_current_strategies": 11, "complete_managed_methods": sum(len(row["complete_methods"]) for row in report["assemblies"]),
        "comparison_classes": counts, "reviewed_changes": ["Steam recursive executable search", "BattleNet frozen blacklist",
            "Epic manifest eligibility and fallback"], "target_execution": False, "runtime_acceptance": "unverified"}


def collect_profile_store_scanner_versions(audit):
    """Continue the current scanner inventory without repeating shared or native captures."""
    previous = json.loads((audit.a.ROOT / ".analysis/results/host-current/local-audit.json").read_bytes())["profile_scanner_version_differences"]
    _verify_profile_scanner_version_differences(previous)
    selected = _profile_store_managed(audit, previous)
    registration = _profile_store_registration(audit, previous)
    report = {"schema_version": 1, "query": "profile-store-scanner-versions", "kind": "current_profile_store_scanner_versions",
        "host_release": previous["host_release"], **selected, "registration": registration,
        "reviewed_changes": _profile_store_review_changes(selected["assemblies"]), "boundaries": _profile_store_boundaries(),
        "dependencies": [{"receipt": ".analysis/results/host-current/local-audit.json", "section": "profile_scanner_version_differences",
            "reviewed_selection_sha256": previous["reviewed_selection_sha256"],
            "reused": ["seven strategies", "verified current package ancestry", "actual RegisterService and ten diagnostics",
                "registry/path and Mihoyo helper boundary", "shared dispatch/stop/dedup/list consumers", "native and deferred icons"]}],
        "selected_version_comparison_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "target_execution": False, "product_code_modified": False, "real_device_operations": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified", "failures": [],
        "complete_originals": list(audit.sources.values()), "complete_source_owners": [], "selected": {},
        "verified_artifacts": list(audit.artifacts.values()), "changed_during_query": audit.final_snapshot(),
        "maintenance_lifecycle": {"temporary_artifacts_created": [], "analysis_sessions_created": [], "reused_complete_managed_capture": True}}
    report["snapshot_stable"] = not report["changed_during_query"]
    report["remaining_chains"] = ["Current strategy not reviewed here: " + row["strategy"]
        for row in registration["registrations"] if row["review_scope"] == "remaining_current_strategy"] + [
        "Unselected changed GameSignatureHelper and affected consumers; external KV, SQLite and framework behavior remain separate",
        "Independent Rust implementation, UI/backend wiring and automated behavior tests",
        "Actual DLL/service/device comparison and runtime acceptance"]
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_store_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    report["verification"] = _verify_profile_store_scanner_versions(report)
    return report


def _profile_local_scope():
    strategies = ["GameScannerStrategy" + name for name in ("DefaultExeSearch", "DefaultRegistryKey",
        "GameUXInfoSearch", "GameUXRegistrySearch", "RegistrySearch", "UninstallSearch", "UserFolderExeSearch")]
    lib = {name: None for name in [*strategies, "GameScannerStrategyGameUXBase"]}
    lib["GameScannerStrategyGameUXBase"] = (".ctor", ".cctor", "GetGameUXInfos", "GetGogGalaxyGuids",
        "GetGogGalaxyManufacturer", "GetOriginGameDirectories", "GetUplayGameDirectories", "GetUplayManufacturer") + tuple(
        prefix + name for name in ("AppExePath", "ConfigGdfBinaryPath", "EntryGuid", "GameGuid", "Manufacturer",
            "RegistryKey", "RegistryPathKeyName", "Title") for prefix in ("get_", "set_"))
    common = {name: None for name in ("RegistryWrapper", "RegistryInspector", "PathExtensions", "RegistryGroupData")}
    common["PathWrapper"] = (".ctor", ".cctor", "DirectoryExists", "FileExists", "GetDirectories", "GetFiles",
        "GetLocalDrivesList", "<GetLocalDrivesList>")
    common["GameSignatureHelper"] = (".ctor", ".cctor", "GetComponents", "GetDefaultFolderArchIndependent",
        "GetDefaultFolderExeArchIndependent", "GetAdjustedDefaultFolderAndDefaultExe",
        "GetAdjustedDefaultFolderAndDefaultExe32", "GetAdjustedDefaultFolderAndDefaultExe64",
        "GetAdjustedVariablePath", "<GetAdjustedVariablePath>", "GetMultipleExpandedDefaultFolderExe",
        "GetPossibleDefaultFolderExePaths", "<GetPossibleDefaultFolderExePaths>", "ExpandPath", "ExpandVariables")
    return {"GameManagerServiceLib.dll": lib, "GameScannerCommon.dll": common}, strategies


def _profile_local_managed(audit, previous):
    """Verify selected local scanner methods against both retained original assemblies."""
    import difflib
    capture_path = audit.a.ROOT / ".analysis/results/host-current/managed/capture.json"
    capture = json.loads(audit.artifact(capture_path, previous["capture"]["identity"]))
    if capture.get("target_execution") is not False:
        raise ValueError("Local scanner managed capture is not static")
    index = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=index)
    if (release["version"] != previous["host_release"]["version"]
            or release["receipt"] != previous["host_release"]["receipt"]):
        raise ValueError("Local scanner current host release differs")
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for artifact in [previous["host_release"]["official_gms_package"], *release["verified_dependencies"]]:
        audit.artifact(audit.a.ROOT / artifact["path"], artifact)
    scope, _ = _profile_local_scope()
    assemblies, source_maps = [], {}
    for version in ("3.14.0.1109", "3.15.0.1200"):
        for filename, selectors in scope.items():
            retained, = [row for row in previous["assemblies"] if row["version"] == version
                         and Path(row["original"]["path"]).name == filename]
            original = retained["original"]
            indexed, = [row for row in index["inputs"] if row["path"] == original["path"]]
            if indexed != original:
                raise ValueError("Local scanner original index identity differs")
            raw = audit.read(original)
            parent = retained["official_package_original"]
            audit.read(parent)
            record, = [row for row in capture["assemblies"] if row["input_sha256"] == original["sha256"]]
            acquired, = [row for row in record["acquisition_bindings"] if row["path"] == original["path"]]
            if (any(acquired[key] != original[key] for key in ("bytes", "sha256", "container", "container_sha256"))
                    or not record["capture_complete"] or not record["input_bytes_unchanged"]
                    or not record["all_csharp_resolved"] or record["diagnostics"]):
                raise ValueError("Local scanner selected managed capture failed")
            metadata = _profile_gog_clr(raw)
            if [row["tree"].get("file_version") for row in metadata["pe"]["version_resources"]] != [version]:
                raise ValueError("Local scanner original file version differs")
            sources = []
            for class_name in selectors:
                artifact, = [row for row in record["outputs"] if row["path"].endswith("/" + class_name + ".cs")]
                source = audit.artifact(audit.a.ROOT / artifact["path"], artifact).decode("utf-8-sig")
                sources.append({"class": class_name, "artifact": artifact, "complete_source": source})
                source_maps[version, class_name] = sources[-1]
            il_artifact, = [row for row in record["outputs"] if row["path"].endswith("/il.stdout.txt")]
            il = audit.artifact(audit.a.ROOT / il_artifact["path"], il_artifact).decode("utf-8-sig")
            selections = {name: choices if choices is not None else tuple(sorted({row["name"]
                for row in metadata["methods"].values() if row["declaring_type"].endswith("." + name)})) + ("<",)
                for name, choices in selectors.items()}
            methods = _profile_gog_il_methods(original, il, metadata, selections)
            heap = _profile_scanner_user_heap(metadata)
            methods = [{**row, **_profile_scanner_token_ranges(row, heap)} for row in methods]
            if set(selectors) != {row["class_ancestry"][0].split(".")[-1] for row in methods}:
                raise ValueError("Local scanner complete method selection omits a class")
            assemblies.append({"version": version, "original": original, "official_package_original": parent,
                "capture_input": {key: record[key] for key in ("input", "input_sha256", "input_bytes",
                    "capture_complete", "all_csharp_resolved", "diagnostics")}, "il_artifact": il_artifact,
                "complete_source_owners": sources, "complete_methods": methods})
    comparisons = []
    for filename in scope:
        old, new = [next(row for row in assemblies if row["version"] == version
                        and Path(row["original"]["path"]).name == filename) for version in ("3.14.0.1109", "3.15.0.1200")]
        before = {_profile_scanner_method_key(row): row for row in old["complete_methods"]}
        after = {_profile_scanner_method_key(row): row for row in new["complete_methods"]}
        if len(before) != len(old["complete_methods"]) or len(after) != len(new["complete_methods"]):
            raise ValueError("Local scanner complete method identity is ambiguous")
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after:
                method = after.get(key, before.get(key))
                comparisons.append({"assembly": filename, "key": key, "token": method["token"], "rva": method["rva"],
                    "classification": "added_selected_method" if key not in before else "removed_selected_method"})
            else:
                comparisons.append({"assembly": filename, **_profile_scanner_compare(before[key], after[key])})
    sources = []
    for name in sorted({name for _, name in source_maps}):
        old, new = (source_maps[version, name] for version in ("3.14.0.1109", "3.15.0.1200"))
        sources.append({"class": name, "old_artifact": old["artifact"], "new_artifact": new["artifact"],
            "complete_source_bytes_equal": old["artifact"]["sha256"] == new["artifact"]["sha256"],
            "complete_diff": "\n".join(difflib.unified_diff(old["complete_source"].splitlines(), new["complete_source"].splitlines(),
                fromfile=old["artifact"]["path"], tofile=new["artifact"]["path"], n=3))})
    return {"assemblies": assemblies, "comparisons": comparisons, "source_comparisons": sources,
        "capture": {"identity": audit.families.identity(capture_path), "analyzer": capture["tool"]}}


def _profile_local_registration(audit, previous):
    retained = previous["registration"]
    audit.read(retained["original"])
    method = retained["complete_register_method"]
    captured = audit.artifact(audit.a.ROOT / ".analysis/results/host-current/managed/capture.json", previous["capture"]["identity"])
    record, = [row for row in json.loads(captured)["assemblies"] if row["input_sha256"] == retained["original"]["sha256"]]
    for artifact in record["outputs"]:
        if artifact["path"].endswith(("/ServiceRegister.cs", "/il.stdout.txt")):
            audit.artifact(audit.a.ROOT / artifact["path"], artifact)
    _, selected = _profile_local_scope()
    rows = [{**row, "review_scope": "this_local_group" if row["strategy"] in selected else
        "remaining_current_strategy" if row["review_scope"] == "remaining_current_strategy" else "previously_reviewed_group"}
        for row in retained["registrations"]]
    if (sum(row["review_scope"] == "this_local_group" for row in rows) != 7
            or sum(row["review_scope"] == "remaining_current_strategy" for row in rows) != 4):
        raise ValueError("Local scanner registration selection differs")
    return {"original": retained["original"], "capture_input": retained["capture_input"],
        "complete_register_method": method, "registrations": rows}


def _profile_local_review_changes(assemblies):
    edges = []

    def select(root, name, version="3.15.0.1200", *, state_machine=False):
        rows = [row for assembly in assemblies if assembly["version"] == version for row in assembly["complete_methods"]
            if row["class_ancestry"][0].split(".")[-1] == root and row["name"] == name
            and (any("<ScanAsync>" in owner for owner in row["class_ancestry"][1:]) if state_machine else len(row["class_ancestry"]) == 1)]
        if len(rows) != 1:
            raise ValueError("Local scanner selected method is absent or ambiguous: " + root + "." + name)
        return rows[0]

    def require(method, target, *, owner=None, count=None):
        calls = [row for row in method["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == target
            and (owner is None or row["resolved_method"]["declaring_type"] == owner)]
        if not calls or count is not None and len(calls) != count:
            raise ValueError("Local scanner actual call differs: " + method["label"] + " -> " + target)
        raw = bytes.fromhex(method["raw_code_hex"])
        if any(raw[row["offset"]:row["offset"] + len(bytes.fromhex(row["bytes"]))].hex() != row["bytes"] for row in calls):
            raise ValueError("Local scanner original call bytes differ: " + method["label"])
        edges.extend({"caller_token": method["token"], "caller_rva": method["rva"], "caller": method["label"], **row} for row in calls)
        return calls

    old = select("RegistryInspector", "SearchForRegistryKey", "3.14.0.1109")
    current = select("RegistryInspector", "SearchForRegistryKey")
    old_contains = require(old, "Contains", owner="System.Linq.Enumerable", count=2)
    span_contains = require(current, "Contains", owner="System.MemoryExtensions", count=2)
    conversions = require(current, "op_Implicit", count=2)
    if ([row["offset"] for row in old_contains] != [0x4c, 0x7c]
            or [row["offset"] for row in span_contains] != [0x51, 0x86]
            or [row["offset"] for row in conversions] != [0x46, 0x7b]
            or any(row["resolved_method"]["generic_signature_hex"] != "0a010e" for row in old_contains + span_contains)
            or any("System.ReadOnlySpan`1<string>::op_Implicit(!0[])" not in row["operand"] for row in conversions)
            or any("System.ReadOnlySpan`1<!!0>" not in row["operand"] for row in span_contains)
            or any(row["bytes"] != "281c00002b" for row in old_contains + span_contains)
            or old["exception_sections"] or current["exception_sections"]):
        raise ValueError("Local scanner original span conversion, string argument or exception boundary differs")
    wrapper = select("RegistryWrapper", "SearchRegistryString")
    require(wrapper, "SearchRegistryKeyPath", owner="Razer.GameScannerCommon.IRegistryInspector", count=1)
    require(wrapper, "GetValue", owner="Microsoft.Win32.RegistryKey", count=2)
    require(wrapper, "Equals", owner="System.String", count=1)
    path = select("RegistryInspector", "SearchRegistryKeyPath")
    require(path, "SearchForRegistryKey", owner="Razer.GameScannerCommon.RegistryInspector", count=6)
    base_calls = require(path, "OpenBaseKey", owner="Microsoft.Win32.RegistryKey", count=6)
    after_open = [row for row in path["instructions"] if 0x180 <= row["offset"] < 0x18a]
    if (bytes.fromhex(path["raw_code_hex"])[0x180:0x185] != bytes.fromhex("260208110d")
            or next(row for row in path["instructions"] if row["offset"] == 0x176) !=
                {"offset": 0x176, "opcode": "ldc.i4", "operand": "512"}
            or [row["opcode"] for row in after_open] != ["pop", "ldarg.0", "ldloc.2", "ldloc.s", "call"]
            or base_calls[4]["offset"] != 0x17b or wrapper["exception_sections"]):
        raise ValueError("Local scanner explicit-hive Registry32 result or wrapper catch differs")
    exe32_branches = []
    for root, gate_at, read_at in (("GameScannerStrategyDefaultRegistryKey", 0x2fa, 0x30d),
            ("GameScannerStrategyRegistrySearch", 0x2e4, 0x2f7)):
        method = select(root, "MoveNext", state_machine=True)
        require(method, "SearchRegistryString", owner="Razer.GameScannerCommon.IRegistryWrapper", count=1)
        require(method, "ReadRegistryString", owner="Razer.GameScannerCommon.IRegistryWrapper", count=1)
        gate = require(method, "get_DefaultExe64", owner="Razer.GameScannerCommon.GameSignature", count=1)[0]
        reads = require(method, "get_DefaultExe32", owner="Razer.GameScannerCommon.GameSignature", count=3)
        if gate["offset"] != gate_at or reads[-1]["offset"] != read_at:
            raise ValueError("Local scanner original 64-bit gate and 32-bit candidate consumer differs")
        exe32_branches.append({"caller_token": method["token"], "gate_offset": gate_at,
            "candidate_read_offset": read_at, "candidate_property": "DefaultExe32"})
    info = select("GameScannerStrategyGameUXInfoSearch", "MoveNext", state_machine=True)
    names = ["GetGameUXInfos", "GetOriginGameDirectories", "GetGogGalaxyGuids", "GetUplayGameDirectories"]
    preloads = [require(info, name, owner="Razer.GameManagerServiceLib.GameScannerStrategyGameUXBase", count=1)[0] for name in names]
    stop = require(info, "GetStopScanFlag", owner="Razer.GameManagerServiceLib.GameScannerStrategyBase", count=1)[0]
    if [row["offset"] for row in preloads] != [0x40, 0x47, 0x4f, 0x57] or stop["offset"] != 0x7a:
        raise ValueError("Local scanner GameUX preload or stop order differs")
    return {"actual_call_edges": edges,
        "registry_contains": {"old": {"token": old["token"], "rva": old["rva"], "code_size": old["code_size"],
            "calls": old_contains, "exception_sections": old["exception_sections"]},
            "current": {"token": current["token"], "rva": current["rva"], "code_size": current["code_size"],
                "calls": span_contains, "span_conversions": conversions, "exception_sections": current["exception_sections"]},
            "conversion_owner": "captured IL ReadOnlySpan<string>; MemberRef name/token verified, TypeSpec owner not independently decoded",
            "same_raw_call_token_does_not_prove_same_target": True},
        "explicit_registry32": {"caller_token": path["token"], "caller_rva": path["rva"],
            "open_offset": 0x17b, "discard_offset": 0x180, "reused_default_key_local": 13,
            "raw_pop_and_reload": "260208110d", "exception_sections": path["exception_sections"]},
        "registry_default_exe64_branches": exe32_branches,
        "gameux_preloads": {"caller_token": info["token"], "names": names,
            "offsets": [row["offset"] for row in preloads], "first_scan_loop_stop_offset": stop["offset"]}}


