def _profile_remaining_projection(report):
    return {key: report[key] for key in ("host_release", "capture", "assemblies", "comparisons", "declaration_comparisons",
        "source_comparisons", "registration", "dependencies", "reviewed_chains", "boundaries")}


def _verify_profile_remaining_scanner_versions(report):
    if report.get("boundaries") != _profile_remaining_boundaries():
        raise ValueError("Remaining scanner registration, failure or lifecycle boundary differs")
    if (report.get("query") != "profile-remaining-scanner-versions" or report.get("kind") != "current_profile_remaining_scanner_versions"
            or report.get("schema_version") != 1 or report.get("selected_version_comparison_complete") is not True
            or report.get("source_chain_complete") is not False or report.get("whole_profiles_complete") is not False
            or report.get("target_execution") is not False or report.get("product_code_modified") is not False
            or report.get("real_device_operations") is not False or report.get("snapshot_stable") is not True
            or report.get("changed_during_query") or report.get("failures")
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "rust_independent_implementation",
                "ui_backend_wiring", "runtime_acceptance"))):
        raise ValueError("Remaining scanner static evidence was promoted or snapshot failed")
    digest = hashlib.sha256(json.dumps(_profile_remaining_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if digest != "cd71197ecd8d14276cb9b6096134dac2fe21a6bbcf20c2cd291a2a43364e4561" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Remaining scanner selected bytes require complete semantic review: " + digest)
    counts = {}
    for row in report["comparisons"]:
        counts[row["classification"]] = counts.get(row["classification"], 0) + 1
    return {"registered_strategies": 22, "selected_strategies": 4, "previously_reviewed_strategies": 18,
        "remaining_registered_version_reviews": 0, "complete_managed_methods": sum(len(row["complete_methods"]) for row in report["assemblies"]),
        "selected_declarations": sum(len(row["selected_declarations"]) for row in report["assemblies"]),
        "comparison_classes": counts, "declaration_comparisons": len(report["declaration_comparisons"]),
        "target_execution": False, "runtime_acceptance": "unverified"}


def collect_profile_remaining_scanner_versions(audit):
    """Review the remaining registered strategies without recapturing earlier groups."""
    previous = json.loads((audit.a.ROOT / ".analysis/results/host-current/local-audit.json").read_bytes())["profile_local_scanner_versions"]
    _verify_profile_local_scanner_versions(previous)
    selected = _profile_remaining_managed(audit, previous)
    registration = _profile_remaining_registration(audit, previous)
    report = {"schema_version": 1, "query": "profile-remaining-scanner-versions", "kind": "current_profile_remaining_scanner_versions",
        "host_release": previous["host_release"], **selected, "registration": registration,
        "reviewed_chains": _profile_remaining_review(selected["assemblies"]), "boundaries": _profile_remaining_boundaries(),
        "dependencies": [{"receipt": ".analysis/results/host-current/local-audit.json", "section": "profile_local_scanner_versions",
            "reviewed_selection_sha256": previous["reviewed_selection_sha256"],
            "reused": ["eighteen previously reviewed strategies", "current package ancestry and actual registration",
                "RegistryWrapper/PathWrapper/PathExtensions", "store-group local JSON serializer",
                "shared identity/dispatch/stop/dedup/list consumers", "native and deferred icons", "ten Service C# diagnostics"]}],
        "selected_version_comparison_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "target_execution": False, "product_code_modified": False, "real_device_operations": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified", "failures": [],
        "complete_originals": list(audit.sources.values()), "complete_source_owners": [], "selected": {},
        "verified_artifacts": list(audit.artifacts.values()), "changed_during_query": audit.final_snapshot(),
        "maintenance_lifecycle": {"temporary_artifacts_created": [], "analysis_sessions_created": [], "reused_complete_managed_capture": True}}
    report["snapshot_stable"] = not report["changed_during_query"]
    report["remaining_chains"] = ["Registered strategy version inventory reviewed; this does not close every Profiles/Service/framework consumer",
        "Unselected UwpHelper.GetInstalledUwpApps/GetUwpFullName and GameSignatureHelper.GetAllPossibleFilenames with actual callers",
        "External SQLite, JSON/XML, WinRT and OS behavior; actual impersonation failure and resource recovery",
        "Independent Rust implementation, UI/backend wiring and automated behavior tests",
        "Actual DLL/service/device comparison and runtime acceptance"]
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_remaining_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    report["verification"] = _verify_profile_remaining_scanner_versions(report)
    return report


