def _profile_shared_helper_managed(audit, previous):
    """Reuse complete captures and select only shared helpers and their real consumers."""
    capture_path = audit.a.ROOT / ".analysis/results/host-current/managed/capture.json"
    capture = json.loads(audit.artifact(capture_path, previous["capture"]["identity"]))
    if capture.get("target_execution") is not False:
        raise ValueError("Shared helper capture is not static")
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    if (release["version"] != previous["host_release"]["version"]
            or release["receipt"] != previous["host_release"]["receipt"]):
        raise ValueError("Shared helper current release differs")
    for artifact in [release["receipt"], previous["host_release"]["official_gms_package"], *release["verified_dependencies"]]:
        audit.artifact(audit.a.ROOT / artifact["path"], artifact)
    scope = _profile_shared_helper_scope()
    assemblies, source_maps, inventories = [], {}, []
    for retained in previous["assemblies"]:
        original, version = retained["original"], retained["version"]
        filename = Path(original["path"]).name
        if filename not in scope or version not in ("3.14.0.1109", "3.15.0.1200"):
            raise ValueError("Shared helper baseline assembly selection differs")
        entry, = [row for row in indexed["inputs"] if row["path"] == original["path"]]
        if entry != original:
            raise ValueError("Shared helper original index identity differs")
        metadata = _profile_gog_clr(audit.read(original))
        parent = retained["official_package_original"]
        audit.read(parent)
        if [row["tree"].get("file_version") for row in metadata["pe"]["version_resources"]] != [version]:
            raise ValueError("Shared helper original file version differs")
        record, = [row for row in capture["assemblies"] if row["input_sha256"] == original["sha256"]]
        acquired, = [row for row in record["acquisition_bindings"] if row["path"] == original["path"]]
        if (any(acquired[key] != original[key] for key in ("bytes", "sha256", "container", "container_sha256"))
                or not record["capture_complete"] or not record["input_bytes_unchanged"]
                or not record["all_csharp_resolved"] or record["diagnostics"]):
            raise ValueError("Shared helper selected managed capture failed")
        selectors, sources = scope[filename], []
        for name in [*selectors, *(("IUwpHelper",) if filename == "GameManagerServiceLib.dll" else ("IGameSignatureHelper",))]:
            artifact, = [row for row in record["outputs"] if row["path"].endswith("/" + name + ".cs")]
            source = audit.artifact(audit.a.ROOT / artifact["path"], artifact).decode("utf-8-sig")
            sources.append({"class": name, "artifact": artifact, "complete_source": source})
            source_maps[version, name] = sources[-1]
        il_artifact, = [row for row in record["outputs"] if row["path"].endswith("/il.stdout.txt")]
        il = audit.artifact(audit.a.ROOT / il_artifact["path"], il_artifact).decode("utf-8-sig")
        selections = {name: choices if choices is not None else tuple(sorted({row["name"]
            for row in metadata["methods"].values() if row["declaring_type"].endswith("." + name)})) + ("<",)
            for name, choices in selectors.items()}
        methods = _profile_gog_il_methods(original, il, metadata, selections)
        heap = _profile_scanner_user_heap(metadata)
        methods = [{**row, **_profile_scanner_token_ranges(row, heap)} for row in methods]
        if set(selectors) != {row["class_ancestry"][0].split(".")[-1] for row in methods}:
            raise ValueError("Shared helper complete method selection omits a class")
        inventories.extend(_profile_shared_helper_call_inventory(version, original, il, methods))
        assemblies.append({"version": version, "original": original, "official_package_original": parent,
            "capture_input": {key: record[key] for key in ("input", "input_sha256", "input_bytes",
                "capture_complete", "all_csharp_resolved", "diagnostics")}, "il_artifact": il_artifact,
            "complete_source_owners": sources, "complete_methods": methods})
    comparisons = []
    for filename in scope:
        old, new = [next(row for row in assemblies if row["version"] == version
            and Path(row["original"]["path"]).name == filename) for version in ("3.14.0.1109", "3.15.0.1200")]
        before = {_profile_scanner_method_key(row): row for row in old["complete_methods"]}
        after = {_profile_scanner_method_key(row): row for row in new["complete_methods"]}
        if len(before) != len(old["complete_methods"]) or len(after) != len(new["complete_methods"]):
            raise ValueError("Shared helper complete method identity is ambiguous")
        for key in sorted(set(before) | set(after)):
            if key not in before or key not in after:
                row = after.get(key, before.get(key))
                comparisons.append({"assembly": filename, "key": key, "token": row["token"], "rva": row["rva"],
                    "classification": "added_selected_method" if key not in before else "removed_selected_method"})
            else:
                comparisons.append({"assembly": filename, **_profile_scanner_compare(before[key], after[key])})
    source_comparisons = []
    for name in sorted({name for _, name in source_maps}):
        old, new = (source_maps[version, name] for version in ("3.14.0.1109", "3.15.0.1200"))
        source_comparisons.append({"class": name, "old_artifact": old["artifact"], "new_artifact": new["artifact"],
            "complete_source_bytes_equal": old["artifact"]["sha256"] == new["artifact"]["sha256"]})
    return {"assemblies": assemblies, "comparisons": comparisons, "source_comparisons": source_comparisons,
        "actual_helper_calls": inventories, "capture": {"identity": audit.families.identity(capture_path), "analyzer": capture["tool"]}}


def _profile_shared_helper_call_inventory(version, original, il, methods):
    """Reject a new direct caller omitted from the selected complete method owners."""
    pattern = (r"(?m)^[ \t]*IL_([0-9a-fA-F]+):[ \t]+(call|callvirt)[^\r\n]*"
        r"(Razer\.GameManagerServiceLib\.(?:IUwpHelper|UwpHelper|UwpHelperUnsupported)|Razer\.GameScannerCommon\.(?:IGameSignatureHelper|GameSignatureHelper))::"
        r"(GetInstalledUwpApps|GetUwpFullName|GetAllPossibleFilenames)\(")
    calls = []
    for match in re.finditer(pattern, il):
        start = len(il[:match.start()].encode())
        owners = [row for row in methods if row["byte_start"] <= start < row["byte_end"]]
        if len(owners) != 1:
            raise ValueError("Shared helper direct caller is absent or ambiguous in selected complete methods")
        method, = owners
        call, = [row for row in method["calls"] if row["offset"] == int(match[1], 16)
                 and (row["resolved_method"] or {}).get("declaring_type") == match[3]
                 and row["resolved_method"]["name"] == match[4]]
        calls.append({"version": version, "original": original, "caller_token": method["token"],
            "caller": method["declaring_type"] + "::" + method["name"], "caller_rva": method["rva"], **call})
    return calls


def _profile_shared_helper_boundaries():
    return {
        "uwp_list": {"input": "SystemId -> FindPackagesForUser; not current user inferred from account",
            "order": "materialize packages, category cache, impersonated entitlement cache with own-context retry, then package loop",
            "requires": "nonempty InstalledLocation, not framework, manifest DisplayName and ExePath, existing combined exe",
            "game_kind": "family -> category ProductId -> entitlement ProductKind; otherwise MicrosoftGame.config presence sets Game",
            "only_games_returned": False, "package_dedup_or_architecture_filter": False,
            "errors": "per-package exception silently skips; outer exception logs and returns accumulated prefix",
            "stop_or_generation_check": False, "impersonator_dispose_proves_handle_close": False},
        "uwp_full_name": {"input": "signature.GameInfo -> FindPackages, with no userId argument",
            "single": "use sole package FullName regardless of architecture",
            "multiple": "first OS X64 or X86, then first Neutral; not highest version or ARM64",
            "no_match_or_error": "retain prior ProcessName; ordinary errors log without success result; null signature can throw again in catch logging",
            "writes": "mutates ProcessName only", "stop_or_generation_check": False},
        "unsupported": {"gate": "existing registration chooses real helper at OS major >= 6",
            "list": "new empty list", "full_name": "no-op", "product_support_claim": False},
        "filenames": {"ordered_fields": ["DefaultExe", "DefaultExe32", "DefaultExe64", "AlternativeExe",
                "DefaultFolderExe", "DefaultFolderExe32", "LaunchHelper", "RunningExe"],
            "multi_value_separator": "|; no trimming", "launch_helper_exclusion": "compare original complete component before stripping extension, without explicit comparer",
            "version_change": "Enumerable.Contains<string> -> array-to-ReadOnlySpan plus MemoryExtensions.Contains<string>",
            "distinct": "CurrentCultureIgnoreCase, first retained order", "launch_exe_directly_included": False,
            "file_exists_required": False, "path_errors": "individual filename extraction catches; field access/GetComponents/Contains are not all protected",
            "framework_behavior_equivalence_executed": False, "stop_or_generation_check": False},
        "consumers": {"get_uwp_apps": "manager supplies SystemId; Hub yields empty for null client then continues Task.Run and another yield",
            "null_client_terminates_enumeration": False, "hub_task_has_cancel_token": False,
            "auto_detect": "first family CurrentCultureIgnoreCase match supplies LogoPath only, before AddGameToUserGameList",
            "manual_add": "both variants call full-name helper only for SourceEx UWP after settings updates and before duplicate checks/list persistence",
            "full_name_failure_prevents_add": False, "serialization_failure_rolls_back_mutations": False,
            "serialization_failure_can_still_notify": True, "outer_add_catch_always_changes_initial_success": False,
            "running_processes": "MGL/LGL/UGL filenames enter OrdinalIgnoreCase set under separate locks; then enumerate processes and name-filter before path extraction",
            "process_objects_explicitly_disposed": False,
            "cache": "filename -> HashSet<Guid>; additive, no clear; blacklist removal only on new filename branch; reset ignored names after normal loop if changed",
            "blacklist": "three local/user-list events remove both stem and stem.exe under monitor lock, then reset ignored names",
            "partial_cache_rollback_on_error": False},
        "lifecycle": {"list_locks_and_enumerators_have_finally": True, "whole_operation_cancel_or_join": False,
            "external_winrt_sqlite_framework_reviewed_here": False, "actual_service_or_dll_execution": False}}


def _profile_shared_helper_review(assemblies):
    current = [row for assembly in assemblies if assembly["version"] == "3.15.0.1200" for row in assembly["complete_methods"]]

    def select(root, name, *, largest=False, generated=None):
        rows = [row for row in current if row["class_ancestry"][0].split(".")[-1] == root and row["name"] == name
                and (generated is None and len(row["class_ancestry"]) == 1
                     or generated is not None and any(generated in owner for owner in row["class_ancestry"][1:]))]
        if largest:
            return max(rows, key=lambda row: row["code_size"])
        row, = rows
        return row

    def require(method, name, count=None, owner=None):
        rows = [row for row in method["calls"] if (row["resolved_method"] or {}).get("name") == name
                and (owner is None or row["resolved_method"].get("declaring_type") == owner)]
        if not rows or count is not None and len(rows) != count:
            raise ValueError("Shared helper actual call selection differs: " + method["label"] + " -> " + name)
        raw = bytes.fromhex(method["raw_code_hex"])
        for row in rows:
            encoded = bytes.fromhex(row["bytes"])
            if raw[row["offset"]:row["offset"] + len(encoded)] != encoded:
                raise ValueError("Shared helper original call bytes differ")
        return rows

    def identity(row):
        return {key: row[key] for key in ("token", "rva", "code_size", "raw_code_sha256", "exception_sections")}

    installed = select("UwpHelper", "GetInstalledUwpApps")
    full = select("UwpHelper", "GetUwpFullName")
    filenames = select("GameSignatureHelper", "GetAllPossibleFilenames")
    for method in (installed, full, filenames):
        if any((row["resolved_method"] or {}).get("name") in ("GetStopScanFlag", "ThrowIfCancellationRequested") for row in method["calls"]):
            raise ValueError("Shared helper acquired an unreviewed cancellation path")
    list_calls = {name: require(installed, name, count=count) for name, count in (
        ("FindPackagesForUser", 1), ("GetCategoryCache", 1), ("GetEntitlementsCache", 2), ("ReadManifest", 1), ("FileExists", 1), ("Exists", 1))}
    if ([c["flags"] for s in installed["exception_sections"] for c in s["clauses"]] != [2, 0, 0, 2, 0]
            or [c["flags"] for s in full["exception_sections"] for c in s["clauses"]] != [0]
            or [c["flags"] for s in filenames["exception_sections"] for c in s["clauses"]] != [0] * 8):
        raise ValueError("Shared helper catch/finally boundary differs")
    require(full, "FindPackages", count=1, owner="Windows.Management.Deployment.PackageManager")
    require(full, "set_ProcessName", count=2)
    getters = [row["resolved_method"]["name"][4:] for row in filenames["calls"]
               if (row["resolved_method"] or {}).get("name", "").startswith("get_")
               and row["resolved_method"].get("declaring_type") == "Razer.GameScannerCommon.GameSignature"]
    ordered = list(dict.fromkeys(getters))
    if ordered != ["DefaultExe", "DefaultExe32", "DefaultExe64", "AlternativeExe", "DefaultFolderExe",
            "DefaultFolderExe32", "LaunchHelper", "LaunchHelperExcludables", "RunningExe"]:
        raise ValueError("Shared helper filename field order differs")
    span = require(filenames, "Contains", count=1, owner="System.MemoryExtensions")[0]
    convert = require(filenames, "op_Implicit", count=1)[0]
    if span["resolved_method"].get("generic_signature_hex") != "0a010e" or convert["offset"] >= span["offset"]:
        raise ValueError("Shared helper span string instantiation or conversion differs")
    require(filenames, "Distinct", count=1, owner="System.Linq.Enumerable")
    old_filenames, = [row for assembly in assemblies if assembly["version"] == "3.14.0.1109"
        for row in assembly["complete_methods"] if row["declaring_type"] == "Razer.GameScannerCommon.GameSignatureHelper"
        and row["name"] == "GetAllPossibleFilenames"]
    old_contains, = require(old_filenames, "Contains", count=1, owner="System.Linq.Enumerable")
    if any((row["resolved_method"] or {}).get("name") == "op_Implicit" for row in old_filenames["calls"]):
        raise ValueError("Shared helper old membership unexpectedly uses span conversion")
    unsupported_list = select("UwpHelperUnsupported", "GetInstalledUwpApps")
    unsupported_full = select("UwpHelperUnsupported", "GetUwpFullName")
    if unsupported_full["raw_code_hex"] != "2a" or unsupported_list["code_size"] != 6:
        raise ValueError("Shared helper unsupported branch differs")
    running = select("GameListAndSettingsManager", "GetRunningProcesses")
    require(running, "GetAllPossibleFilenames", count=3)
    require(running, "GetProcesses", count=1)
    if any((row["resolved_method"] or {}).get("name") in ("Close", "Dispose")
           and row["resolved_method"].get("declaring_type") in ("System.Diagnostics.Process", "System.ComponentModel.Component") for row in running["calls"]):
        raise ValueError("Shared helper process ownership boundary differs")
    cache = select("GameProcessManager", "CacheFileNames")
    blacklist = select("GameProcessManager", "RemoveGamesFromBlacklist")
    require(cache, "GetAllPossibleFilenames", count=1)
    require(blacklist, "GetAllPossibleFilenames", count=1)
    for method in (cache, blacklist):
        require(method, "ResetIgnoredProcessNames", count=1)
    if any((row["resolved_method"] or {}).get("name") == "Clear" for row in cache["calls"]):
        raise ValueError("Shared helper additive cache was changed to replacement")
    adds = [select("GameListAndSettingsManager", name, largest=True)
            for name in ("AddGameToUserGameList", "AddGameToUserGameListReturnGS")]
    add_orders = []
    for method in adds:
        fill, = require(method, "GetUwpFullName", count=1)
        settings = require(method, "SetGameSettings", count=1)
        notify, = require(method, "NotifyUserGameListXmlUpdated", count=1)
        if not settings[0]["offset"] < fill["offset"] < notify["offset"]:
            raise ValueError("Shared helper full-name fill and persistence order differs")
        add_orders.append({"method": method["name"], **identity(method), "set_settings_offset": settings[0]["offset"],
            "full_name_offset": fill["offset"], "notify_offset": notify["offset"]})
    hub = select("GameManagerServiceHub", "MoveNext", generated="<GetUwpApps>")
    require(hub, "GetClientInstance", count=1)
    require(hub, "Run", count=1, owner="System.Threading.Tasks.Task")
    dispose = select("GameManagerServiceHub", "System.IAsyncDisposable.DisposeAsync", generated="<GetUwpApps>")
    return {"installed": {**identity(installed), "preload_calls": {name: [row["offset"] for row in calls] for name, calls in list_calls.items()},
            "actual_call_names": [row["resolved_method"]["name"] for row in installed["calls"] if row["resolved_method"]]},
        "full_name": {**identity(full), "architecture_lambdas": [identity(row) for row in current
            if row["class_ancestry"][0].split(".")[-1] == "UwpHelper" and "<GetUwpFullName>" in row["name"]]},
        "filenames": {**identity(filenames), "old_method": identity(old_filenames), "ordered_getters": ordered,
            "old_contains": old_contains, "span_conversion": convert, "contains": span},
        "running": identity(running), "cache": identity(cache), "blacklist": identity(blacklist),
        "manual_add_order": add_orders, "hub": {**identity(hub), "dispose_async": identity(dispose)}}


def _profile_shared_helper_projection(report):
    return {key: report[key] for key in ("host_release", "capture", "assemblies", "comparisons", "source_comparisons",
        "actual_helper_calls", "dependencies", "reviewed_chains", "boundaries")}


def _verify_profile_shared_helper_consumers(report):
    if report.get("boundaries") != _profile_shared_helper_boundaries():
        raise ValueError("Shared helper consumer, failure or lifecycle boundary differs")
    if (report.get("schema_version") != 1 or report.get("query") != "profile-shared-helper-consumers"
            or report.get("kind") != "current_profile_shared_helper_consumers"
            or report.get("selected_version_comparison_complete") is not True or report.get("source_chain_complete") is not False
            or report.get("whole_profiles_complete") is not False or report.get("target_execution") is not False
            or report.get("product_code_modified") is not False or report.get("real_device_operations") is not False
            or report.get("snapshot_stable") is not True or report.get("changed_during_query") or report.get("failures")
            or any(report.get(name) != "unverified" for name in ("actual_dll_comparison", "rust_independent_implementation",
                "ui_backend_wiring", "runtime_acceptance"))):
        raise ValueError("Shared helper static evidence was promoted or snapshot failed")
    digest = hashlib.sha256(json.dumps(_profile_shared_helper_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if digest != "0ae19ff0ac108787015af34342c17198d43805116c6a0384e3e1964a6ae3879c" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("Shared helper selected bytes require complete semantic review: " + digest)
    counts = {}
    for row in report["comparisons"]:
        counts[row["classification"]] = counts.get(row["classification"], 0) + 1
    return {"complete_managed_methods": sum(len(row["complete_methods"]) for row in report["assemblies"]),
        "comparison_classes": counts, "actual_helper_calls": len(report["actual_helper_calls"]),
        "registered_strategy_reanalysis": False, "target_execution": False, "runtime_acceptance": "unverified"}


def collect_profile_shared_helper_consumers(audit):
    """Close the selected GMS helper consumers while retaining external and runtime limits."""
    previous = json.loads((audit.a.ROOT / ".analysis/results/host-current/local-audit.json").read_bytes())["profile_remaining_scanner_versions"]
    _verify_profile_remaining_scanner_versions(previous)
    selected = _profile_shared_helper_managed(audit, previous)
    report = {"schema_version": 1, "query": "profile-shared-helper-consumers", "kind": "current_profile_shared_helper_consumers",
        "host_release": previous["host_release"], **selected, "reviewed_chains": _profile_shared_helper_review(selected["assemblies"]),
        "boundaries": _profile_shared_helper_boundaries(),
        "dependencies": [{"receipt": ".analysis/results/host-current/local-audit.json", "section": "profile_remaining_scanner_versions",
            "reviewed_selection_sha256": previous["reviewed_selection_sha256"],
            "reused": ["all 22 registered strategy version reviews and actual OS/helper registration",
                "GetCategoryCache/GetEntitlementsCache/GetUwpPackages/ReadManifest/ReadStoreId and Impersonator",
                "GetComponents and typed GameSignature fields", "current package ancestry and complete static captures",
                "shared dispatch/stop/dedup/list consumers, path and registry wrappers, native and deferred icons",
                "ten Service C# diagnostics; not suppressed or reclassified here"]}],
        "selected_version_comparison_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "target_execution": False, "product_code_modified": False, "real_device_operations": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified", "failures": [],
        "complete_originals": list(audit.sources.values()), "complete_source_owners": [], "selected": {},
        "verified_artifacts": list(audit.artifacts.values()), "changed_during_query": audit.final_snapshot(),
        "maintenance_lifecycle": {"temporary_artifacts_created": [], "analysis_sessions_created": [], "reused_complete_managed_capture": True}}
    report["snapshot_stable"] = not report["changed_during_query"]
    report["remaining_chains"] = ["Selected shared-helper and direct-consumer static version review is complete; it does not close whole Profiles or Service behavior",
        "External WinRT/OS and framework behavior, actual impersonation/resource recovery and process-monitor races remain separate",
        "Unselected game addition/persistence/process-monitor dependencies and all their actual callers remain outside this selected helper review",
        "Independent Rust implementation, UI/backend wiring and automated behavior tests",
        "Actual DLL/service/device comparison and runtime acceptance"]
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_shared_helper_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    report["verification"] = _verify_profile_shared_helper_consumers(report)
    return report


def _profile_gog_clr(raw):
    """Read MethodDef identities and method bodies without loading the assembly."""
    import struct
    pe = inspect_pe(raw)
    def read(rva, size):
        matches = [row["file_offset"] + rva - row["rva"] for row in pe["sections"]
                   if row["rva"] <= rva and rva + size <= row["rva"] + row["bytes"]]
        if size <= 0 or len(matches) != 1 or matches[0] + size > len(raw):
            raise ValueError("GOG CLR range has no unique original file backing")
        return raw[matches[0]:matches[0] + size]
    coff = struct.unpack_from("<I", raw, 0x3c)[0]
    optional = coff + 24
    directories = optional + (112 if struct.unpack_from("<H", raw, optional)[0] == 0x20b else 96)
    cli_rva, cli_size = struct.unpack_from("<II", raw, directories + 14 * 8)
    if cli_size < 72:
        raise ValueError("GOG managed original has no full CLR header")
    cli = read(cli_rva, 72)
    metadata_rva, metadata_size = struct.unpack_from("<II", cli, 8)
    metadata = read(metadata_rva, metadata_size)
    if metadata[:4] != b"BSJB":
        raise ValueError("GOG CLR metadata signature differs")
    position = (16 + struct.unpack_from("<I", metadata, 12)[0] + 3) & ~3
    count = struct.unpack_from("<H", metadata, position + 2)[0]
    position += 4
    streams = {}
    for _ in range(count):
        offset, size = struct.unpack_from("<II", metadata, position)
        finish = metadata.index(0, position + 8)
        name = metadata[position + 8:finish].decode("ascii")
        if name in streams or offset + size > len(metadata):
            raise ValueError("GOG CLR metadata stream is duplicate or truncated")
        streams[name] = metadata[offset:offset + size]
        position = (finish + 4) & ~3
    tables = streams.get("#~", streams.get("#-"))
    if tables is None or len(tables) < 24:
        raise ValueError("GOG CLR metadata tables are missing")
    heap_flags = tables[6]
    string_size, guid_size, blob_size = (4 if heap_flags & bit else 2 for bit in (1, 2, 4))
    valid = struct.unpack_from("<Q", tables, 8)[0]
    rows, position = {}, 24
    for table in range(64):
        if valid & (1 << table):
            rows[table] = struct.unpack_from("<I", tables, position)[0]
            position += 4
    index = lambda table: 4 if rows.get(table, 0) >= 65536 else 2
    coded = lambda bits, ids: 4 if max(rows.get(table, 0) for table in ids) >= 1 << (16 - bits) else 2
    resolution = coded(2, (0, 26, 35, 1))
    typedef = coded(2, (2, 1, 27))
    sizes = {0: 2 + string_size + 3 * guid_size, 1: resolution + 2 * string_size,
        2: 4 + 2 * string_size + typedef + index(4) + index(6), 3: index(4),
        4: 2 + string_size + blob_size, 5: index(6), 6: 8 + string_size + blob_size + index(8),
        7: index(8), 8: 4 + string_size, 9: index(2) + typedef,
        10: coded(3, (2, 1, 26, 6, 27)) + string_size + blob_size,
        11: 2 + coded(2, (4, 8, 23)) + blob_size,
        12: coded(5, (6, 4, 1, 2, 8, 9, 10, 0, 14, 23, 20, 17, 26, 27, 32, 35, 38, 39, 40, 42, 44, 43))
            + coded(3, (6, 10)) + blob_size,
        13: coded(1, (4, 8)) + blob_size, 14: 2 + coded(2, (2, 6, 32)) + blob_size,
        15: 6 + index(2), 16: 4 + index(4), 17: blob_size, 18: index(2) + index(20),
        19: index(20), 20: 2 + string_size + typedef, 21: index(2) + index(23), 22: index(23),
        23: 2 + string_size + blob_size, 24: 2 + index(6) + coded(1, (20, 23)),
        25: index(2) + 2 * coded(1, (6, 10)), 26: string_size, 27: blob_size,
        28: 2 + coded(1, (4, 6)) + string_size + index(26), 29: 4 + index(4), 30: 8, 31: 4,
        32: 16 + blob_size + 2 * string_size, 33: 4, 34: 12,
        35: 12 + 2 * blob_size + 2 * string_size, 36: 4 + index(35), 37: 12 + index(35),
        38: 4 + string_size + blob_size, 39: 8 + 2 * string_size + coded(2, (38, 35, 39)),
        40: 8 + string_size + coded(2, (38, 35, 39)), 41: 2 * index(2),
        42: 4 + coded(1, (2, 6)) + string_size, 43: coded(1, (6, 10)) + blob_size}
    offsets = {}
    for table in range(44):
        offsets[table] = position
        position += sizes[table] * rows.get(table, 0)
        if position > len(tables):
            raise ValueError("GOG CLR MethodDef table is truncated")
    def integer(offset, size):
        return int.from_bytes(tables[offset:offset + size], "little")
    def string(offset):
        heap = streams["#Strings"]
        return heap[offset:heap.index(0, offset)].decode("utf-8")
    types = []
    type_refs = {}
    for row in range(rows.get(1, 0)):
        at = offsets[1] + row * sizes[1] + resolution
        name, namespace = string(integer(at, string_size)), string(integer(at + string_size, string_size))
        type_refs[row + 1] = namespace + "." + name if namespace else name
    for row in range(rows.get(2, 0)):
        at = offsets[2] + row * sizes[2]
        name, namespace = string(integer(at + 4, string_size)), string(integer(at + 4 + string_size, string_size))
        first = integer(at + 4 + 2 * string_size + typedef + index(4), index(6))
        types.append({"type": namespace + "." + name if namespace else name, "first_method": first})
    nested_parents = {}
    for row in range(rows.get(41, 0)):
        at = offsets[41] + row * sizes[41]
        child, parent = integer(at, index(2)), integer(at + index(2), index(2))
        if not (0 < child <= len(types) and 0 < parent <= len(types)) or child in nested_parents:
            raise ValueError("GOG CLR nested type ownership is invalid")
        nested_parents[child] = parent
    for number, value in enumerate(types, 1):
        chain, seen, current = [], set(), number
        while current:
            if current in seen:
                raise ValueError("GOG CLR nested type ownership contains a cycle")
            seen.add(current)
            chain.append(types[current - 1]["type"])
            current = nested_parents.get(current)
        value["ancestry"] = chain[::-1]
    methods = {}
    for row in range(rows.get(6, 0)):
        at = offsets[6] + row * sizes[6]
        rva = integer(at, 4)
        token = (6 << 24) + 1 + row
        owners = [value for i, value in enumerate(types) if value["first_method"] <= row + 1
                  < (types[i + 1]["first_method"] if i + 1 < len(types) else rows[6] + 1)]
        if len(owners) != 1:
            raise ValueError("GOG CLR MethodDef declaring type is ambiguous")
        implementation_flags = integer(at + 4, 2)
        implementation_kind = ("il", "native", "optil", "runtime")[implementation_flags & 3]
        record = {"token": hex(token), "rva": hex(rva), "name": string(integer(at + 8, string_size)),
                  "declaring_type": owners[0]["type"], "declaring_type_ancestry": owners[0]["ancestry"],
                  "implementation_flags": hex(implementation_flags),
                  "method_flags": hex(integer(at + 6, 2)), "implementation_kind": implementation_kind,
                  "metadata_row_hex": tables[at:at + sizes[6]].hex(), "body_decoded": False}
        if rva and implementation_kind == "il":
            lead = read(rva, 1)[0]
            if lead & 3 == 2:
                header_size, code_size = 1, lead >> 2
            elif lead & 3 == 3:
                prefix = read(rva, 12)
                header_size = (struct.unpack_from("<H", prefix)[0] >> 12) * 4
                code_size = struct.unpack_from("<I", prefix, 4)[0]
                if header_size < 12:
                    raise ValueError("GOG CLR fat method header is invalid")
            else:
                raise ValueError("GOG CLR method header is invalid")
            record.update(header_bytes=read(rva, header_size).hex(), header_size=header_size, code_size=code_size,
                          code=read(rva + header_size, code_size) if code_size else b"")
            sections = []
            if lead & 3 == 3 and int.from_bytes(bytes.fromhex(record["header_bytes"])[:2], "little") & 8:
                section_rva = (rva + header_size + code_size + 3) & ~3
                while True:
                    prefix = read(section_rva, 4)
                    fat = bool(prefix[0] & 0x40)
                    size = int.from_bytes(prefix[1:4], "little") if fat else prefix[1]
                    stride = 24 if fat else 12
                    if prefix[0] & 0x3f != 1 or size < 4 or (size - 4) % stride:
                        raise ValueError("GOG CLR exception section is invalid")
                    body = read(section_rva, size)
                    clauses = []
                    for offset in range(4, size, stride):
                        if fat:
                            values = struct.unpack_from("<6I", body, offset)
                        else:
                            values = struct.unpack_from("<HHBHBI", body, offset)
                        flags, start, length, handler, handler_size, catch_or_filter = values
                        if start + length > code_size or handler + handler_size > code_size:
                            raise ValueError("GOG CLR exception clause exceeds the method")
                        clauses.append({"flags": flags, "try_offset": start, "try_length": length,
                            "handler_offset": handler, "handler_length": handler_size,
                            "catch_token_or_filter_offset": hex(catch_or_filter)})
                    sections.append({"rva": hex(section_rva), "bytes": body.hex(), "clauses": clauses})
                    if not prefix[0] & 0x80:
                        break
                    section_rva = (section_rva + size + 3) & ~3
            record["exception_sections"] = sections
            record["body_decoded"] = True
        methods[token] = record
    member_refs = {}
    parent_size = coded(3, (2, 1, 26, 6, 27))
    for row in range(rows.get(10, 0)):
        at = offsets[10] + row * sizes[10]
        parent = integer(at, parent_size)
        tag, item = parent & 7, parent >> 3
        owner = types[item - 1]["type"] if tag == 0 and 0 < item <= len(types) else type_refs.get(item) if tag == 1 else None
        token = (10 << 24) + 1 + row
        member_refs[token] = {"token": hex(token), "name": string(integer(at + parent_size, string_size)),
                              "declaring_type": owner, "parent_tag": tag, "parent_row": item}
    def compressed(blob, offset):
        first = blob[offset]
        if first < 0x80:
            return first, offset + 1
        if first < 0xc0:
            return ((first & 0x3f) << 8) | blob[offset + 1], offset + 2
        if first < 0xe0:
            return ((first & 0x1f) << 24) | int.from_bytes(blob[offset + 1:offset + 4], "big"), offset + 4
        raise ValueError("GOG CLR compressed metadata integer is invalid")

    def type_argument(blob, offset):
        element = blob[offset]
        if element not in (0x11, 0x12):
            return None, offset
        value, offset = compressed(blob, offset + 1)
        tag, row = value & 3, value >> 2
        name = types[row - 1]["type"] if tag == 0 and 0 < row <= len(types) else type_refs.get(row) if tag == 1 else None
        return name, offset

    method_specs = {}
    for row in range(rows.get(43, 0)):
        at = offsets[43] + row * sizes[43]
        method = integer(at, coded(1, (6, 10)))
        definition = ((10 if method & 1 else 6) << 24) + (method >> 1)
        target = methods.get(definition) or member_refs.get(definition)
        blob_offset = integer(at + coded(1, (6, 10)), blob_size)
        length, start = compressed(streams["#Blob"], blob_offset)
        signature = streams["#Blob"][start:start + length]
        arguments = None
        if signature and signature[0] == 0x0a:
            count, cursor = compressed(signature, 1)
            values = []
            for _ in range(count):
                value, cursor = type_argument(signature, cursor)
                if value is None:
                    break
                values.append(value)
            if len(values) == count and cursor == len(signature):
                arguments = values
        if target is not None:
            token = (43 << 24) + row + 1
            method_specs[token] = {**{key: target[key] for key in ("name", "declaring_type")}, "token": hex(token),
                "definition_token": hex(definition), "generic_signature_hex": signature.hex(), "generic_type_arguments": arguments}
    return {"pe": pe, "methods": methods, "member_refs": member_refs, "method_specs": method_specs, "read": read}


def _profile_gog_il_methods(original, text, metadata, selections):
    """Keep complete IL methods and verify their identities against original PE bytes."""
    selected_tokens = metadata.get("selected_method_tokens")
    classes = []
    for match in re.finditer(r"(?m)^(\t*)\.class[^\r\n]*", text):
        end = re.search(r"(?m)^" + re.escape(match[1]) + r"\} // end of class ([^\r\n]+)", text[match.end():])
        if end:
            classes.append((match.start(), match.end() + end.end(), end[1]))
    selected = []
    for match in re.finditer(r"(?m)^(\t*)\.method[^\r\n]*", text):
        end = re.search(r"(?m)^" + re.escape(match[1]) + r"\} // end of method ([^\r\n]+)", text[match.end():])
        if not end:
            raise ValueError("GOG captured IL method is unterminated")
        finish = match.end() + end.end()
        ancestry = [row[2] for row in sorted(classes, key=lambda row: row[0]) if row[0] < match.start() < row[1]]
        if not ancestry:
            continue
        root, label = ancestry[0].split(".")[-1], end[1]
        choices = selections.get(root, ())
        method_name = label.rsplit("::", 1)[-1].strip("'")
        if selected_tokens is None and not any((choice == method_name or choice.startswith("<")
                and any(choice in name for name in [method_name, *ancestry[1:]])) for choice in choices):
            continue
        body = text[match.start():finish]
        rva = re.search(r"Method begins at RVA (0x[0-9a-fA-F]+)", body)
        size = re.search(r"Code size: (\d+)", body)
        if not rva or not size:
            continue
        candidates = [row for row in metadata["methods"].values() if row["rva"] == rva[1].lower()]
        if selected_tokens is not None:
            candidates = [row for row in candidates
                          if row["declaring_type_ancestry"] == [name.replace("'", "") for name in ancestry]]
            named = [row for row in candidates if row["name"] == method_name]
            if not named and any(int(row["token"], 16) in selected_tokens for row in candidates):
                raise ValueError("GOG captured IL MethodDef identity/code size differs: " + label)
            candidates = [row for row in named if int(row["token"], 16) in selected_tokens]
        if selected_tokens is not None and not candidates:
            continue
        if len(candidates) != 1 or candidates[0]["name"] != method_name or candidates[0]["code_size"] != int(size[1]):
            raise ValueError("GOG captured IL MethodDef identity/code size differs: " + label)
        method = candidates[0]
        instructions = []
        for instruction in re.finditer(r"(?m)^\s*IL_([0-9a-fA-F]+):\s+([^\s]+)([^\r\n]*)", body):
            offset, opcode, operand = int(instruction[1], 16), instruction[2], instruction[3].strip()
            instructions.append({"offset": offset, "opcode": opcode, "operand": operand})
        if not instructions or instructions[0]["offset"] != 0 or any(row["offset"] >= method["code_size"] for row in instructions):
            raise ValueError("GOG captured IL does not cover the complete method")
        calls = []
        for instruction in instructions:
            encoded = {"call": b"\x28", "callvirt": b"\x6f", "newobj": b"\x73", "ldftn": b"\xfe\x06"}.get(instruction["opcode"])
            if encoded is None:
                continue
            offset, code = instruction["offset"], method["code"]
            if code[offset:offset + len(encoded)] != encoded or offset + len(encoded) + 4 > len(code):
                raise ValueError("GOG original IL call opcode differs: " + label)
            token = int.from_bytes(code[offset + len(encoded):offset + len(encoded) + 4], "little")
            target = metadata["methods"].get(token) or metadata["member_refs"].get(token) or metadata["method_specs"].get(token)
            cleaned = instruction["operand"].replace("'", "")
            if target and (("::" + target["name"]) not in cleaned or target["declaring_type"] and target["declaring_type"] not in cleaned):
                raise ValueError("GOG original IL local call target differs: " + label + " / " + target["name"] + " / " + instruction["operand"])
            calls.append({**instruction, "token": hex(token), "bytes": code[offset:offset + len(encoded) + 4].hex(),
                           "resolved_method": {key: target[key] for key in ("token", "rva", "name", "declaring_type",
                               "definition_token", "generic_signature_hex", "generic_type_arguments") if key in target} if target else None})
        selected.append({"original": original, "class_ancestry": ancestry, "label": label,
            **{key: method[key] for key in ("token", "rva", "name", "declaring_type", "header_bytes", "header_size", "code_size", "exception_sections")},
            "byte_start": len(text[:match.start()].encode()), "byte_end": len(text[:finish].encode()),
            "complete_il": body, "il_sha256": hashlib.sha256(body.encode()).hexdigest(),
            "raw_code_hex": method["code"].hex(), "raw_code_sha256": hashlib.sha256(method["code"]).hexdigest(),
            "calls": calls, "instructions": instructions, "whole_il_independently_decoded": False})
    if selected_tokens is not None and (len(selected) != len(selected_tokens)
            or {int(row["token"], 16) for row in selected} != selected_tokens):
        raise ValueError("GOG exact selected MethodDef identity/unique ownership differs")
    if not selected:
        raise ValueError("GOG selected managed IL methods are absent")
    return selected


def _profile_gog_calls(audit, source, root, callee, *, count=1):
    """Require actual AST call expressions within the selected lexical owner."""
    calls = [node for node in _help_nodes(root) if node.type == "call_expression"
             and node.child_by_field_name("function") is not None
             and node.child_by_field_name("function").text.decode() == callee]
    if len(calls) != count:
        raise ValueError("GOG actual frontend call differs: " + callee)
    return [{"original": source, "byte_start": node.start_byte, "byte_end": node.end_byte,
             "callee": callee, "arguments": node.child_by_field_name("arguments").text.decode()}
            for node in calls]


def _profile_gog_frontend(audit):
    import frontend
    source_sets = []
    for slug, pattern in (("profiles", "synapse-profiles-*"), ("gms-proxy", "gms-proxy-*")):
        current = frontend.current_source_selection("https://apps.razer.com/synapse/" + slug + "/", audit,
            candidates=sorted((audit.a.ROOT / ".analysis/inputs/frontend").glob(pattern + "/acquisition.json")))
        source_sets.append(current)
    profiles, proxy = [row.pop("originals") for row in source_sets]
    main, = [row for row in profiles if Path(row["path"]).name == "main.bceb4af9.js"]
    gms, = [row for row in proxy if Path(row["path"]).name == "main.a3d8b7f8.js"]
    selected, bindings, exports, calls, nodes = {}, {}, {}, [], {}

    def retain(role, source, anchor, syntax):
        selected[role], = audit.retain("profile_gog_" + role, source, anchor, syntax)
        row = audit.owners[selected[role]]
        nodes[role] = source, audit.tree(source).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)
        return nodes[role][1]

    def member(role, source, root, name):
        node, selected[role] = audit.callable_member("profile_gog_" + role, source, root, name)
        nodes[role] = source, node
        return node

    def binding(role, source, name, reference):
        value = audit.binding("profile_gog_" + role, source, name, reference)
        if value.get("resolution") != "declaration":
            raise ValueError("GOG actual frontend lexical import is unresolved: " + role)
        bindings[role], selected[role] = value, value["owner_id"]
        return value

    def exported(role, module, name):
        value = audit.webpack_export("profile_gog_" + role, profiles, module, name)
        exports[role], selected[role] = value, value["binding"]["owner_id"]
        nodes[role] = value["original"], _help_binding_node(audit, value["original"], value["binding"])
        return value

    bridge = retain("game_bridge", main, "this.getApplicationsIcon=", {"class", "class_declaration"})
    for name in ("componentDidMount", "gmsEventsListener", "_onConnectionEvents", "getGMSData",
            "handleMemoryStorageEvent", "handleGmsDataKeyEvent", "handleGetLocalGameListCompletedEvent",
            "handleGetUserGameListCompletedEvent", "addNewGames"):
        member("page_" + name, main, bridge, name)
    connect = retain("game_bridge_connect", main, "$=(0,c.connect)", {"variable_declarator"})
    retain("game_bridge_mount", main, "(0,v.jsx)($,{isIframe:this.props.isIframe})", {"method_definition"})
    binding("page_scan_actions", main, "D", connect.start_byte)
    binding("page_game_actions", main, "I", connect.start_byte)
    binding("page_api", main, "g", bridge.start_byte)
    if bindings["page_scan_actions"]["body"] != "D=n(38301)":
        raise ValueError("GOG scan action import differs from the actual bridge")
    for role, module, name in (("scan_action", 38301, "initiateGameScan"),
            ("scan_action_name", 98916, "kL"), ("request_key", 98916, "Rp"), ("data_key", 98916, "FB"),
            ("update_game_list", 70399, "updateGameList"), ("set_scanned_local", 70399, "setScannedLocalGame"),
            ("game_list_type", 13254, "ySx")):
        exported(role, module, name)
    for role, name in (("action_api", "r"), ("action_constants", "o")):
        binding(role, main, name, nodes["scan_action"][1].start_byte)
    api = retain("api", main, "this.getApplicationIconsAlt=", {"class", "class_declaration"})
    for name in ("setMemoryStorageItem", "getMemoryStorageItem", "callElectronAction"):
        member("api_" + name, main, api, name)
    reducer = retain("game_list_reducer", main, "ge=function(", {"variable_declarator"})
    binding("game_list_commit", main, "pe", reducer.start_byte)
    retain("game_list_registration", main, "linkedGamesReducer:ge", {"pair"})

    pages = [row for row in profiles if Path(row["path"]).name in ("6360.49064bb7.chunk.js", "1255.e55f5545.chunk.js")]
    if len(pages) != 2:
        raise ValueError("GOG current game refresh pages are missing")
    for index, source in enumerate(sorted(pages, key=lambda row: row["path"])):
        prefix = "games_popup" if Path(source["path"]).name.startswith("1255.") else "games_page"
        page = retain(prefix, source, "this.onRefresh=", {"class", "class_declaration"})
        member(prefix + "_refresh", source, page, "onRefresh")
        member(prefix + "_mount", source, page, "componentDidMount")
        member(prefix + "_render", source, page, "render")
        retain(prefix + "_connect", source,
            "P=(0,b.connect)" if prefix == "games_popup" else "ae=(0,c.connect)", {"variable_declarator"})
        binding(prefix + "_scan_import", source, "i" if prefix == "games_popup" else "v", page.start_byte)
        if prefix == "games_popup":
            member(prefix + "_unmount", source, page, "componentWillUnmount")

    sdk = retain("sdk", gms, "startScan(){return this._client.invoke(a.GmsServerMethods.StartScan)", {"class", "class_declaration"})
    for name in ("startScan", "stopScan", "setupConnectionEvents", "setupGmsServiceEvents",
            "removeGmsServiceEvents", "initializeClient", "disconnectClient", "getLocalGameList", "getUserGameList"):
        member("sdk_" + name, gms, sdk, name)
    binding("sdk_method_import", gms, "a", sdk.start_byte)
    retain("sdk_method_names", gms, 'e.StartScan="StartScan"', {"function_expression"})
    retain("sdk_callback_names", gms, 'e.OnGameScanFinishedEvent="OnGameScanFinishedEvent"', {"function_expression"})
    retain("sdk_error_codes", gms, 'e.GS_SUCCESS="GS_SUCCESS"', {"function_expression"})
    proxy_class = retain("proxy", gms, "this.handleAPIRequest=", {"class", "class_declaration"})
    binding("proxy_sdk_import", gms, "J", proxy_class.start_byte)
    for name in ("handleAPIRequest", "startScan", "stopScan", "_onConnectedEvent", "_onGameScanFinishedEvent",
            "_onLocalGameListXmlUpdatedEvent", "getLocalGameList", "getUserGameList", "updateGMSData_MemoryStorage",
            "createGmsClient", "unsubscribeEvent", "logout", "setMemoryStorageItem"):
        member("proxy_" + name, gms, proxy_class, name)
    for role, callee in (("page__onConnectionEvents", "this.props.initiateGameScan"),
            ("games_page_refresh", "this.props.initiateGameScan"), ("games_popup_refresh", "this.props.initiateGameScan"),
            ("scan_action", "r.A.setMemoryStorageItem"), ("proxy_handleAPIRequest", "this.startScan"),
            ("proxy_startScan", "this.gmsClient.startScan"), ("proxy_stopScan", "this.gmsClient.stopScan"),
            ("sdk_startScan", "this._client.invoke"), ("sdk_stopScan", "this._client.invoke"),
            ("proxy__onGameScanFinishedEvent", "this.getLocalGameList"),
            ("proxy__onGameScanFinishedEvent", "this.getUserGameList"),
            ("proxy__onGameScanFinishedEvent", "this.updateGMSData_MemoryStorage"),
            ("proxy_updateGMSData_MemoryStorage", "this.setMemoryStorageItem"),
            ("page_handleGmsDataKeyEvent", "this.handleGetLocalGameListCompletedEvent"),
            ("page_handleGmsDataKeyEvent", "this.addNewGames"), ("page_addNewGames", "this.props.updateGameList")):
        source, node = nodes[role]
        calls.extend({"owner_role": role, **row} for row in _profile_gog_calls(audit, source, node, callee))
    return {"source_sets": source_sets, "selected": selected, "bindings": bindings,
            "exports": exports, "verified_calls": calls}


def _profile_gog_managed(audit, selected):
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for item in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / item["path"], item)
    packages = [row for row in release["files"]
        if row.get("declaration", {}).get("resourceName") == "ExtraInstaller_RazerGameManager"]
    if len(packages) != 1 or packages[0]["declaration"]["resourceVersion"] != "3.15.0.1200":
        raise ValueError("GOG current GMS declaration requires semantic review")
    package, = packages
    audit.artifact(audit.a.ROOT / package["path"], package)
    extracted = current_host_extracted_inputs(indexed, release)
    originals = {row["path"]: row for row in indexed["inputs"]}
    host_members = []
    for suffix in ("electron/main.js", "electron/modules/memory_storage/index.js"):
        members = [row for row in current_host_asar_members(audit, indexed, release) if row["path"].endswith("/" + suffix)]
        if len(members) != 1:
            raise ValueError("GOG current host storage member is absent or ambiguous")
        source, = members
        archive = originals[source["container"]]
        ancestors = [row for row in release["files"] if row.get("path") == archive.get("container")
                     and row.get("sha256") == archive.get("container_sha256") and row.get("manifest_identity_verified")]
        body, archive_bytes = audit.read(source), audit.read(archive)
        if (len(ancestors) != 1 or source["container_sha256"] != archive["sha256"]
                or source.get("unpacked") or type(source.get("offset")) is not int
                or archive_bytes[source["offset"]:source["offset"] + len(body)] != body):
            raise ValueError("GOG current host storage ASAR bytes or package ancestry differs")
        audit.artifact(audit.a.ROOT / ancestors[0]["path"], ancestors[0])
        host_members.append({"member": source, "archive": archive, "official_package": ancestors[0],
                             "member_offset_verified": True})
        if suffix.endswith("main.js"):
            selected["host_storage_dispatch"], = audit.retain("profile_gog_host_storage_dispatch", source,
                'case"setMemoryStorageItem":', {"switch_case"})
            selected["host_storage_call"], = audit.retain("profile_gog_host_storage_call", source,
                "return b.memoryStorage?.callFunction(n,i)", {"return_statement"})
        else:
            key, = audit.retain("profile_gog_host_memory_storage", source, "callFunction=async", {"class", "class_declaration"})
            selected["host_memory_storage"] = key
            owner = audit.owners[key]
            node = audit.tree(source).root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
            for name in ("callFunction", "shouldFireEvent"):
                _, selected["host_memory_" + name] = audit.callable_member("profile_gog_host_memory_" + name, source, node, name)

    capture_path = audit.a.ROOT / ".analysis/results/host-current/managed/capture.json"
    capture = json.loads(audit.artifact(capture_path))
    if capture.get("target_execution") is not False:
        raise ValueError("GOG managed input capture is not static")
    specifications = {
        "GameManagerServiceLib.dll": {
            "GameScannerStrategyGogRegistrySearch": (".ctor", ".cctor", "GetGogData", "ScanAsync", "<ScanAsync>"),
            "GameManagerServiceHub": ("StartScan", "StopScan", "GetClientInstance", "GetLocalGameListPartial",
                "<GetLocalGameListPartial>", "GetUserGameListPartial", "<GetUserGameListPartial>", "GetGameSettingsList"),
            "GameScanner": (".ctor", "StartScan", "StopScan", "SetState", "NotifyGameFound", "NotifyScanFinished"),
            "GameScannerController": (".ctor", "StartScan", "<StartScan>", "StopScan", "OnStartScan", "<OnStartScan>",
                "GameScannerStrategyOnGameFoundEvent", "RemoveDuplicateGameSettings", "<RemoveDuplicateGameSettings>",
                "RemovePostScanDuplicates", "<RemovePostScanDuplicates>"),
            "GameScannerStoppedState": (".ctor", "StartScan", "StopScan", "get_IsScanning"),
            "GameScannerScanningState": (".ctor", "StartScan", "StopScan", "get_IsScanning"),
            "GameScannerStrategyBase": (".ctor", "StopScan", "ResetStopScanFlag", "GetStopScanFlag", "CanSkipGame",
                "CreateEntryGuid", "AddFoundGame", "<AddFoundGame>", "NotifyGameFound", "ExtractIconForGameSignature"),
            "GameManagerServiceBroadcaster": (".ctor", "InitializeGameScanner", "RegisterGameScanningEvent",
                "UnregisterGameScannerEvents", "GameScannerManagerOnGameFoundEvent", "<GameScannerManagerOnGameFoundEvent>",
                "GameScannerManagerOnScanFinishedEvent", "<GameScannerManagerOnScanFinishedEvent>",
                "GameListAndSettingsManagerOnLocalGameListXmlUpdatedEvent", "<GameListAndSettingsManagerOnLocalGameListXmlUpdatedEvent>",
                "GameListAndSettingsManagerOnLocalGameListXmlUpdatedWithUserIdEvent", "<GameListAndSettingsManagerOnLocalGameListXmlUpdatedWithUserIdEvent>"),
            "LglDataManager": ("GetLocalGameList", "GetLocalGameListCached", "SetLocalGameList", "SaveLocalGameList",
                "SaveExtendedLocalGameList", "NotifyLocalGameListXmlUpdated", "NotifyLocalGameListXmlUpdatedWithUserId"),
            "GslDataManager": ("UpdateGameSetting", "SetGameSettingsCache", "GetGameSettingsFromCache", "RemoveGameSettingsFromCache",
                "LoadGameSettingsCache", "FixGameSettingsCacheColors", "SaveGameSettingsCache"),
            "IoUtil": ("CreateAes",),
            "CaseInsensitiveTupleEqualityComparer": ("Equals", "GetHashCode"),
        },
        "GameScannerCommon.dll": {
            "RegistryWrapper": ("GetRegistryGroup",), "PathWrapper": ("FileExists", "CanonicalizePath"),
            "GameSignatureHelper": ("FixLaunchHelpers", "ExtractDefaultFolderExe", "CorrectExe", "GetCorrectExe"),
            "GameSignature": ("CopyMissingGameSignatureSettings",),
            "CryptoXmlSerializer": ("Serialize", "Deserialize"),
        },
        "GameManagerService3.dll": {"ServiceRegister": ("RegisterService",)},
    }
    assemblies = []
    for filename, methods in specifications.items():
        candidates = [row for row in extracted if row["container_sha256"] == package["sha256"]
                      and Path(row["path"]).name == filename]
        if len(candidates) != 1:
            raise ValueError("GOG current managed original is absent or ambiguous: " + filename)
        original, = candidates
        raw = audit.read(original)
        audit.artifact(audit.a.ROOT / original["extraction_receipt"]["path"], original["extraction_receipt"])
        records = [row for row in capture["assemblies"] if row["input_sha256"] == original["sha256"]]
        if len(records) != 1:
            raise ValueError("GOG current managed assembly has not been captured: " + filename)
        record, = records
        if (record.get("capture_complete") is not True or record.get("input_bytes_unchanged") is not True
                or filename != "GameManagerService3.dll" and (record.get("all_csharp_resolved") is not True or record.get("diagnostics"))):
            raise ValueError("GOG current selected managed capture is incomplete: " + filename)
        bindings = [row for row in record["acquisition_bindings"] if row["path"] == original["path"]]
        if len(bindings) != 1 or any(bindings[0][key] != original[key] for key in ("bytes", "sha256", "container", "container_sha256")):
            raise ValueError("GOG current managed capture acquisition differs: " + filename)
        metadata = _profile_gog_clr(raw)
        versions = [row["tree"].get("file_version") for row in metadata["pe"]["version_resources"]]
        if versions != ["3.15.0.1200"]:
            raise ValueError("GOG managed file version requires semantic review: " + filename)
        il_rows = [row for row in record["outputs"] if row["path"].endswith("/il.stdout.txt")]
        if len(il_rows) != 1:
            raise ValueError("GOG complete captured IL is absent or ambiguous")
        il_artifact, = il_rows
        il = audit.artifact(audit.a.ROOT / il_artifact["path"], il_artifact).decode("utf-8-sig")
        sources = []
        for class_name in methods:
            rows = [row for row in record["outputs"] if row["path"].endswith("/" + class_name + ".cs")]
            if len(rows) != 1:
                raise ValueError("GOG complete current C# owner is absent or ambiguous: " + class_name)
            artifact, = rows
            body = audit.artifact(audit.a.ROOT / artifact["path"], artifact).decode("utf-8-sig")
            sources.append({"class": class_name, "artifact": artifact, "complete_source": body})
        selected_methods = _profile_gog_il_methods(original, il, metadata, methods)
        if set(methods) != {row["class_ancestry"][0].split(".")[-1] for row in selected_methods}:
            raise ValueError("GOG selected current managed class methods are incomplete")
        assemblies.append({"original": original, "file_versions": versions,
            "capture_input": {key: record[key] for key in ("input", "input_sha256", "input_bytes", "capture_complete", "all_csharp_resolved", "diagnostics")},
            "il_artifact": il_artifact, "complete_source_owners": sources,
            "complete_methods": selected_methods, "pe_kind": metadata["pe"]["kind"],
            "clr": metadata["pe"]["clr"], "pe_machine_does_not_fix_CLR_runtime_architecture": True})
    return {"version": release["version"], "acquisition": release["receipt"],
            "official_gms_package": package, "host_members": host_members}, {
        "capture": audit.families.identity(capture_path), "analyzer": capture["tool"], "assemblies": assemblies,
        "only_selected_capture_reused": True, "old_gms_3_14_used_as_current": False,
        "whole_IL_independently_decoded": False, "framework_execution": False}


def _profile_gog_managed_edges(assemblies):
    methods = [row for assembly in assemblies for row in assembly["complete_methods"]]
    edges = []

    def require(root, name, target_name, target_type=None, *, state=None):
        callers = [row for row in methods if row["class_ancestry"][0].split(".")[-1] == root
                   and row["name"] == name and (state is None or any(state in value for value in row["class_ancestry"]))]
        matches = [(caller, call) for caller in callers for call in caller["calls"]
            if call["resolved_method"] and call["resolved_method"]["name"] == target_name
            and (target_type is None or (call["resolved_method"]["declaring_type"] or "").endswith("." + target_type))]
        if not matches:
            raise ValueError("GOG actual managed call edge is absent: " + root + "." + name + " -> " + target_name)
        for caller, call in matches:
            edges.append({"assembly": caller["original"]["sha256"], "caller_token": caller["token"],
                "caller_rva": caller["rva"], "caller": root + "." + name, "offset": call["offset"],
                "target": call["resolved_method"], "bytes": call["bytes"]})
        return matches

    for caller, name, target, owner, state in (
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "GetRegistryGroup", "IRegistryWrapper", None),
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "FileExists", "IPathWrapper", None),
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "CreateEntryGuid", "GameScannerStrategyBase", None),
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "GetStopScanFlag", "GameScannerStrategyBase", None),
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "GetOrAdd", None, None),
            ("GameScannerStrategyGogRegistrySearch", "GetGogData", "TryUpdate", None, None),
            ("GameScannerStrategyGogRegistrySearch", "MoveNext", "GetGogData", "GameScannerStrategyGogRegistrySearch", "<ScanAsync>"),
            ("GameScannerStrategyGogRegistrySearch", "MoveNext", "CanSkipGame", "GameScannerStrategyBase", "<ScanAsync>"),
            ("GameScannerStrategyGogRegistrySearch", "MoveNext", "AddFoundGame", "GameScannerStrategyBase", "<ScanAsync>"),
            ("RegistryWrapper", "GetRegistryGroup", "OpenBaseKey", "RegistryKey", None),
            ("RegistryWrapper", "GetRegistryGroup", "OpenSubKey", "RegistryKey", None),
            ("RegistryWrapper", "GetRegistryGroup", "GetSubKeyNames", "RegistryKey", None),
            ("RegistryWrapper", "GetRegistryGroup", "GetValue", "RegistryKey", None),
            ("GameScannerStrategyBase", "AddFoundGame", "FixLaunchHelpers", "IGameSignatureHelper", None),
            ("GameScannerStrategyBase", "AddFoundGame", "ExtractDefaultFolderExe", "IGameSignatureHelper", None),
            ("GameScannerStrategyBase", "AddFoundGame", "CorrectExe", "IGameSignatureHelper", None),
            ("GameScannerStrategyBase", "AddFoundGame", "NotifyGameFound", "GameScannerStrategyBase", None),
            ("GameScannerStrategyBase", "CreateEntryGuid", ".ctor", "HMACMD5", None),
            ("GameScannerController", "MoveNext", "WaitAll", "Task", "<OnStartScan>d"),
            ("GameScannerController", "MoveNext", "SetLocalGameList", "ILglDataManager", "<OnStartScan>d"),
            ("GameScannerController", "MoveNext", "RemovePostScanDuplicates", "GameScannerController", "<OnStartScan>d"),
            ("GameScannerController", "MoveNext", "NotifyScanFinished", "IGameScanner", "<OnStartScan>d"),
            ("GameScannerController", "MoveNext", "SaveLocalGameList", "ILglDataManager", "<OnStartScan>d"),
            ("GameScannerController", "MoveNext", "ResetStopScanFlag", "IGameScannerStrategy", "<OnStartScan>d"),
            ("GameScannerController", "RemovePostScanDuplicates", "RemoveDuplicateGameSettings", "GameScannerController", None),
            ("GameScannerController", "RemoveDuplicateGameSettings", "GetGameSettingsFromCache", "IGslDataManager", None),
            ("GameScannerController", "RemoveDuplicateGameSettings", "RemoveGameSettingsFromCache", "IGslDataManager", None),
            ("GameScannerController", "RemoveDuplicateGameSettings", "SetGameSettingsCache", "IGslDataManager", None),
            ("GameManagerServiceHub", "StartScan", "StartScan", "IGameScanner", None),
            ("GameManagerServiceHub", "StopScan", "StopScan", "IGameScanner", None),
            ("GameScannerController", "GameScannerStrategyOnGameFoundEvent", "NotifyGameFound", "IGameScanner", None),
            ("GameScanner", "NotifyGameFound", "UpdateGameSetting", "IGslDataManager", None),
            ("LglDataManager", "SaveLocalGameList", "Serialize", "ICryptoXmlSerializer", None)):
        require(caller, name, target, owner, state=state)
    registration, = [row for row in methods if row["class_ancestry"][0].endswith(".ServiceRegister") and row["name"] == "RegisterService"]
    bindings = [row for row in registration["calls"] if row["resolved_method"]
        and row["resolved_method"].get("generic_type_arguments") == ["Razer.GameManagerServiceLib.IGameScannerStrategy",
            "Razer.GameManagerServiceLib.GameScannerStrategyGogRegistrySearch"]]
    if len(bindings) != 1 or bindings[0]["resolved_method"]["name"] != "AddScoped":
        raise ValueError("GOG strategy registration has no original MethodSpec type binding")
    worker, = [row for row in methods if row["class_ancestry"][0].endswith(".GameScannerController")
               and row["name"] == "MoveNext" and any("<OnStartScan>d" in name for name in row["class_ancestry"])]
    discarded = []
    for target in ("WaitAll", "SaveLocalGameList"):
        call, = [row for row in worker["calls"] if row["resolved_method"] and row["resolved_method"]["name"] == target]
        offset = call["offset"] + len(bytes.fromhex(call["bytes"]))
        instruction, = [row for row in worker["instructions"] if row["offset"] == offset]
        if instruction["opcode"] != "pop" or bytes.fromhex(worker["raw_code_hex"])[offset] != 0x26:
            raise ValueError("GOG controller ignored-return original pop differs: " + target)
        discarded.append({"caller_token": worker["token"], "target": target, "call_offset": call["offset"],
                          "pop_offset": offset, "original_pop_byte": "26"})
    return {"verified_call_edges": edges, "gog_scoped_registration": {"caller_token": registration["token"],
        "offset": bindings[0]["offset"], "bytes": bindings[0]["bytes"], "target": bindings[0]["resolved_method"]},
        "discarded_return_evidence": discarded,
        "selected_service_csharp_diagnostics": [row for row in assemblies[-1]["capture_input"]["diagnostics"]
            if row["path"].endswith("/ServiceRegister.cs")],
        "service_diagnostic_scope": "RegisterService IL_00d5/00dc RazerAnalytics construction; GOG registration independently bound to original MethodSpec"}


def _profile_gog_boundaries():
    return {
        "scope": "Current Windows GOG registry strategy and its actual shared scan/result/stop consumers",
        "registry": {"hive": "LocalMachine", "view": "Registry32", "key": "SOFTWARE\\GOG.com\\Games\\",
            "values": ["exe", "launchParam", "gameName"], "read_before_stop_check": True,
            "wrapper_exception": "return_completed_prefix", "explicit_key_disposal": False,
            "strategy_per_entry_exception": "continue", "strategy_outer_exception": "return_collected_prefix"},
        "strategy": {"priority": "High", "priority_value": 4, "source": "GOGGALAXY", "detect_method": "GOG_REGISTRY",
            "title_marks_removed": ["™", "®"], "path_quotes_removed_for_exists_only": True,
            "guid": "HMACMD5(Encoding.Default(platform-key),Encoding.Default(gog+platform-id));hex-to-Guid",
            "empty_platform_id": "defaultGuid", "helper_TryUpdate_result_checked": False,
            "scan_item_catch": False, "clear_in_finally": False, "async_has_await_suspension": False},
        "controller": {"start_success": "accepted_Task.Run_not_scan_completed", "token_passed_to_ScanAsync": False,
            "wait_timeout_bool_checked": False, "timeout_cancels_or_joins_strategies": False,
            "stop_joins_strategies": False, "stop_notification_completed": False,
            "normal_finished_before_file_save": True, "save_local_result_checked": False,
            "cancellation_sources_disposed": False, "strategy_scope_disposed": False,
            "stale_generation_guard": False, "async_void_worker_catch_guaranteed": False},
        "events": {"found_before_setting_update": True, "broadcaster_async_void_awaited_by_publisher": False,
            "finished_segment_size": 16, "empty_finished_sends_one_segment": True,
            "finished_request_id": False, "unsubscribe_joins_sends": False},
        "post_scan": {"before_icons_and_finished": True, "memory_list_set_before_dedup": True,
            "group_path": "nonempty LaunchExe.ToLower using current culture", "sort": "master membership then LaunchExe mapping membership; both descending",
            "single_steam_group": "copy source/icon/registry from Steam candidate into selected winner; preserve selected GUID",
            "nonsteam_duplicates": "copy missing fields into first ordered candidate and remove the rest",
            "ugl_guid_duplicates": "copy missing into UGL object and remove from local scan list",
            "launch_helper_index": "CurrentCultureIgnoreCase; local and UGL included helpers to Guid sets",
            "remove_helper_candidate": "LaunchExe matches helper key whose Guid set excludes this candidate",
            "setting_changes": "cache only here; empty winner cache creates entry; extra winner and removed Guid settings deleted",
            "return_codes_checked": False, "atomic_or_rollback": False,
            "dedup_exception": "outer controller catch logs then continues; already applied changes remain"},
        "frontend": {"request": "gms-api-request/scanGame", "iframe_request_suppressed": "profiles-\\d+",
            "pending_scan_before_connection": True, "stop_action_in_request_switch": False,
            "failed_start_clears_isScanning": False, "finished_checks_scanCompleted": False,
            "partial_list_generation_guard": False, "memory_publish": "zero-delay_timer_not_awaited",
            "list_commit_clears_syncing": True, "bridge_unmount_handler": False,
            "logout_awaits_disconnect": False, "queued_memory_timers_cancelled": False,
            "list_update_proves_file_or_device_write": False},
        "dependencies": {"other_scan_strategies_reviewed_here": False, "icon_extraction_review_repeated": False,
            "service_connection_identity_is_unchanged_without_review": False,
            "all_framework_and_crypto_internals_reviewed_here": False}}


def _profile_gog_projection(report):
    owners = {row["id"]: row for row in report["complete_source_owners"]}
    selected = {}
    for role, key in report["selected"].items():
        row = owners[key]
        if hashlib.sha256(row["body"].encode()).hexdigest() != row["body_sha256"]:
            raise ValueError("GOG complete source body differs")
        selected[role] = {name: row[name] for name in ("original", "syntax", "byte_start", "byte_end", "body_sha256")}
    return {"selected": selected, **{key: report[key] for key in (
        "source_sets", "bindings", "exports", "verified_calls", "host_release", "managed", "dependencies", "boundaries")}}


def _verify_profile_gog_claims(report):
    if report.get("boundaries") != _profile_gog_boundaries():
        raise ValueError("GOG failure, cancellation or release boundary differs")
    if (report.get("schema_version") != 1 or report.get("query") != "profile-gog-scanner"
            or report.get("selected_source_chain_complete") is not True or report.get("source_chain_complete") is not False
            or report.get("whole_profiles_complete") is not False or report.get("target_execution") is not False
            or report.get("product_code_modified") is not False or report.get("real_device_operations") is not False
            or any(report.get(name) != "unverified" for name in ("rust_independent_implementation", "ui_backend_wiring",
                "actual_dll_comparison", "runtime_acceptance")) or report.get("failures")
            or report.get("changed_during_query") or report.get("snapshot_stable") is not True):
        raise ValueError("GOG static review was promoted or its snapshot failed")
    digest = hashlib.sha256(json.dumps(_profile_gog_projection(report), ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    if digest != "895d40d6d74b06159782982f7906103933586f13e4fae5e01eb4722bf7be2250" or digest != report["reviewed_selection_sha256"]:
        raise ValueError("GOG selected bytes require complete semantic review: " + digest)
    return {"selected_source_owners": len(report["selected"]),
        "managed_assemblies": len(report["managed"]["assemblies"]),
        "complete_managed_methods": sum(len(row["complete_methods"]) for row in report["managed"]["assemblies"]),
        "verified_frontend_calls": len(report["verified_calls"]), "selected_strategy": "GameScannerStrategyGogRegistrySearch",
        "target_execution": False, "runtime_acceptance": "unverified"}


def collect_profile_gog_scanner(audit):
    """Continue the Profiles receipts through the current local GOG scan strategy."""
    report = {"schema_version": 1, "query": "profile-gog-scanner", "kind": "current_profile_gog_scanner",
        **_profile_gog_frontend(audit), "boundaries": _profile_gog_boundaries(),
        "selected_source_chain_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "target_execution": False, "real_device_operations": False, "product_code_modified": False,
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified",
        "actual_dll_comparison": "unverified", "runtime_acceptance": "unverified", "failures": []}
    report["host_release"], report["managed"] = _profile_gog_managed(audit, report["selected"])
    report["managed"].update(_profile_gog_managed_edges(report["managed"]["assemblies"]))
    upstream = json.loads((audit.a.ROOT / ".analysis/results/host-current/local-audit.json").read_bytes())
    report["dependencies"] = [{"receipt": ".analysis/results/host-current/local-audit.json", "section": section,
        "kind": upstream[section]["kind"], "section_sha256": hashlib.sha256(json.dumps(upstream[section],
            ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest(),
        "reuse": "current game-list/icon consumer evidence; no repeat icon native analysis",
        "remaining_chains": upstream[section]["remaining_chains"]}
        for section in ("profile_local_applications", "profile_alternate_icons")]
    report["complete_originals"] = list(audit.sources.values())
    report["complete_source_owners"] = list(audit.owners.values())
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_gog_projection(report),
        ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    report["remaining_chains"] = [
        "Other current service scanning strategies and their actual local inputs/dependencies",
        "Service mutations, automatic profile writers and other Profiles UI/backend chains",
        "Independent Rust implementation and automated behavior tests",
        "Actual DLL/service/device comparison and runtime acceptance"]
    report["verification"] = _verify_profile_gog_claims(report)
    return report


def collect_profile_alternate_icons(audit):
    """Continue the existing icon receipt with the actual Alt consumers only."""
    import frontend
    current = frontend.current_source_selection("https://apps.razer.com/synapse/profiles/", audit,
        candidates=sorted((audit.a.ROOT / ".analysis/inputs/frontend").glob("synapse-profiles-*/acquisition.json")))
    originals = current.pop("originals")
    mains = [row for row in originals if row["path"].endswith(".js") and b"this.getApplicationsIcon=" in audit.read(row)]
    if len(mains) != 1:
        raise ValueError("Current Profiles Alt consumer source is absent or ambiguous")
    main, = mains
    original, host, release = _profile_local_applications_release(audit)
    selected, bindings, exports = {}, {}, {}

    def retain(role, source, anchor, kinds):
        selected[role], = audit.retain("profile_alt_" + role, source, anchor, kinds)
        row = audit.owners[selected[role]]
        return audit.tree(source).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)

    def member(role, source, root, name):
        node, selected[role] = audit.callable_member("profile_alt_" + role, source, root, name)
        return node

    def binding(role, source, name, reference):
        value = audit.binding("profile_alt_" + role, source, name, reference)
        if value.get("resolution") != "declaration":
            raise ValueError("Profile Alt lexical binding is unresolved: " + role)
        bindings[role], selected[role] = value, value["owner_id"]

    bridge = retain("game_bridge", main, "this.getApplicationsIcon=", {"class", "class_declaration"})
    api = retain("api_class", main, "this.getApplicationIconsAlt=", {"class", "class_declaration"})
    for name in ("getApplicationsIcon", "setCustomGameCover", "addNewGames", "handleGmsDataKeyEvent",
            "handleGetLocalGameListCompletedEvent", "handleGetUserGameListCompletedEvent", "componentDidMount",
            "gmsEventsListener", "handleMemoryStorageEvent"):
        member(name, main, bridge, name)
    for name in ("getApplicationIconsAlt", "getApplicationIcons", "callElectronAction", "isElectronApp"):
        member(name, main, api, name)
    connect = retain("game_bridge_connect", main, "$=(0,c.connect)", {"variable_declarator"})
    retain("game_bridge_mount", main, "(0,v.jsx)($,{isIframe:this.props.isIframe})", {"method_definition"})
    for role, name, reference in (("api_import", "g", bridge.start_byte),
            ("game_actions_import", "I", connect.start_byte), ("scan_actions_import", "D", connect.start_byte)):
        binding(role, main, name, reference)
    for role, module, name in (("api_export", 37226, "A"), ("update_game_list", 70399, "updateGameList"),
            ("scanned_user_list", 70399, "setScannedUserGame"), ("scanned_local_list", 70399, "setScannedLocalGame"),
            ("removed_games", 70399, "setRemovedGames"), ("game_list_type", 13254, "ySx"),
            ("gms_data_key", 98916, "FB")):
        value = audit.webpack_export("profile_alt_" + role, originals, module, name)
        exports[role], selected[role] = value, value["binding"]["owner_id"]
    reducer = retain("game_list_reducer", main, "ge=function(", {"variable_declarator"})
    binding("game_list_commit", main, "pe", reducer.start_byte)
    retain("game_list_registration", main, "linkedGamesReducer:ge", {"pair"})
    calls = _profile_alternate_icon_calls(audit, originals, {
        role: (audit.owners[selected[role]], size) for role, size in (
            ("getApplicationsIcon", [80, 80]), ("setCustomGameCover", [300, 150]))})

    hmain, win, mac, ffi = (host[name] for name in ("electron/main.js", "electron/modules/sysutil/win/index.js",
        "electron/modules/sysutil/mac/index.js", "electron/modules/ffi/ffiMain.js"))
    retain("host_alt_case", hmain, 'case"getApplicationIconsAlt":', {"switch_case"})
    binding("host_sysutil_instance", hmain, "po", audit.owners[selected["host_alt_case"]]["byte_start"])
    retain("host_sysutil_import", hmain, "FFISysUtils:lo", {"variable_declarator"})
    retain("host_dll_initialization", hmain, 'let n="SysUtilsNative.dll"', {"arrow_function"})
    retain("host_platform_selector", host["electron/modules/sysutil/index.js"],
           '"win32"===process.platform', {"program"})
    for platform, source in (("windows", win), ("macos", mac)):
        member(platform + "_init", source, audit.tree(source).root_node, "initDll")
        member(platform + "_async", source, audit.tree(source).root_node, "callDLLAsync")
        binding(platform + "_channel", source, "s", audit.owners[selected[platform + "_async"]]["byte_start"])
    retain("ffi_async", ffi, "exports.callDLLMainAsync=", {"assignment_expression"})
    retain("ffi_sync", ffi, "exports.callDLLMain=", {"assignment_expression"})
    binding("ffi_library_map", ffi, "o", audit.owners[selected["ffi_async"]]["byte_start"])
    declarations = {}
    for platform, source in (("windows", win), ("macos", mac)):
        rows, pending = {}, [audit.tree(source).root_node]
        expected = {"getInstalledApplicationList": ["pointer", []],
            "getApplicationIcons": ["pointer", ["string", "int", "int"]], "FreeMalloc": ["void", ["pointer"]]}
        if platform == "windows":
            expected["getApplicationIconsAlt"] = ["pointer", ["string", "int", "int"]]
        while pending:
            node = pending.pop()
            pending.extend(node.named_children)
            key = node.child_by_field_name("key") if node.type == "pair" else None
            name = key.text.decode() if key is not None else None
            if name not in {*expected, "getApplicationIconsAlt"}:
                continue
            if name not in expected or name in rows or json.loads(node.child_by_field_name("value").text) != expected[name]:
                raise ValueError("Profile Alt platform declaration differs: " + platform + ":" + name)
            owner = audit.retain_range("profile_alt_" + platform + "_abi_" + name,
                source, node.start_byte, node.end_byte, node.type)
            selected[platform + "_abi_" + name] = owner
            rows[name] = {"signature": expected[name], "owner_id": owner}
        if set(rows) != set(expected):
            raise ValueError("Profile Alt platform declarations are incomplete: " + platform)
        declarations[platform] = rows

    roles = {rva: _profile_local_applications_native_functions()[rva] for rva in (
        0x3850, 0x3b7b0, 0x3bbb0, 0x3d590, 0x3ed20, 0x40490, 0x41120, 0x41770,
        0x44e20, 0x69d10, 0x9b120, 0x9dae0)}
    roles.update({0x431c0: "alternate_icons_body", 0x41590: "cache_store_successful_source",
        0x44fa0: "json_path_field_lookup", 0x45be0: "batch_cache_key_insertion", 0x6f080: "getApplicationIconsAlt"})
    native = audit.families.verify_native_functions(original, roles,
        exports={"getApplicationIconsAlt": 0x6f080, "FreeMalloc": 0x69d10})
    directory = audit.a.ROOT / ".analysis/results/native" / original["sha256"]
    capture = json.loads(audit.artifact(directory / "capture.json", native["capture_receipt"]))
    for output in capture["outputs"]:
        audit.artifact(directory / output["path"], output)
    native["all_pseudocode_captured"] = capture["all_pseudocode_captured"]
    native["selected_pseudocode_failures"] = native_pseudocode_failures(
        native["complete_selected_functions"], capture["failures"], int(native["image_base"], 16))
    functions = {int(row["capture"]["rva"], 16): row["capture"] for row in native["complete_selected_functions"]}
    edges = []
    for caller, target in [(0x6f080, 0x431c0)] + [(0x431c0, target) for target in (
            0x44e20, 0x44fa0, 0x3ed20, 0x45be0, 0x3d590, 0x41120, 0x3bbb0,
            0x3b7b0, 0x41590, 0x41770, 0x40490, 0x3850, 0x9b120, 0x9dae0)]:
        sites = [row["address"] for row in functions[caller]["assembly"]
            if row["text"].split()[0].lower() in {"call", "jmp"}
            and any(ref.get("code") and ref.get("type") in {17, 18, 19, 20}
                and int(ref["to"], 16) == int(native["image_base"], 16) + target for ref in row["xrefs_from"])]
        if not sites:
            raise ValueError("Profile Alt native call edge is absent: " + hex(caller) + " -> " + hex(target))
        edges.append({"caller_rva": hex(caller), "target_rva": hex(target), "instruction_addresses": sites})
    native["verified_call_edges"] = edges
    for row in native["complete_selected_functions"]:
        body = row.pop("capture")
        if not row["pseudocode_captured"] or row["failures"]:
            raise ValueError("Profile Alt selected native body is incomplete: " + row["role"])
        row["rva"] = body["rva"]
        row["pseudocode_text_sha256"] = hashlib.sha256("\n".join(
            line["text"] for line in body["pseudocode"]["lines"]).encode("utf-8")).hexdigest()
        audit.artifact(audit.a.ROOT / row["artifact"]["path"], row["artifact"])
    index = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    mac_candidates = [row["path"] for row in index["inputs"] if
        Path(row["path"]).suffix.lower() in {".dylib", ".dmg", ".pkg"} or ".app/" in row["path"].lower()]
    if mac_candidates:
        raise ValueError("Profile Alt retained Mac originals require a new native review")
    report = {"schema_version": 1, "kind": "current_profile_alternate_icons", "query": "profile-alternate-icons",
        "recorded_at_utc": audit.a.stamp(), "parser": audit.parser_versions, "source_set": current,
        "host_release": release, "selected": selected, "bindings": bindings, "cross_chunk_exports": exports,
        "ffi_declarations": declarations, "actual_alt_calls": calls, "native": native,
        "boundaries": _profile_alternate_icons_boundaries(),
        "macos_native": {"status": "not_acquired", "retained_candidates": mac_candidates,
            "absence_of_feature_inferred": False},
        "dependencies": [{"receipt": ".analysis/results/host-current/local-audit.json",
            "section": "profile_local_applications",
            "reviewed_selection_sha256": "9c0f79c29de599770635d6fadf3335a2371835f94cdb7f68827dd64d895c8060",
            "scope": "Reuse current ordinary ICO/PNG extraction, cache persistence, pointer ownership and preload/IPC closure; do not reassign Add App to Alt"}],
        "remaining_chains": ["Acquire current Mac native originals and verify enumeration/icon bodies without inferring absence",
            "Continue scanner strategies, game/service writes and product automatic-profile writers through their existing owners",
            "After full semantic reverse work, implement independent Rust and UI/backend wiring, then actual DLL/service/device comparisons"],
        "windows_source_chain_complete": True, "source_chain_complete": False, "whole_profiles_complete": False,
        "product_code_modified": False, "target_execution": False, "real_device_operations": False,
        "actual_dll_comparison": "unverified", "rust_independent_implementation": "unverified",
        "ui_backend_wiring": "unverified", "runtime_acceptance": "unverified", "failures": [],
        "maintenance_lifecycle": {"temporary_artifacts_created": [], "analysis_sessions_created": [],
            "reused_complete_native_capture": True}}
    report["complete_originals"] = list(audit.sources.values())
    report["complete_source_owners"] = list(audit.owners.values())
    report["reviewed_selection_sha256"] = hashlib.sha256(json.dumps(_profile_alternate_icons_projection(report),
        ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["verification"] = _verify_profile_alternate_icons_claims(report)
    return report


def _profile_mac_sysutils_inputs(audit):
    """Verify Mac JS as a member of the selected package without using Windows native code."""
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for row in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / row["path"], row)
    originals = {row["path"]: row for row in indexed["inputs"]}
    packages = {row["path"]: row for row in release["files"] if row.get("manifest_identity_verified")}
    members = current_host_asar_members(audit, indexed, release)
    selected, ancestry = {}, []
    for suffix in ("electron/main.js", "electron/modules/sysutil/index.js", "electron/modules/sysutil/mac/index.js",
            "electron/modules/ffi/ffiMain.js", "electron/mainSubFunction.js", "electron/lib/common.js"):
        candidates = [row for row in members if row["path"].endswith("/" + suffix)]
        if len(candidates) != 1:
            raise ValueError("Current Mac SysUtils source is absent or ambiguous: " + suffix)
        source = candidates[0]
        archive = originals[source["container"]]
        package = packages.get(archive["container"])
        if (package is None or archive["container_sha256"] != package["sha256"]
                or source["container_sha256"] != archive["sha256"] or source.get("unpacked")
                or type(source.get("offset")) is not int):
            raise ValueError("Current Mac SysUtils package/ASAR ancestry changed: " + suffix)
        raw = audit.read(source)
        if audit.read(archive)[source["offset"]:source["offset"] + len(raw)] != raw:
            raise ValueError("Current Mac SysUtils source differs from actual ASAR bytes: " + suffix)
        audit.artifact(audit.a.ROOT / package["path"], package)
        for row in (archive, source):
            dependency = row.get("extraction_receipt")
            if dependency:
                audit.artifact(audit.a.ROOT / dependency["path"], dependency)
        selected[suffix] = source
        ancestry.append({"member": source, "archive": archive, "official_package": package, "member_offset_verified": True})
    mac = selected["electron/modules/sysutil/mac/index.js"]
    if (release["version"] != "4.0.896" or mac["sha256"] != "b739d78a2253d67de0e2aae4f3e2fc6f4bfc049bd26f0d55a8c5fdee861bc299"
            or mac["bytes"] != 4963 or mac["offset"] != 3739509):
        raise ValueError("Current Mac SysUtils release requires a new source review")
    return selected, {"version": release["version"], "receipt": release["receipt"], "host_members": ancestry,
        "mac_native_version": "unobserved", "current_js_from_windows_package": True}, indexed, release


def _profile_mac_sysutils_acquisition(audit, indexed, release):
    """Record the precise limit of the retained locator and platform evidence."""
    native_candidates = [row for row in indexed["inputs"]
        if Path(row["path"]).name.lower() == "libsysutilsnative.dylib"]
    metadata = json.loads(audit.artifact(audit.a.ROOT / release["metadata_snapshot"]["path"], release["metadata_snapshot"]))
    retained_metadata, locator_matches = [], []
    for row in release["metadata_files"]:
        raw = audit.read(row)
        retained_metadata.append({name: row[name] for name in ("path", "bytes", "sha256", "url", "kind")})
        if b"libsysutilsnative.dylib" in raw.lower():
            locator_matches.append(row["path"])
    if (native_candidates or locator_matches or metadata["release_profile"] != {
            "os": "WINDOWS", "osver": "11", "arch": "64", "hardware": "source-defined generic fallback", "locale": "en-US"}):
        raise ValueError("Mac SysUtils acquisition inputs changed and need native/source review")
    return {"status": "source_not_located_in_selected_current_evidence", "native_original_acquired": False,
        "selected_metadata_scope": metadata["release_profile"], "metadata_snapshot": release["metadata_snapshot"],
        "verified_metadata": retained_metadata, "indexed_native_candidates": native_candidates,
        "selected_metadata_native_locator_matches": locator_matches,
        "loader_source": "current Host main.js local CommonDylib path and optional local debug copy",
        "packaged_path": "HOME/Library/Razer/RazerAppEngine/razerappengine.app/Contents/CommonDylib/libSysUtilsNative.dylib",
        "development_path": "__dirname/../CommonDylib/libSysUtilsNative.dylib",
        "debug_copy_target": "userDataDir/Apps/Common/libSysUtilsNative.dylib",
        "download_url_from_selected_loader": None,
        "blocker": "No current official Mac package/download declaration or indexed libSysUtilsNative.dylib connects the retained JS loader to native bytes. The selected release metadata queried WINDOWS/11/64 and identifies a Windows EXE; that package cannot establish a Mac native version or implementation.",
        "required_input": "An official current Mac release/package locator or a statically acquired Mac installation archive containing the named CommonDylib member, with source/version, actual bytes, SHA-256 and dependency ancestry; then Mach-O architecture/exports and static capture review.",
        "network_requests_attempted": [], "guessed_urls_or_platform_parameters": False,
        "absence_of_mac_functionality_inferred": False, "windows_native_used_as_substitute": False}


