def collect_profile_mac_sysutils_native(audit):
    """Close current Mac JS dispatch while retaining its missing native source boundary."""
    sources, provenance, indexed, release = _profile_mac_sysutils_inputs(audit)
    acquisition = _profile_mac_sysutils_acquisition(audit, indexed, release)
    selected, owners, bindings = {}, {}, {}

    def keep(role, source, node):
        key = audit.retain_range("profile_mac_sysutils_" + role, source, node.start_byte, node.end_byte, node.type)
        selected[role], owners[role] = key, audit.owners[key]
        return node

    for role, filename, anchor, kinds in (
            ("platform_selector", "modules/sysutil/index.js", '"win32"===process.platform', {"program"}),
            ("host_loader", "main.js", 'let n="SysUtilsNative.dll"', {"arrow_function"}),
            ("host_common_directory", "main.js", 'o="win32"===process.platform?', {"variable_declarator"}),
            ("host_system_poweroff", "main.js", 'po.on("systempoweroff"', {"call_expression"}),
            ("host_shutdown", "main.js", "terminating sysUtils", {"function_declaration", "arrow_function"}),
            ("host_sync_dispatch", "main.js", 'case"GetRegisteredApplaunchedList":', {"switch_case"}),
            ("host_async_dispatch", "main.js", 'case"getApplicationIconsAlt":', {"switch_case"}),
            ("ffi_sync", "modules/ffi/ffiMain.js", "exports.callDLLMain=", {"assignment_expression"}),
            ("ffi_async", "modules/ffi/ffiMain.js", "exports.callDLLMainAsync=", {"assignment_expression"}),
            ("timeout", "lib/common.js", "module.exports.promiseWithTimeout=", {"assignment_expression"}),
            ("disposed", "mainSubFunction.js", "module.exports.isWebContentsDisposed=", {"assignment_expression"})):
        source = sources["electron/" + filename]
        keys = audit.retain("profile_mac_sysutils_" + role, source, anchor, kinds)
        if len(keys) != 1:
            raise ValueError("Mac SysUtils complete source owner is ambiguous: " + role)
        selected[role], owners[role] = keys[0], audit.owners[keys[0]]
    source = sources["electron/modules/sysutil/mac/index.js"]
    nodes = {}
    for name in ("constructor", "initDll", "callDLL", "callDLLAsync", "handleFFIEvent"):
        node, _ = audit.callable_member("profile_mac_sysutils_" + name, source, audit.tree(source).root_node, name)
        nodes[name] = keep("mac_" + name, source, node)
    for role, source, name, offset, expected in (
            ("host_instance", sources["electron/main.js"], "po", owners["host_loader"]["byte_start"], "po=new lo(Ye)"),
            ("host_factory", sources["electron/main.js"], "lo", owners["host_loader"]["byte_start"], '{FFISysUtils:lo}=require("./modules/sysutil")'),
            ("host_ffi", sources["electron/main.js"], "Ye", owners["host_loader"]["byte_start"], 'Ye=require("./modules/ffi/ffiMain")'),
            ("mac_channel", sources["electron/modules/sysutil/mac/index.js"], "s", nodes["callDLL"].start_byte, 's="sysUtilsNative"'),
            ("ffi_library_map", sources["electron/modules/ffi/ffiMain.js"], "o", owners["ffi_sync"]["byte_start"], "o=new Map"),
            ("ffi_callback_map", sources["electron/modules/ffi/ffiMain.js"], "t", owners["ffi_sync"]["byte_start"], "t=new Map"),
            ("ffi_module", sources["electron/modules/ffi/ffiMain.js"], "n", owners["ffi_sync"]["byte_start"], 'n=require("ffi-napi-rz")')):
        value = audit.binding("profile_mac_sysutils_" + role, source, name, offset)
        if value["body"] != expected or value["resolution"] not in ("declaration", "destructuring_requires_value_analysis"):
            raise ValueError("Mac SysUtils actual lexical producer changed: " + role)
        node = audit.tree(source).root_node.descendant_for_byte_range(value["start_byte"], value["end_byte"] - 1)
        keep(role, source, node)
        bindings[role] = value
    abi = [node for node in _help_nodes(nodes["initDll"]) if node.type == "pair"
        and node.child_by_field_name("key").text == b"apiObj"]
    if len(abi) != 1:
        raise ValueError("Mac SysUtils ConfigureFFI declaration is absent or ambiguous")
    table = abi[0].child_by_field_name("value")
    declarations = {}
    for node in table.named_children:
        if node.type != "pair":
            raise ValueError("Mac SysUtils ConfigureFFI declaration has unreviewed spread/computed members")
        name = node.child_by_field_name("key").text.decode()
        if name in declarations:
            raise ValueError("Mac SysUtils ConfigureFFI declaration is duplicated")
        declarations[name] = json.loads(node.child_by_field_name("value").text)
    keep("configure_ffi_table", sources["electron/modules/sysutil/mac/index.js"], abi[0])
    contract = _profile_mac_sysutils_source_contract(owners, declarations)
    return {"schema_version": 1, "kind": "current_profile_mac_sysutils_native", "query": "profile-mac-sysutils-native",
        "scope": "Current Host 4.0.896 retained Mac SysUtils JS declaration/loading, source acquisition boundary, URL subscriptions, event forwarding and stop/release requests",
        "host_release": provenance, "selected": selected, "bindings": bindings, "ffi_declarations": declarations,
        "acquisition": acquisition, "source_contract": contract, "selected_static_semantics_reviewed": True,
        "native": {"status": "not_acquired", "original": None, "capture": None, "complete_selected_functions": [],
            "mach_o_architecture": "unobserved", "export_abi": "unverified", "native_semantics_complete": False,
            "windows_native_used_as_substitute": False},
        "source_chain_complete": False, "whole_profiles_complete": False, "whole_product_complete": False,
        "target_execution": False, "real_device_operations": False, "actual_dll_comparison": "unverified",
        "rust_independent_implementation": "unverified", "ui_backend_wiring": "unverified", "runtime_acceptance": "unverified",
        "product_code_modified": False,
        "remaining_chains": [acquisition["blocker"], acquisition["required_input"],
            "Native Initialize/Terminate, two monitors, callback thread/handle ownership and every pending/error/cancellation/release branch cannot be inferred from JS declarations or a Windows DLL. Their actual Mac native source and static semantics remain unverified.",
            "Independent Rust implementation, UI/backend callers, actual corresponding official native/service/device results, restoration and runtime acceptance remain separate unfinished work."],
        "maintenance_lifecycle": {"temporary_artifacts_created": [], "analysis_sessions_created": [], "network_requests_attempted": [],
            "new_native_capture_created": False}}


def collect_profiles_static(audit):
    """Capture current mounted Games branches and their actual host consumers."""
    report = {"schema_version": 1, "query": "profiles", "recorded_at_utc": audit.a.stamp(),
        "parser": audit.parser_versions, "source_sets": [], "host_sources": [],
        "selected": {}, "cross_chunk_exports": {}, "bindings": {}, "failures": [],
        "source_chain_complete": False, "selected_static_semantics_reviewed": True,
        "product_code_modified": False, "target_execution": False, "real_device_operations": False,
        "actual_dll_comparison": "unverified", "rust_independent_implementation": "unverified",
        "ui_backend_wiring": "unverified", "runtime_acceptance": "unverified",
        "boundaries": profiles_static_boundaries(),
        "remaining_chains": ["SysUtilsNative installed-app enumeration and icon extraction native bodies",
            "All game scanner strategies and every product automatic-profile writer",
            "Independent Rust implementation, mounted UI wiring and automated feature tests",
            "Actual corresponding DLL/service/device comparison and window acceptance"]}
    for name in ("tools/host.py", "tools/workspace.py", "tools/evidence.py", "tools/families.py"):
        audit.artifact(audit.a.ROOT / name)
    deployments = {}
    for name in ("synapse-profiles-current", "gms-proxy-current"):
        source_set, files = audit.source_set(name)
        capture = audit.frontend_capture(name, files)
        manifest = json.loads(audit.artifact(audit.a.ROOT / source_set["capture"]["path"]))
        source_set["complete_capture"] = capture
        source_set["capture_acquisition_relation"] = {
            "capture_recorded_acquisition_sha256": manifest.get("module_recovery", {}).get("original_acquisition_sha256"),
            "current_acquisition_sha256": source_set["acquisition"]["sha256"],
            "current_deployment_original_bytes_reverified": True,
            "capture_metadata_rewritten": False}
        report["source_sets"].append(source_set)
        deployments[name] = files

    def source(files, filename):
        matches = [row for row in files if Path(row["path"]).name == filename]
        if len(matches) != 1:
            raise ValueError("Profiles current source is absent or ambiguous: " + filename)
        return matches[0]

    ui, proxy = deployments["synapse-profiles-current"], deployments["gms-proxy-current"]
    main, page, common = (source(ui, name) for name in (
        "main.776df2b1.js", "9449.8f17b519.chunk.js", "9473.f9ed3133.chunk.js"))
    gms = source(proxy, "main.fd0c50a8.js")
    selected = report["selected"]
    for role, original, needle, kinds in (
        ("api_adapter", main, 'this.getInstalledApplicationList=', {"class_declaration", "class"}),
        ("add_app", common, 'this.handleGetInstalledApp=', {"class_declaration", "class"}),
        ("detail", page, 'this.relocateGame=async', {"class_declaration", "class"}),
        ("games", page, 'this.onRefresh=', {"class_declaration", "class"}),
        ("gms_bridge", main, 'this.gmsEventsListener=', {"class_declaration", "class"}),
        ("list_commit", main, 'pt=(t,e)=>', {"variable_declarator"}),
        ("relocate_reducer", main, 'case u.BuN:', {"switch_case"}),
        ("proxy_api", gms, 'this.handleAPIRequest=async', {"assignment_expression"}),
        ("proxy_start_scan", gms, 'this.startScan=async', {"assignment_expression"}),
        ("proxy_finished", gms, 'this._onGameScanFinishedEvent=async', {"assignment_expression"}),
    ):
        selected[role] = audit.retain("profiles_" + role, original, needle, kinds)[0]
    for role, parent, name in (
        ("get_installed_apps", "add_app", "getInstalledApps"),
        ("browse_game", "add_app", "browseGame"), ("add_app_call", "add_app", "addApp"),
        ("unmount_add_app", "add_app", "componentWillUnmount"),
        ("games_add_drop", "games", "addNewApp"), ("games_refresh", "games", "onRefresh"),
        ("relocate_selection", "detail", "relocateGame"),
        ("replace_game", "gms_bridge", "_replacingGame"),
        ("bridge_events", "gms_bridge", "handleMemoryStorageEvent"),
        ("file_dialog_adapter", "api_adapter", "showFileOpenDialog"),
        ("get_installed_adapter", "api_adapter", "getInstalledApplicationList"),
        ("icons_adapter", "api_adapter", "getApplicationIcons"),
    ):
        owner = audit.owners[selected[parent]]
        original = owner["original"]
        node = audit.tree(original).root_node.descendant_for_byte_range(owner["byte_start"], owner["byte_end"] - 1)
        kwargs = {} if name in {"componentWillUnmount", "showFileOpenDialog"} else {"receiver": "this"}
        _, selected[role] = audit.callable_member("profiles_" + role, original, node, name, **kwargs)
    for role, module, exported in (("add_action", 399, "addGame"),
            ("relocate_action", 399, "updateRelocateGamePath"),
            ("scan_action", 8301, "initiateGameScan"), ("drag_drop", 9902, "A")):
        item = audit.webpack_export("profiles_" + role, ui, module, exported)
        report["cross_chunk_exports"][role] = item
        selected[role] = item["binding"]["owner_id"]
    for role, original, name, parent in (
        ("add_app_api_import", common, "I", "add_app"),
        ("add_app_actions_import", common, "r", "add_app"),
        ("detail_api_import", page, "L", "detail"),
        ("games_drag_import", page, "H", "games"),
        ("bridge_api_import", main, "N", "gms_bridge")):
        reference = audit.owners[selected[parent]]["byte_start"]
        report["bindings"][role] = {"original": audit.sources[original["path"]],
            "reference_byte": reference, **audit.binding("profiles_" + role, original, name, reference)}

    host = verified_host_owners(audit, ("electron/main.js", "electron/modules/sysutil/index.js",
        "electron/modules/sysutil/win/index.js", "electron/modules/sysutil/mac/index.js",
        "electron/modules/ffi/ffiMain.js"))
    for suffix, item in host.items():
        report["host_sources"].append({key: value for key, value in item.items() if key != "body"})
        original = item["original"]
        if suffix == "electron/main.js":
            for role, anchor in (("host_dialog_dispatch", 'case"showFileOpenDialog":'),
                                 ("host_async_dispatch", 'case"getApplicationIconsAlt":')):
                selected[role] = audit.retain("profiles_" + role, original, anchor, {"switch_case"})[0]
        elif suffix.endswith("/ffiMain.js"):
            selected["host_async_ffi"] = audit.retain("profiles_host_async_ffi", original,
                "exports.callDLLMainAsync=", {"assignment_expression"})[0]
        else:
            selected["host_" + suffix] = audit.retain_range("profiles_host_" + suffix, original,
                0, len(audit.read(original)), audit.tree(original).root_node.type)
    report["complete_originals"] = list(audit.sources.values())
    report["complete_source_owners"] = list(audit.owners.values())
    report["verified_artifacts"] = list(audit.artifacts.values())
    report["changed_during_query"] = audit.final_snapshot()
    report["snapshot_stable"] = not report["changed_during_query"]
    report["failures"].extend("Profiles artifact changed during query: " + name
                              for name in report["changed_during_query"])
    return report


def verify_profiles_static_receipt(report, audit=None):
    """Independent read-only receipt check; never invokes the collector."""
    audit = audit or HostLocalAudit()
    if not isinstance(report, dict):
        raise ValueError("Profiles source receipt is absent")
    owners = {}
    for owner in report["complete_source_owners"]:
        verify_profiles_owner(audit, owner)
        if owner["id"] in owners:
            raise ValueError("Profiles source owner is repeated")
        owners[owner["id"]] = owner
    selected = report["selected"]
    bodies = {role: owners[key]["body"] for role, key in selected.items()}
    verify_profiles_static_claims(report, bodies)
    expected_selected = {"api_adapter", "add_app", "detail", "games", "gms_bridge", "list_commit",
        "relocate_reducer", "proxy_api", "proxy_start_scan", "proxy_finished", "get_installed_apps",
        "browse_game", "add_app_call", "unmount_add_app", "games_add_drop", "games_refresh",
        "relocate_selection", "replace_game", "bridge_events", "file_dialog_adapter", "get_installed_adapter",
        "icons_adapter", "add_action", "relocate_action", "scan_action", "drag_drop",
        "host_dialog_dispatch", "host_async_dispatch", "host_async_ffi", "host_electron/modules/sysutil/index.js",
        "host_electron/modules/sysutil/win/index.js", "host_electron/modules/sysutil/mac/index.js"}
    if set(selected) != expected_selected:
        raise ValueError("Profiles selected source owner set differs")
    reviewed = {role: {field: owners[key][field] for field in (
        "original", "syntax", "byte_start", "byte_end", "body_sha256")}
        for role, key in selected.items()}
    # This binds the manual static review to its complete source owners. It is
    # an analysis receipt constraint, never a product/runtime compatibility gate.
    reviewed_sha = hashlib.sha256(json.dumps(reviewed, ensure_ascii=False,
        sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if reviewed_sha != "f4f74a263aec084f7a80a73b3dd1ac546872ab695b63a50543cc5ebccb7c0e91":
        raise ValueError("Profiles selected bytes require a new complete semantic review")
    for role, parent in {"get_installed_apps": "add_app", "browse_game": "add_app",
            "add_app_call": "add_app", "unmount_add_app": "add_app", "games_add_drop": "games",
            "games_refresh": "games", "relocate_selection": "detail", "replace_game": "gms_bridge",
            "bridge_events": "gms_bridge", "file_dialog_adapter": "api_adapter",
            "get_installed_adapter": "api_adapter", "icons_adapter": "api_adapter"}.items():
        child, root = owners[selected[role]], owners[selected[parent]]
        if (child["original"] != root["original"] or not root["byte_start"] <= child["byte_start"]
                < child["byte_end"] <= root["byte_end"]):
            raise ValueError("Profiles callable does not belong to its recorded complete owner")
    expected_sources = {}
    if [row["name"] for row in report["source_sets"]] != ["synapse-profiles-current", "gms-proxy-current"]:
        raise ValueError("Profiles current deployment source sets differ")
    for stored in report["source_sets"]:
        current, files = audit.source_set(stored["name"])
        for field in ("acquisition", "deployment", "capture", "capture_failures", "unresolved_acquisition", "failed_acquisition"):
            if stored[field] != current[field]:
                raise ValueError("Profiles current deployment receipt differs: " + field)
        if stored["complete_capture"] != audit.frontend_capture(stored["name"], files):
            raise ValueError("Profiles reusable full capture identity or failures differ")
        capture = json.loads(audit.artifact(audit.a.ROOT / current["capture"]["path"]))
        relation = stored["capture_acquisition_relation"]
        if relation != {"capture_recorded_acquisition_sha256": capture.get("module_recovery", {}).get("original_acquisition_sha256"),
                "current_acquisition_sha256": current["acquisition"]["sha256"],
                "current_deployment_original_bytes_reverified": True, "capture_metadata_rewritten": False}:
            raise ValueError("Profiles acquisition change was hidden or transferred to the old capture")
        expected_sources.update({row["path"]: row for row in files})
    host = verified_host_owners(audit, ("electron/main.js", "electron/modules/sysutil/index.js",
        "electron/modules/sysutil/win/index.js", "electron/modules/sysutil/mac/index.js",
        "electron/modules/ffi/ffiMain.js"))
    if report["host_sources"] != [{k: v for k, v in item.items() if k != "body"} for item in host.values()]:
        raise ValueError("Profiles host original or official package provenance differs")
    expected_sources.update({row["original"]["path"]: row["original"] for row in host.values()})
    for owner in owners.values():
        source = expected_sources.get(owner["original"]["path"])
        if source is None or any(source[k] != owner["original"][k] for k in ("bytes", "sha256")):
            raise ValueError("Profiles owner is outside its current deployment or official host")
    expected_exports = {"add_action": (399, "addGame"), "relocate_action": (399, "updateRelocateGamePath"),
        "scan_action": (8301, "initiateGameScan"), "drag_drop": (9902, "A")}
    if set(report["cross_chunk_exports"]) != set(expected_exports):
        raise ValueError("Profiles cross-chunk export set differs")
    for role, item in report["cross_chunk_exports"].items():
        original, binding = item["original"], item["binding"]
        factory, exported, target = (owners[item["complete_factory_owner"]],
            owners[item["export_definition_owner"]], owners[binding["owner_id"]])
        if (selected[role] != target["id"] or original != target["original"]
                or factory["original"] != original or exported["original"] != original
                or not factory["byte_start"] <= exported["byte_start"] < exported["byte_end"] <= factory["byte_end"]
                or not factory["byte_start"] <= target["byte_start"] < target["byte_end"] <= factory["byte_end"]):
            raise ValueError("Profiles cross-chunk export owner graph differs")
        resolved = audit.binding("profiles_verify_export_" + role, original, binding["name"], binding["reference_byte"])
        if resolved != binding:
            raise ValueError("Profiles cross-chunk export no longer has its recorded lexical binding")
        factory_node = verify_profiles_owner(audit, factory)
        module_key = factory_node.child_by_field_name("key")
        if ((item["module_id"], item["export"]) != expected_exports[role]
                or module_key is None or module_key.text.decode() != str(item["module_id"])
                or (item["export"] + ":()=>" + binding["name"]) not in exported["body"]):
            raise ValueError("Profiles source module or actual export getter differs")
    expected_imports = {"add_app_api_import": "I=a(7226)", "add_app_actions_import": "r=a(399)",
        "detail_api_import": "L=s(7226)", "games_drag_import": "H=s(9902)",
        "bridge_api_import": "N=n(7226)"}
    if set(report["bindings"]) != set(expected_imports):
        raise ValueError("Profiles producer import set differs")
    for role, binding in report["bindings"].items():
        original = binding["original"]
        expected = {"original": original, "reference_byte": binding["reference_byte"],
            **audit.binding("profiles_verify_" + role, original, binding["name"], binding["reference_byte"])}
        if binding != expected or binding["body"] != expected_imports[role]:
            raise ValueError("Profiles producer import binding differs")
    for artifact in report["verified_artifacts"]:
        audit.artifact(audit.a.ROOT / artifact["path"], artifact)
    recorded = {row["path"]: row for row in report["complete_originals"]}
    if len(recorded) != len(report["complete_originals"]) or recorded != audit.sources:
        raise ValueError("Profiles complete original inventory differs from verified current sources")
    if audit.final_snapshot():
        raise ValueError("Profiles input changed during independent verification")
    return {"complete_source_owners": len(owners), "selected_owners": len(selected),
        "source_sets": 2, "target_execution": False, "runtime_acceptance": "unverified"}


def publish_host_static_query(report, destination, a, query, *, replace_existing=True):
    """Update only this query while recording canonical identities of older fields."""
    def identity(value):
        return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
            separators=(",", ":")).encode("utf-8")).hexdigest()
    with a.index_lock(destination.with_suffix(".lock")):
        previous = json.loads(destination.read_bytes()) if destination.is_file() else {"schema_version": 1}
        if not replace_existing and query in previous:
            current = previous[query]
            if (isinstance(current, dict)
                    and {key: value for key, value in current.items()
                         if key != "preserved_top_level_canonical_sha256"}
                    == {key: value for key, value in report.items()
                        if key != "preserved_top_level_canonical_sha256"}):
                return current["preserved_top_level_canonical_sha256"]
            raise ValueError("Static capability already has a different retained proof")
        preserved = {key: identity(value) for key, value in previous.items() if key != query}
        failed = previous.get(query)
        reference = failed.get("previous_failed_query") if isinstance(failed, dict) else None
        seen = set()
        while reference is not None:
            import reverse_pending
            if (not reverse_pending.valid(reference) or reference["sha256"] in seen
                    or reference["path"] != ".analysis/results/reverse-pending/review-sources/"
                    + reference["sha256"] + ".json"):
                raise ValueError("Host query lost its retained previous failure")
            seen.add(reference["sha256"])
            snapshot = json.loads(a.resolve(reference["path"], ".analysis/results").read_bytes())
            original = snapshot.get("report", {})
            if (snapshot.get("kind") != "failed_host_static_query" or snapshot.get("query") != query
                    or snapshot.get("target_execution") is not False or not isinstance(original, dict)
                    or not isinstance(original.get("failures"), list) or not original["failures"]):
                raise ValueError("Host query previous failure belongs to another query or scope")
            reference = original.get("previous_failed_query")
        if isinstance(failed, dict) and isinstance(failed.get("failures"), list) and failed["failures"]:
            import reverse_pending
            retained = reverse_pending.retain_review_json({
                "schema_version": 1, "kind": "failed_host_static_query",
                "query": query, "report": failed,
                "target_execution": False,
                "scope": "Complete previous failed query; no successful source or runtime result is implied"})
            report["previous_failed_query"] = retained
        elif isinstance(failed, dict) and "previous_failed_query" in failed:
            report["previous_failed_query"] = failed["previous_failed_query"]
        report["preserved_top_level_canonical_sha256"] = preserved
        previous[query] = report
        a.save(destination, previous)
        del previous
        persisted = json.loads(destination.read_bytes())
        if ({key: identity(value) for key, value in persisted.items() if key != query} != preserved
                or persisted[query] != report):
            raise ValueError("Host query publication changed an unrelated top-level field")
    return preserved


def publish_profiles_static(report, destination, a):
    return publish_host_static_query(report, destination, a, "profiles")


def audit_host_profiles(args):
    audit = HostLocalAudit()
    destination = audit.a.ROOT / ".analysis/results/host-current/local-audit.json"
    if getattr(args, "verify_only", False):
        report = json.loads(destination.read_bytes())["profiles"]
    else:
        report = collect_profiles_static(audit)
    verification = verify_profiles_static_receipt(report)
    if not getattr(args, "verify_only", False):
        publish_profiles_static(report, destination, audit.a)
    print(json.dumps({"receipt": audit.a.rel(destination), "query": "profiles",
        "verify_only": bool(getattr(args, "verify_only", False)), **verification}), flush=True)


def lighting_catalog_projection(rows):
    """Project the ordered strict-equality helper over the catalog's full ID domain."""
    if not isinstance(rows, list) or not rows:
        raise ValueError("Device catalog is not a nonempty row array")
    shapes = {"productId": {int}, "dongleId": {int, list}, "bleId": {int},
              "wiredId": {list}, "psModeIds": {list}, "monitorPortIds": {list}, "xBoxId": {int, list}}
    declared, scalar = set(), set()
    for row in rows:
        if not isinstance(row, dict) or "productId" not in row:
            raise ValueError("Device catalog row has no product identity")
        for key, value in row.items():
            if key == "isNotChromaDevice" and type(value) is bool:
                continue
            if key not in shapes or type(value) not in shapes[key]:
                raise ValueError("Device catalog has an unverified field shape: " + key)
            values = value if type(value) is list else [value]
            if not values or any(type(item) is not int or not 0 < item <= 65535 for item in values):
                raise ValueError("Device catalog has an invalid numeric identity: " + key)
            declared.update(values)
            if key in {"productId", "dongleId", "bleId"} and type(value) is int:
                scalar.add(value)
    resolutions = []
    for pid in sorted(declared):
        match = {"input_pid": pid, "primary": pid, "index": None, "matched": "unchanged"}
        for index, row in enumerate(rows):
            field = next((key for key in ("productId", "dongleId", "bleId")
                          if type(row.get(key)) is int and row[key] == pid), None)
            if field is not None:
                match.update(primary=row["productId"], index=index, matched=field)
                break
        resolutions.append(match)
    return {"rows": len(rows), "distinct_primary_pids": len({row["productId"] for row in rows}),
            "all_declared_numeric_id_count": len(declared), "engine_scalar_input_count": len(scalar),
            "engine_changed_input_count": sum(row["input_pid"] in scalar and row["input_pid"] != row["primary"]
                                               for row in resolutions),
            "ordered_resolutions": resolutions}


def audit_lighting_catalog(audit, engine_main, current_consumers):
    observation, files = audit.observed_sources("synapse-device-catalog-current",
        "https://apps.razer.com/synapse/dashboard/AvailableDevices.json")
    owner_path = audit.a.ROOT / ".analysis/results/frontend/synapse-device-catalog-current/source-owners.json"
    owners, owner_ids = json.loads(audit.artifact(owner_path)), []
    for owner in owners["owners"]:
        matches = [row for row in files if row["path"] == owner["source"]]
        if len(matches) != 1:
            raise ValueError("Catalog source owner is outside the bounded observations")
        original = matches[0]
        start, end = owner["start"], owner["end"]
        node = audit.tree(original).root_node.descendant_for_byte_range(start, end - 1)
        raw = audit.read(original)[start:end]
        if (node.start_byte, node.end_byte, node.type) != (start, end, owner["type"]) \
                or hashlib.sha256(raw).hexdigest() != owner["body_sha256"] \
                or raw.decode("utf-8") != owner["body"]:
            raise ValueError("Catalog owner does not match its complete source AST")
        owner_ids.append(audit.retain_range("lighting_catalog_" + str(len(owner_ids)),
            original, start, end, node.type))
    original = next(row for row in files if row["url"] ==
        "https://apps.razer.com/synapse/dashboard/AvailableDevices.json")
    projection = lighting_catalog_projection(json.loads(audit.read(original)))
    analysis = json.loads(audit.artifact(audit.a.ROOT /
        ".analysis/results/frontend/synapse-device-catalog-current/catalog-analysis.json"))
    if analysis["input"] != original["path"] or analysis["input_bytes"] != original["bytes"] \
            or analysis["input_sha256"] != original["sha256"]:
        raise ValueError("Catalog projection belongs to different original bytes")
    for key, value in projection.items():
        if key == "ordered_resolutions":
            recorded = [{name: row[name] for name in ("input_pid", "primary", "index", "matched")}
                        for row in analysis["engine_all_declared_id_resolutions"]]
        else:
            recorded = analysis[key]
        if value != recorded:
            raise ValueError("Catalog projection differs from retained analysis: " + key)
    return {"observation": observation, "historical_owner_ids": owner_ids,
            "historical_scope": "The bounded catalog observation retains its original deployment; current consumers are independently located in the selected deployment",
            "current_engine_main": audit.sources[engine_main["path"]],
            "current_consumer_owner_ids": current_consumers, "catalog": audit.sources[original["path"]],
            **projection, "ordered_equality": "First row with strict scalar productId/dongleId/bleId equality; arrays and other ID fields do not match; no match preserves the input PID",
            "consumer": "DeviceInfo.configure uses vendor5426/1678 and feeds both manifests and middleware lighting SVG paths",
            "cache": "Getter may receive Service Worker DeviceDataJson stale cache and falls back to CacheAPI DeviceDataJson on failure/empty. This observation does not read a live browser cache",
            "runtime_browser_cache_observed": False, "target_execution": False,
            "actual_dll_comparison": "unverified"}


def audit_iot_reconnect(audit):
    import evidence
    observation, _ = audit.observed_sources("synapse-iot-reconnect-current",
        "https://apps.razer.com/synapse/products/780/mw/index.html")
    path = audit.a.ROOT / ".analysis/results/frontend/synapse-iot-reconnect-current/source-owners.json"
    retained = json.loads(audit.artifact(path))
    indexed = {row["path"]: row for row in json.loads(
        audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))["inputs"]}
    sources, deployments, owner_ids = {}, {}, []
    for source in retained["sources"]:
        row = indexed.get(source["path"])
        if row is None or any(row[key] != source[key] for key in ("bytes", "sha256")):
            raise ValueError("IoT reconnect source differs from its indexed original")
        audit.read(row)
        sources[row["path"]] = row
        if row["path"].startswith(".analysis/inputs/frontend/"):
            receipt = source["acquisition"]
            if receipt not in deployments:
                acquired = json.loads(audit.artifact(audit.a.ROOT / receipt))
                if acquired.get("source_current_during_acquisition") is not True:
                    raise ValueError("IoT reconnect deployment has an unverified entry")
                deployments[receipt] = evidence.frontend_deployment_sources(acquired)
            if not any(item["identity_verified"] and item["original"]["path"] == row["path"]
                       for item in deployments[receipt]["sources"]):
                raise ValueError("IoT reconnect owner is not referenced by the current entry")
    host = verified_host_owners(audit, ("electron/modules/ffi/FFIPreloadMain.js", "electron/preload.js"))
    for owner in retained["owners"]:
        original = sources[owner["source"]]
        start, end = owner["start_byte"], owner["end_byte"]
        node = audit.tree(original).root_node.descendant_for_byte_range(start, end - 1)
        body = audit.read(original)[start:end]
        if (node.start_byte, node.end_byte, node.type) != (start, end, owner["type"]) \
                or body.decode("utf-8") != owner["body"] \
                or hashlib.sha256(body).hexdigest() != owner["body_sha256"]:
            raise ValueError("IoT reconnect source owner differs from its complete AST")
        owner_ids.append(audit.retain_range("iot_reconnect_" + owner["label"], original, start, end, node.type))
    native = []
    for owner in retained["native_owners"]:
        raw = audit.artifact(audit.a.ROOT / owner["source"], {"sha256": owner["capture_sha256"]})
        function = json.loads(raw)
        if function["rva"] != owner["rva"]:
            raise ValueError("IoT reconnect native owner has a different RVA")
        native.append({"artifact": audit.artifacts[owner["source"]], "rva": owner["rva"]})
    return {"observation": observation, "owner_ids": owner_ids, "host_sources": list(host.values()),
            "native_owners": native, "products": retained["products"],
            "static_projections": retained["static_projections"], "findings": retained["findings"],
            "unverified": retained["unverified"], "target_execution": False,
            "actual_dll_comparison": "unverified"}


def verify_reviewed_frontend_acquisition(audit, reference, indexed):
    """Bind a review to current bytes or its proven immutable acquisition scope."""
    name = reference.get("path", "")
    if (not re.fullmatch(r"\.analysis/inputs/frontend/[a-z0-9-]+/acquisition\.json", name)
            or type(reference.get("bytes")) is not int or reference["bytes"] < 0
            or not re.fullmatch(r"[a-f0-9]{64}", str(reference.get("sha256")))):
        raise ValueError("Reviewed frontend acquisition has no exact maintained identity")
    current_index = indexed.get(name)
    if not isinstance(current_index, dict) or any(key not in current_index for key in ("bytes", "sha256")):
        raise ValueError("Reviewed frontend acquisition is absent from the current input index")
    raw = audit.artifact(audit.a.ROOT / name, current_index)
    current = audit.artifacts[name]
    if all(reference[key] == current[key] for key in ("bytes", "sha256")):
        return {"reviewed_acquisition": reference, "current_acquisition": current, "relation": "unchanged"}
    acquired = json.loads(raw)
    if acquired.get("target_execution") is not False or acquired.get("source_current_during_acquisition") is not True:
        raise ValueError("Reviewed frontend acquisition has no verified current static source")
    _, _, extensions = audit.bounded_observation_history(acquired, current)
    predecessors = [extension["previous_acquisition"] for extension in extensions
                    if all(extension["previous_acquisition"][key] == reference[key] for key in ("bytes", "sha256"))]
    if len(predecessors) != 1:
        raise ValueError("Reviewed acquisition is not a verified immutable predecessor of its current owner")
    return {"reviewed_acquisition": reference, "current_acquisition": current,
            "relation": "verified_immutable_predecessor", "retained_acquisition": predecessors[0],
            "dependency_extensions": extensions, "historical_scope_preserved": True}


def audit_deviceinfo_value_sources(audit, main, manifests, current_protocol):
    """Recheck reviewed value sources against complete ASTs and retained manifests."""
    path = audit.a.ROOT / ".analysis/results/frontend/synapse-lighting-engine-current/deviceinfo-value-sources.json"
    retained = json.loads(audit.artifact(path))
    if retained["target_execution"] is not False or retained["real_device_operations"] is not False:
        raise ValueError("DeviceInfo value review has an invalid execution boundary")
    indexed = {row["path"]: row for row in json.loads(
        audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))["inputs"]}
    sources = {}
    for row in retained["sources"]:
        original = indexed[row["path"]]
        if any(row[key] != original[key] for key in ("bytes", "sha256")):
            raise ValueError("DeviceInfo value source differs from current indexed bytes")
        sources[row["path"]] = original
    acquisition_relations = [verify_reviewed_frontend_acquisition(audit, row, indexed)
                             for row in retained["acquisitions"]]
    owners = {}
    for row in retained["owners"]:
        original = sources[row["source"]]
        start, end = row["start_byte"], row["end_byte"]
        body = audit.read(original)[start:end]
        node = audit.tree(original).root_node.descendant_for_byte_range(start, end - 1)
        if row["source_sha256"] != original["sha256"] or (node.start_byte, node.end_byte, node.type) != (
                start, end, row["type"]) or body.decode("utf-8") != row["body"] \
                or hashlib.sha256(body).hexdigest() != row["body_sha256"]:
            raise ValueError("DeviceInfo value owner differs from its complete original AST")
        if row["id"] in owners:
            raise ValueError("DeviceInfo value owner has a duplicate identity")
        owners[row["id"]] = audit.retain_range(
            "lighting_deviceinfo_value_source", original, start, end, node.type)
    expected_manifests = {row["original"]["path"]: row for row in manifests}
    if {row["source"] for row in retained["manifest_branches"]} != set(expected_manifests):
        raise ValueError("DeviceInfo value review does not cover the retained manifest set")
    for row in retained["manifest_branches"]:
        expected = expected_manifests[row["source"]]
        original = expected["original"]
        body = json.loads(audit.read(original))
        if any(row[key] != original[key] for key in ("bytes", "sha256")) \
                or (row["filename_product_id"], row["edition_id"]) != (
                    expected["product_id"], expected["edition_id"]) \
                or {key: body[key] for key in row["fields"] if key in body} != row["fields"]:
            raise ValueError("DeviceInfo manifest value projection differs from original fields")
    gate_owner = [row for row in audit.owners.values()
                  if "lighting_default_restore_device_names" in row["roles"]]
    if len(gate_owner) != 1:
        raise ValueError("DeviceInfo restore name gate is absent or ambiguous")
    row = gate_owner[0]
    node = audit.tree(main).root_node.descendant_for_byte_range(row["byte_start"], row["byte_end"] - 1)
    value = node.child_by_field_name("right")
    if value is None or value.type != "array" or any(part.type != "string" for part in value.named_children):
        raise ValueError("DeviceInfo restore name gate requires dynamic expression analysis")
    gate = {json.loads(part.text.decode("utf-8")) for part in value.named_children}
    gated = [row for row in retained["manifest_branches"]
             if row["fields"].get("rzDeviceConfig", {}).get("rzDeviceName") in gate]
    counts = {}
    for row in gated:
        name = row["fields"]["rzDeviceConfig"]["rzDeviceName"]
        counts[name] = counts.get(name, 0) + 1
    projection = retained["manifest_projection"]
    if counts != projection["gated_by_protocol"] or len(gated) != projection["gated_originals"] \
            or len(manifests) != projection["retained_originals"]:
        raise ValueError("DeviceInfo per-protocol manifest projection differs")
    for row in retained["retained_engine_keyword_scope"]:
        original = indexed[row["source"]]
        if any(row[key] != original[key] for key in ("bytes", "sha256")):
            raise ValueError("DeviceInfo keyword scan original differs")
        raw = audit.read(original)
        counts = {key: raw.count(key.encode("utf-8")) for key in (
            "quickEffectOnExit", "userQuickEffectOnExit", "getQuickEffect") if key.encode("utf-8") in raw}
        if counts != row["occurrences"]:
            raise ValueError("DeviceInfo keyword scan does not match retained source bytes")
    return {"analysis": audit.artifacts[audit.a.rel(path)], "historical_owner_ids": owners,
            "historical_scope": "Retained value-source findings and complete classes belong to their original acquisitions; the selected deployment has independent AST owners",
            "current_engine_main": audit.sources[main["path"]],
            "current_owner_ids": current_protocol["device_info"],
            "current_classes": current_protocol["classes"],
            "acquisition_relations": acquisition_relations,
            "historical_classes": retained["classes"], "manifest_projection": projection,
            "findings": retained["findings"], "remaining": retained["unresolved"],
            "target_execution": False, "actual_dll_comparison": "unverified"}


def lighting_frontend_protocol_owners(audit, originals):
    """Locate protocol and restore owners in the selected complete source ASTs."""
    def walk(node):
        yield node
        for child in node.named_children:
            yield from walk(child)

    def one(role, source, root, syntax, predicate):
        matches = [node for node in walk(root) if node.type in syntax and predicate(node)]
        if len(matches) != 1:
            raise ValueError("Current lighting owner is absent or ambiguous: " + role)
        node = matches[0]
        return node, audit.retain_range(role, source, node.start_byte, node.end_byte, node.type)

    def factory(mid):
        matches = audit.webpack_factories(originals, mid)
        if len(matches) != 1:
            raise ValueError("Current lighting factory is absent or ambiguous: " + str(mid))
        return matches[0]

    def member(node, field, name):
        value = node.child_by_field_name(field)
        return value is not None and value.type == "member_expression" \
            and value.child_by_field_name("property").text == name.encode()

    classes, constructors = [], []
    default_classes = {4001: "rzDevice25", 3061: "rzDevice25LedMatrix", 7826: "rzDevice25Oled",
        4026: "rzDevice25Linker", 8648: "rzDevice25Glitter", 1452: "rzDevice25GlitterWireless",
        8508: "rzDevice25DualLinkMouse", 986: "rzDevice25DualLinkKeyboard",
        7752: "rzDevice25LedMatrixBatchSender", 269: "rzDevice25LedMatrixSkipSetEffect"}
    constructor_classes = {9396: "rzDevice", 4001: "rzDevice25", 334: "rzDevice25Chroma65",
        3061: "rzDevice25LedMatrix", 269: "rzDevice25LedMatrixSkipSetEffect", 8648: "rzDevice25Glitter",
        1452: "rzDevice25GlitterWireless", 330: "rzDevice25MarciT1", 2237: "rzDevice25AudioCamy",
        1794: "rzDeviceIoT", 7752: "rzDevice25LedMatrixBatchSender", 6825: "rzDeviceLampArray"}
    located = {}
    for mid, name in {**default_classes, **constructor_classes}.items():
        matches = audit.webpack_factories(originals, mid)
        if not matches:
            raise ValueError("Current lighting protocol factory is absent: " + name)
        for source, module, owner in matches:
            node, class_owner = audit.named_class("lighting_protocol_class_" + name, source, owner, name)
            located.setdefault(name, []).append((source, node))
            if mid in default_classes:
                heritage = [child for child in node.named_children if child.type == "class_heritage"]
                if len(heritage) != 1 or len(heritage[0].named_children) != 1:
                    raise ValueError("Current lighting protocol base requires explicit analysis: " + name)
                base = heritage[0].named_children[0]
                receiver = base.child_by_field_name("object") if base.type == "member_expression" else base
                if receiver.type != "identifier":
                    raise ValueError("Current lighting protocol base has no lexical binding: " + name)
                classes.append({"name": name, "module_id": mid, "owner_id": class_owner,
                    "base_expression": base.text.decode(), "base_binding": audit.binding(
                        "lighting_default_restore_base_" + name, source, receiver.text.decode(), receiver.start_byte)})
            if mid in constructor_classes:
                _, constructor = audit.callable_member("lighting_protocol_constructor_" + name, source,
                    node.child_by_field_name("body"), "constructor")
                constructors.append({"protocol": "base" if mid == 9396 else name,
                                     "module_id": mid, "owner_id": constructor})
    base_source, base = located["rzDevice25"][0]
    for role, name in (("checksum", "_calculateChecksum"), ("transaction", "_getTransactionId"),
                       ("frame", "_createDataSend")):
        audit.callable_member("lighting_default_restore_" + role, base_source, base, name)

    source, module, info_factory = factory(8199)
    info, info_owner = audit.named_class("lighting_restore_device_info_complete_class", source,
                                         info_factory, "DeviceInfo")
    roles = {"complete_module": audit.retain_range("lighting_restore_device_info_complete_module",
        source, module.start_byte, module.end_byte, module.type), "complete_class": info_owner}
    info_nodes = {}
    for role, name in (("constructor", "constructor"), ("configure", "configure"),
            ("manifest_selection", "getManifestData"), ("partner_manifest", "getPartnerManifestData"),
            ("manifest_fetch", "fetchManifestFromURL"), ("manifest_idb_read", "getManifestDataFromIndexedDB"),
            ("manifest_idb_write", "writeManifestToIndexedDB"), ("local_profile_read", "getInfoFromLocalStorage"),
            ("ui_effect", "setUIEffect")):
        info_nodes[role], roles[role] = audit.callable_member("lighting_restore_device_info_" + role,
                                                            source, info, name)
    broker_source, _, broker = factory(5954)
    for role, name in (("prepare_device", "prepareDevice"), ("create_device_info", "createNewDeviceInfo"),
            ("available_devices", "getAvailableDevices"), ("software_effect_sync", "syncHWEffect"),
            ("region_effect_init", "initRegionQuickEffect"), ("device_ready", "onDeviceInfoReady"),
            ("unused_info_message", "onLightingEngineDeviceInfo")):
        info_nodes[role], roles[role] = audit.callable_member("lighting_restore_device_info_" + role,
            broker_source, broker, name, receiver=None if role == "unused_info_message" else "this")
    _, roles["exit_target_assignment"] = one("lighting_restore_device_info_exit_target_assignment", source,
        info_nodes["configure"], {"assignment_expression"},
        lambda node: member(node, "left", "quickEffectOnExit") and member(node, "right", "quickEffectOnExit"))
    _, roles["initial_snapshot"] = one("lighting_restore_device_info_initial_snapshot", source,
        info_nodes["constructor"], {"assignment_expression"},
        lambda node: node.child_by_field_name("left").text == b"this.userQuickEffectOnExit"
        and node.child_by_field_name("right").text == b"void 0")
    _, roles["snapshot_gate"] = one("lighting_restore_device_info_snapshot_gate", broker_source,
        info_nodes["device_ready"], {"if_statement"}, lambda node: any(
            part.type == "member_expression" and part.child_by_field_name("property").text == b"useUserQuickEffectOnExit"
            for part in walk(node.child_by_field_name("condition"))))
    helper_source, _, helper = factory(5459)
    for role, name in (("snapshot_helper", "getChromaEffectCommon"),
                       ("hardware_effect_setter_exception_consumer", "setChromaEffectCommon")):
        _, roles[role] = audit.callable_member("lighting_restore_device_info_" + role, helper_source,
                                               helper, name)
    _, roles["snapshot_getter"] = audit.callable_member("lighting_restore_device_info_snapshot_getter",
                                                        base_source, base, "getChromaEffectCommon")
    for role, mid, key in (("primary_product", 6191, "IS"), ("snapshot_encoder", 6411, "a6"),
                           ("snapshot_header", 5668, "COMMAND_GET_CHROMA_EFFECT_HEADER")):
        exported = audit.webpack_export("lighting_restore_device_info_" + role, originals, mid, key)
        roles[role] = exported["binding"]["owner_id"]
    encoder_source, _, _ = factory(6411)
    encoder_owner = audit.owners[roles["snapshot_encoder"]]
    encoder = audit.tree(encoder_source).root_node.descendant_for_byte_range(
        encoder_owner["byte_start"], encoder_owner["byte_end"] - 1)
    parser_calls = [node for node in walk(encoder) if node.type == "call_expression"
        and node.child_by_field_name("function").type == "identifier"
        and node.parent.type == "sequence_expression" and node.parent.parent.type == "return_statement"]
    if len(parser_calls) != 1:
        raise ValueError("Current lighting snapshot parser has no unique actual return consumer")
    callee = parser_calls[0].child_by_field_name("function")
    parser = audit.binding("lighting_restore_device_info_snapshot_parser", encoder_source,
                           callee.text.decode(), callee.start_byte)
    if parser.get("resolution") != "declaration":
        raise ValueError("Current lighting snapshot parser has no lexical declaration")
    roles["snapshot_parser"] = parser["owner_id"]
    context_source, context, _ = factory(7531)
    roles["dynamic_context"] = audit.retain_range("lighting_restore_device_info_dynamic_context",
        context_source, context.start_byte, context.end_byte, context.type)
    default_source, _, default = factory(4238)
    one("lighting_pid_zero_manifest_only", default_source, default, {"variable_declarator"},
        lambda node: node.child_by_field_name("value") is not None
        and node.child_by_field_name("value").type == "object" and any(
            child.type == "pair" and child.child_by_field_name("key").text == b"quickEffectOnExit"
            for child in node.child_by_field_name("value").named_children))
    return {"classes": classes, "constructors": constructors, "device_info": roles}


def lighting_frontend_abi(audit, source_set_record, originals):
    """Read the current lighting initializer and its actual ABI configuration calls."""
    mains = [row for row in originals if Path(row["path"]).name.startswith("main.")
             and Path(row["path"]).suffix == ".js"]
    if len(mains) != 1:
        raise ValueError("Current lighting ABI main is absent or ambiguous")
    main = mains[0]
    factories = audit.webpack_factories([main], 2198)
    if len(factories) != 1:
        raise ValueError("Current lighting ABI factory is absent or ambiguous")
    _, _, factory = factories[0]
    parameters = factory.child_by_field_name("parameters")
    if parameters is None or len(parameters.named_children) != 3 \
            or any(parameter.type != "identifier" for parameter in parameters.named_children):
        raise ValueError("Lighting ABI factory requires its three actual webpack parameters")
    require_parameter = parameters.named_children[2]

    def walk(node):
        yield node
        for child in node.named_children:
            yield from walk(child)

    def string(node):
        if node is None or node.type != "string":
            raise ValueError("Lighting ABI requires a literal string")
        value = json.loads(node.text)
        if not isinstance(value, str):
            raise ValueError("Lighting ABI string has an invalid type")
        return value

    declarations = []
    for node in walk(factory):
        if node.type != "variable_declarator":
            continue
        value = node.child_by_field_name("value")
        if value is not None and value.type == "object" and any(
                child.type == "pair" and child.child_by_field_name("key").text == b'"4.0.2.0"'
                and b"RzLightingApi:" in child.child_by_field_name("value").text for child in value.named_children):
            declarations.append(node)
    if len(declarations) != 1:
        raise ValueError("Current lighting ABI declaration is absent or ambiguous")
    declaration = declarations[0]
    declaration_name = declaration.child_by_field_name("name")
    if declaration_name.type != "identifier":
        raise ValueError("Lighting ABI declaration has no lexical identifier")
    initializer = declaration.parent
    while initializer is not None and initializer.type != "method_definition":
        initializer = initializer.parent
    if initializer is None or initializer.child_by_field_name("name").text != b"init":
        raise ValueError("Lighting ABI declaration has no complete init owner")
    versions = {}
    for version in declaration.child_by_field_name("value").named_children:
        if version.type != "pair":
            raise ValueError("Lighting ABI version table contains a dynamic field")
        version_name = string(version.child_by_field_name("key"))
        methods = version.child_by_field_name("value")
        if not re.fullmatch(r"\d+\.\d+\.\d+\.\d+", version_name) or version_name in versions or methods.type != "object":
            raise ValueError("Lighting ABI version is invalid or repeated")
        parsed = {}
        for method in methods.named_children:
            if method.type != "pair":
                raise ValueError("Lighting ABI method contains a dynamic field")
            key = method.child_by_field_name("key")
            if key.type not in {"string", "property_identifier"}:
                raise ValueError("Lighting ABI method name is dynamic")
            name = string(key) if key.type == "string" else key.text.decode("utf-8")
            signature = method.child_by_field_name("value")
            if signature.type != "array" or len(signature.named_children) != 2:
                raise ValueError("Lighting ABI method signature is not a return/arguments pair")
            returned, parameters = signature.named_children
            if parameters.type != "array" or name in parsed:
                raise ValueError("Lighting ABI method arguments are dynamic or repeated")
            parsed[name] = [string(returned), [string(parameter) for parameter in parameters.named_children]]
        versions[version_name] = parsed
    declaration_owner = audit.retain_range("lighting_current_abi_declaration", main,
        declaration.start_byte, declaration.end_byte, declaration.type)
    calls = []
    for node in walk(initializer):
        if node.type != "call_expression":
            continue
        arguments = node.child_by_field_name("arguments").named_children
        function = node.child_by_field_name("function")
        wrapped_await = function.type == "call_expression" and function.child_by_field_name("function").text == b"await"
        awaited = wrapped_await or node.parent.type == "await_expression"
        if wrapped_await:
            wrapped = function.child_by_field_name("arguments").named_children
            if len(wrapped) != 2 or wrapped[0].text != b"0":
                continue
            function = wrapped[1]
        if function.type == "parenthesized_expression" and len(function.named_children) == 1:
            function = function.named_children[0]
        if function.type == "sequence_expression" and len(function.named_children) == 2 \
                and function.named_children[0].text == b"0":
            function = function.named_children[1]
        if function.type != "member_expression" or function.child_by_field_name("property").text not in {b"Qq", b"Sl"}:
            continue
        if len(arguments) != 3 or [argument.text for argument in arguments[:2]] != [b"this.dllName", b"this.channelName"] \
                or arguments[2].text != declaration_name.text:
            raise ValueError("Lighting ABI configuration does not consume the observed declaration")
        binding = audit.binding("lighting_current_abi_call_table", main, declaration_name.text.decode(), arguments[2].start_byte)
        if binding.get("owner_id") != declaration_owner:
            raise ValueError("Lighting ABI configuration table is shadowed")
        receiver = function.child_by_field_name("object")
        if receiver.type != "identifier":
            raise ValueError("Lighting ABI configuration has no lexical import receiver")
        imported = audit.binding("lighting_current_abi_bridge_import", main, receiver.text.decode(), receiver.start_byte)
        if imported.get("resolution") != "declaration":
            raise ValueError("Lighting ABI configuration bridge has no lexical declaration")
        imported_node = audit.tree(main).root_node.descendant_for_byte_range(imported.get("start_byte", -1),
                                                                 imported.get("end_byte", 0) - 1)
        imported_value = imported_node.child_by_field_name("value") if imported_node.type == "variable_declarator" else None
        if imported.get("resolution") != "declaration" or imported_value is None or imported_value.type != "call_expression" \
                or [argument.text for argument in imported_value.child_by_field_name("arguments").named_children] != [b"4407"]:
            raise ValueError("Lighting ABI configuration bridge is not the current 4407 import")
        importer = imported_value.child_by_field_name("function")
        if importer.type != "identifier" or importer.text != require_parameter.text:
            raise ValueError("Lighting ABI bridge is not imported by the actual webpack require parameter")
        importer_binding = audit.binding("lighting_current_abi_require", main, importer.text.decode(), importer.start_byte)
        if importer_binding.get("resolution") != "parameter_requires_caller_analysis" \
                or (importer_binding.get("start_byte"), importer_binding.get("end_byte")) != (
                    require_parameter.start_byte, require_parameter.end_byte):
            raise ValueError("Lighting ABI webpack require parameter is shadowed")
        exported = function.child_by_field_name("property").text.decode()
        calls.append({"export": exported, "awaited": awaited,
            "arguments": [argument.text.decode() for argument in arguments],
            "call_owner": audit.retain_range("lighting_current_abi_configuration_" + exported, main,
                node.start_byte, node.end_byte, node.type), "api_declaration_owner": declaration_owner,
            "import_binding": imported, "require_binding": importer_binding, "bridge_export": audit.webpack_export(
                "lighting_current_abi_bridge_" + exported, originals, 4407, exported)})
    if sorted((call["export"], call["awaited"]) for call in calls) != [("Qq", True), ("Sl", False)]:
        raise ValueError("Lighting ABI initializer lacks its two actual configuration branches")
    return {"source_set": source_set_record["name"], "acquisition": source_set_record["acquisition"],
            "current_source_selection": source_set_record.get("current_source_selection"),
            "main": audit.sources[main["path"]], "init_owner": audit.retain_range("lighting_current_abi_initializer", main,
                initializer.start_byte, initializer.end_byte, initializer.type),
            "api_declaration_owner": declaration_owner, "api_versions": versions, "configuration_calls": calls,
            "target_execution": False}


def studio_editing_effect_catalog(audit, source, function):
    """Extract only literal branches from the mounted editor's name mapper."""
    switches = [node for node in _help_nodes(function) if node.type == "switch_statement"]
    if len(switches) != 1:
        raise ValueError("Studio effect-name mapper is absent or ambiguous")
    catalog = {}
    for case in switches[0].child_by_field_name("body").named_children:
        if case.type != "switch_case" or case.child_by_field_name("value").type != "string":
            raise ValueError("Studio effect-name mapper has a dynamic/default branch")
        name = json.loads(case.child_by_field_name("value").text)
        assignments = [node for node in _help_nodes(case) if node.type == "assignment_expression"]
        if len(assignments) != 1 or assignments[0].child_by_field_name("right").type != "number":
            raise ValueError("Studio effect-name mapper has a nonliteral effect ID")
        effect_id = audit.families.javascript_integer_literal(assignments[0].child_by_field_name("right").text.decode())
        if name in catalog or effect_id in {item["effect_id"] for item in catalog.values()}:
            raise ValueError("Studio effect-name mapper has duplicate names or IDs")
        catalog[name] = {"effect_id": effect_id, "owner": audit.retain_range("studio_effect_name_" + name,
            source, case.start_byte, case.end_byte, case.type)}
    return catalog


def studio_editing_lazy_routes(audit, source, sidebar, names):
    """Resolve actual mounted lazy-module IDs, without executing their loader."""
    candidates = []
    for node in _help_nodes(sidebar):
        if node.type != "object":
            continue
        pairs = [item for item in node.named_children if item.type == "pair"]
        keys = [json.loads(item.child_by_field_name("key").text) if
            item.child_by_field_name("key").type == "string" else item.child_by_field_name("key").text.decode()
            for item in pairs]
        if set(keys) == set(names):
            if len(keys) != len(set(keys)):
                raise ValueError("Studio mounted effect routes have duplicate names")
            candidates.append((pairs, keys))
    if len(candidates) != 1:
        raise ValueError("Studio mounted effect routes do not match its name mapper")
    routes = {}
    for pair, name in zip(*candidates[0]):
        binds, chunks = [], []
        for node in _help_nodes(pair.child_by_field_name("value")):
            if node.type != "call_expression":
                continue
            function = node.child_by_field_name("function")
            if function.type != "member_expression":
                continue
            prop = function.child_by_field_name("property").text
            arguments = node.child_by_field_name("arguments").named_children
            if prop == b"bind":
                if len(arguments) != 2 or arguments[1].type != "number":
                    raise ValueError("Studio effect lazy module is dynamic")
                binds.append(int(arguments[1].text))
            elif prop == b"e":
                if len(arguments) != 1 or arguments[0].type != "number":
                    raise ValueError("Studio effect lazy chunk is dynamic")
                chunks.append(int(arguments[0].text))
        if len(binds) != 1 or not chunks:
            raise ValueError("Studio effect route has no unique lazy module")
        routes[name] = {"module_id": binds[0], "chunk_ids": chunks,
            "owner": audit.retain_range("studio_mounted_effect_route_" + name, source,
                pair.start_byte, pair.end_byte, pair.type)}
    return routes


def collect_studio_editing_consumers(audit):
    """Join the current shared draft, preview and local-profile consumers."""
    import frontend

    current = frontend.current_source_selection("https://apps.razer.com/synapse/chroma-studio/", audit,
        candidates=sorted((audit.a.ROOT / ".analysis/inputs/frontend").glob("synapse-chroma-studio*/acquisition.json")))
    originals = current["originals"]
    source_sets = [{key: current[key] for key in ("name", "canonical_entry_url", "acquisition", "deployment",
        "capture", "capture_failures", "unresolved_acquisition", "failed_acquisition", "candidate_decisions")}]
    selected, exports = {}, []

    def source(prefix):
        matches = [row for row in originals if Path(row["path"]).name.startswith(prefix)
                   and Path(row["path"]).suffix == ".js"]
        if len(matches) != 1:
            raise ValueError("Current Studio source is absent or ambiguous: " + prefix)
        return matches[0]

    def retain(role, item, anchor, kinds):
        owner, = audit.retain("studio_editing_" + role, item, anchor, set(kinds))
        selected[role] = [owner]
        return _help_binding_node(audit, item, {"resolution": "declaration",
            "start_byte": audit.owners[owner]["byte_start"], "end_byte": audit.owners[owner]["byte_end"]})

    def exported(role, module_id, name, files=originals):
        result = audit.webpack_export("studio_editing_" + role, files, module_id, name)
        selected[role] = [result["binding"]["owner_id"]]
        exports.append({"role": role, **result})
        return result, _help_binding_node(audit, result["original"], result["binding"])

    def actual(role, item, access):
        _, factory, owner = javascript_import_namespace(audit, originals, item,
            access.child_by_field_name("object"), role="studio_editing_" + role)
        selected[role + "_import_factory"] = [owner]
        return exported(role, _help_factory(factory)["module_id"], access.child_by_field_name("property").text.decode())

    main, canvas = source("main."), source("EditorCanvas.")
    retain("react_mount", main, 'createRoot(document.getElementById("root"))', ("expression_statement",))
    retain("app_composition", main, "store:Zo.A", ("variable_declarator",))
    retain("editor_lazy_mount", main, ".e(244)", ("function_declaration",))
    retain("unsaved_header_mount", main, ".e(666)", ("function_declaration",))
    retain("save_modal_mount", main, ".e(193)", ("function_declaration",))
    sidebar = retain("mounted_parameter_sidebar", canvas, "effects-custom-container", ("function_declaration",))
    retain("preview_toolbar", canvas, 'id:"editor-preview"', ("variable_declarator",))
    mounted, owner = audit.callable_member("studio_editing_canvas_memory_consumer", canvas,
        audit.tree(canvas).root_node, "onComponentDidMount")
    selected["canvas_memory_consumer"] = [owner]
    canvas_class = mounted
    while canvas_class is not None and canvas_class.type not in {"class", "class_declaration"}:
        canvas_class = canvas_class.parent
    if canvas_class is None:
        raise ValueError("Studio mounted editor has no lifecycle owner")
    for name in ("render", "componentDidMount", "componentWillUnmount"):
        _, owner = audit.callable_member("studio_editing_canvas_" + name, canvas, canvas_class, name)
        selected["canvas_" + name] = [owner]
    retain("connected_canvas", canvas, "addDeviceItemTypes:c.w4", ("variable_declarator",))
    for name, role in (("g7", "reset_parameters"), ("ce", "save_profile"), ("yt", "unsaved_prompt"),
                       ("ih", "restore_saved_profile")):
        matches = [node for node in _help_nodes(sidebar) if node.type == "member_expression"
            and node.child_by_field_name("property").text == name.encode()]
        if not matches or len({audit.binding("studio_editing_sidebar_namespace", canvas,
                node.child_by_field_name("object").text.decode(), node.start_byte)["owner_id"]
                for node in matches}) != 1:
            raise ValueError("Studio sidebar action is absent or ambiguous: " + role)
        actual(role, canvas, matches[0])
    layers = {}
    for name, role in (("AQ", "new_layer"), ("XP", "add_layer"), ("ed", "select_layer"),
                       ("HZ", "set_parameters"), ("XF", "set_layer_parameters"), ("xo", "merge_selected_regions"),
                       ("jJ", "flatten_draft_layers"), ("ql", "flatten_saved_layers")):
        result, node = exported(role, 9286, name)
        layers[role] = (result, node)
    defaults = {}
    for name, role in (("$k", "effect_name_mapper"), ("rH", "region_defaults"),
                       ("pR", "layer_geometry_defaults"), ("c9", "parameter_normalizer")):
        result, node = exported(role, 2904, name)
        defaults[role] = (result, node)
    catalog = studio_editing_effect_catalog(audit, defaults["effect_name_mapper"][0]["original"],
                                          defaults["effect_name_mapper"][1])
