def _lighting_ripple_frontend_owner(audit, source, factory, role, name, syntax, expected):
    """Retain one reviewed lexical owner inside the actually mounted factory."""
    matches = [node for node in _help_nodes(factory) if node.type == syntax
               and node.child_by_field_name("name") is not None
               and node.child_by_field_name("name").text.decode() == name]
    if len(matches) != 1:
        raise ValueError("Current Ripple lexical owner is absent or ambiguous: " + role)
    node, = matches
    owner = audit.retain_range("lighting_ripple_" + role, source, node.start_byte, node.end_byte, node.type)
    if audit.owners[owner]["body_sha256"] != expected:
        raise ValueError("Current Ripple source requires semantic review: " + role)
    return node, owner


def _lighting_ripple_native_source(audit):
    """Bind the retained lighting PE to the current stable release declaration."""
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for item in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / item["path"], item)
    matches = [row for row in release["files"]
               if row.get("declaration", {}).get("resourceName") == "LightingEngineDLL"]
    if len(matches) != 1:
        raise ValueError("Current Ripple native declaration is absent or ambiguous")
    original, = matches
    declaration = original["declaration"]
    if (original.get("manifest_identity_verified") is not True
            or declaration.get("sha256", "").lower() != original.get("sha256")
            or declaration.get("size") != original.get("bytes")
            or declaration.get("url") != original.get("url")):
        raise ValueError("Current Ripple native resource declaration differs")
    if (declaration.get("resourceVersion"), original["sha256"], original["bytes"]) != (
            "4.0.55.0", "cd9fc2a61ff920b9b73e1f5e27632020e2f8586f443e426a875ad3b042b714fa", 2153672):
        raise ValueError("Current Ripple native algorithms require semantic review")
    audit.read(original)
    return original, {"version": release["version"], "receipt": release["receipt"],
                      "declaration": declaration, "authorities": original["authorities"],
                      "verified_dependencies": release["verified_dependencies"]}


