    if (original["sha256"], original["bytes"]) != (
            "cd9fc2a61ff920b9b73e1f5e27632020e2f8586f443e426a875ad3b042b714fa", 2153672):
        raise ValueError("Current lighting input native algorithms require semantic review")
    release_manifests = []
