def _mapping_external_input_source(audit):
    """Bind the external hardware route to the explicit current host release."""
    original, provenance = _mapping_physical_input_inputs(audit)
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    matches = [row for row in current_host_asar_members(audit, indexed, release)
               if row["path"].endswith("/electron/modules/mapping_engine/win/index.js")]
    if len(matches) != 1:
        raise ValueError("Current external input host source is absent or ambiguous")
    source = matches[0]
    archive = next(row for row in indexed["inputs"] if row["path"] == source["container"])
    package = provenance["official_package"]
    if (archive.get("container") != package["path"]
            or archive.get("container_sha256") != package["sha256"]
            or archive["sha256"] != source["container_sha256"]
            or source.get("unpacked") or source.get("offset") is None):
        raise ValueError("Current external input host package/ASAR ancestry differs")
    body, packed = audit.read(source), audit.read(archive)
    if packed[source["offset"]:source["offset"] + len(body)] != body:
        raise ValueError("Current external input host source differs from its ASAR bytes")
    return original, source, {**provenance, "host_source": source, "host_archive": archive}


