def _mapping_ble_analog_stick_tables(raw):
    """Read the BLE class switch and axis names from the actual current PE."""
    pe = inspect_pe(raw)
    base = int(pe["image_base"], 16)

    def region(rva, size):
        rows = [row for row in pe["sections"]
                if row["rva"] <= rva and rva + size <= row["rva"] + row["bytes"]]
        if len(rows) != 1:
            raise ValueError("BLE analog stick PE region is absent or ambiguous")
        offset = rows[0]["file_offset"] + rva - rows[0]["rva"]
        return raw[offset:offset + size]

    switch = region(0x2e55f8, 36)
    targets = [0x2e55f8 + value for value, in struct.iter_unpack("<i", switch)]
    if targets != [0x53e98, 0x53ebd, 0x53ee2, 0x53f04, 0x53f14,
                   0x53f36, 0x53f58, 0x53e85, 0x53e85]:
        raise ValueError("BLE analog stick actual report-class switch differs")
    names = []
    axis_table = region(0x2eeaa0, 40)
    for pointer, in struct.iter_unpack("<Q", axis_table):
        name = bytearray()
        for offset in range(32):
            value = region(pointer - base + offset, 1)[0]
            if value == 0:
                break
            name.append(value)
        else:
            raise ValueError("BLE analog stick axis name is unterminated")
        names.append(name.decode("ascii"))
    if names != ["left", "right", "up", "down", "invalid"]:
        raise ValueError("BLE analog stick actual axis names differ")
    return {"class_switch_rva": "0x2e55f8", "class_targets": [hex(value) for value in targets],
        "class_switch_bytes_sha256": hashlib.sha256(switch).hexdigest(),
        "axis_names_rva": "0x2eeaa0", "axis_names": names,
        "axis_table_bytes_sha256": hashlib.sha256(axis_table).hexdigest(), "actual_pe_bytes_verified": True}


