def _keypad_mapping_consumer_sources(audit):
    """Choose the actual current 747 deployment before reusing older semantics."""
    import frontend
    boundary = audit.a.ROOT / ".analysis/inputs/frontend"
    selections, originals, sources = {}, {}, {}
    for side, pattern in (("ui", "keyboard-747-*/acquisition.json"),
                          ("mw", "keyboard-mw-747-*/acquisition.json")):
        current = frontend.current_source_selection(
            "https://apps.razer.com/synapse/products/747/" + side + "/", audit,
            candidates=sorted(boundary.glob(pattern)), verify_capture=False)
        originals[side] = current.pop("originals")
        selections[side] = current
    for role, (side, filename, size, digest) in KEYPAD_MAPPING_CONSUMER_INPUTS.items():
        rows = [row for row in originals[side] if Path(row["path"]).name == filename]
        if len(rows) != 1 or (rows[0]["bytes"], rows[0]["sha256"]) != (size, digest):
            raise ValueError("Current keypad mapping source requires semantic review: " + role)
        audit.read(rows[0])
        sources[role] = rows[0]
    return selections, originals, sources


def _keypad_mapping_consumer_deployment(receipt, sources, selections):
    """Limit the double-GET receipt to the selected thirteen complete originals."""
    if (receipt.get("passed") is not True or receipt.get("failures")
            or receipt.get("inputs_unchanged") is not True
            or receipt.get("protected_originals_unchanged") is not True
            or receipt.get("index_changed") is not False or receipt.get("target_execution") is not False):
        raise ValueError("Current keypad mapping deployment verification failed")
    acquired = {row["acquisition"]["path"]: row["acquisition"] for row in receipt["source_sets"]}
    for value in selections.values():
        if acquired.get(value["acquisition"]["path"]) != value["acquisition"]:
            raise ValueError("Current keypad mapping deployment selected another acquisition")
    selected = []
    for role, source in sources.items():
        matches = [row for row in receipt["observations"]
                   if (row.get("retained_original") or {}).get("path") == source["path"]]
        if len(matches) != 1:
            raise ValueError("Current keypad mapping deployment owner is absent or ambiguous: " + role)
        row = matches[0]
        if (row.get("required") is not True or row.get("classification") != "unchanged_reused"
                or any(row["retained_original"].get(key) != source[key] for key in ("bytes", "sha256"))
                or [item.get("round") for item in row.get("rounds", [])] != [1, 2]
                or any(item.get("status") != "ok" or item.get("http_status") != 200
                       or any(item.get(key) != source[key] for key in ("bytes", "sha256"))
                       for item in row["rounds"])):
            raise ValueError("Current keypad mapping deployment owner changed: " + role)
        selected.append({"role": role, "original": source, "url": row["url"], "verified_rounds": [1, 2]})
    return {"selected_originals_verified": selected, "observations_in_receipt": len(receipt["observations"]),
        "selected_owner_count": len(selected), "whole_deployment_closure_verified": False,
        "target_execution": False}


