    """Revalidate the actual shared dpad consumers selected by current 747 Fe."""
    source = collect_keypad_mapping_consumers(audit)
    if (source.get("kind") != "current_keypad_mapping_consumers" or source.get("product_id") != 747
            or source.get("verified_contract", {}).get("actual_compiler_path") !=
                ["1610.B", "32226.A", "4325.RzAppEngineMapping_default", "Fe"]):
        raise ValueError("Current keypad native actual source compiler join differs")
    original, provenance = _mapping_physical_input_inputs(audit)
    if (original["sha256"], original["bytes"]) != (
            "c64e539437b50da2b1f2e4155d8cbb0fb1c3e1ebaad894caf509bad97e9857f9", 3948744):
        raise ValueError("Current keypad native input requires semantic review; prior evidence cannot substitute")
    raw = audit.read(original)
    pe = inspect_pe(raw)
    if [row["tree"].get("file_version") for row in pe["version_resources"]] != ["1.3.17.2"]:
        raise ValueError("Current keypad native version differs")
    slots = [{"role": role + "_slot_" + str(index * 8), "vtable_rva": table,
              "slot_byte_offset": index * 8, "target_rva": target}
        for role, table, targets in KEYPAD_MAPPING_CURRENT_NATIVE_TABLES for index, target in enumerate(targets)]
    slots.extend({"role": role, "vtable_rva": table, "slot_byte_offset": offset, "target_rva": target}
        for role, table, offset, target in (("input_make_lookup", 0x2e6a78, 24, 0x66d10),
            ("input_dispatch", 0x2e6a78, 32, 0x69530), ("driver_actual_send", 0x2f1990, 96, 0x112ee0)))
    native = audit.families.verify_native_functions(original, KEYPAD_MAPPING_CURRENT_NATIVE_ROLES, slots)
    for function in native["complete_selected_functions"]:
        if not function["pseudocode_captured"] or function["failures"]:
            raise ValueError("Current keypad native selected owner remains incomplete: " + function["role"])
    proof = _keypad_mapping_current_native_proof(raw, native)
    for function in native["complete_selected_functions"]:
        body = function.pop("capture")
        function["rva"] = body["rva"]
        function["pseudocode_text_sha256"] = hashlib.sha256("\n".join(
            line["text"] for line in body["pseudocode"]["lines"]).encode()).hexdigest()
        audit.artifact(audit.a.ROOT / function["artifact"]["path"], function["artifact"])
    audit.artifact(audit.a.ROOT / native["capture_receipt"]["path"], native["capture_receipt"])
