def _mapping_physical_input_inputs(audit):
    """Select the input decoder from the current release-owned package."""
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for dependency in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / dependency["path"], dependency)
    candidates = [row for row in current_host_extracted_inputs(indexed, release)
                  if row["path"].endswith("/CommonDLL/mapping_engine.dll")]
    if len(candidates) != 1:
        raise ValueError("Current mapping physical input is absent or ambiguous")
    original = candidates[0]
    packages = [row for row in release["files"] if row.get("path") == original["container"]
                and row.get("sha256") == original["container_sha256"]]
    if len(packages) != 1:
        raise ValueError("Current mapping physical input package ancestry differs")
    audit.artifact(audit.a.ROOT / packages[0]["path"], packages[0])
    audit.read(original)
    return original, {"release_version": release["version"], "acquisition": release["receipt"],
        "official_package": packages[0], "original": original}


