def _mapping_kernel_input_inputs(audit):
    """Bind the shared producer and one actual product provider to current packages."""
    indexed = json.loads(audit.artifact(audit.a.ROOT / ".analysis/inputs.json"))
    release = verified_host_release_receipt(index=indexed)
    audit.artifact(audit.a.ROOT / release["receipt"]["path"], release["receipt"])
    for row in release["verified_dependencies"]:
        audit.artifact(audit.a.ROOT / row["path"], row)
    current = current_host_extracted_inputs(indexed, release)

    def member(rows, suffix, package, *, native=False):
        matches = [row for row in rows if row["path"].endswith("/" + suffix)]
        if len(matches) != 1:
            raise ValueError("Current kernel input member is absent or ambiguous: " + suffix)
        original = matches[0]
        prefix = ".analysis/inputs/official-native-current/extracted/" if native else ".analysis/inputs/host-current/extracted/"
        if (not original["path"].startswith(prefix)
                or original.get("container") != package["path"]
                or original.get("container_sha256") != package["sha256"]
                or native and (original.get("verified_against_manifest") is not True
                    or original.get("declared_container_sha256") != package["sha256"]
                    or original.get("container_extraction_complete") is not True)):
            raise ValueError("Current kernel input member package ancestry differs: " + suffix)
        reference = original.get("extraction_receipt")
        if reference is None:
            raise ValueError("Current kernel input extraction receipt is missing")
        inspection = json.loads(audit.artifact(audit.a.ROOT / reference["path"], reference))
        if native:
            extraction = inspection
            source_matches = extraction.get("container") == {key: package[key] for key in ("path", "bytes", "sha256")}
            listing_complete = extraction.get("listing_exit_code") == 0
        else:
            containers = [row for row in inspection.get("containers", [])
                          if row.get("input") == package["path"] and row.get("sha256") == package["sha256"]]
            if len(containers) != 1:
                raise ValueError("Current kernel input extraction container differs")
            extraction = containers[0]
            source_matches = extraction.get("retained_outputs_verified") is True
            listing_complete = extraction.get("list_exit_code") == 0
        retained = [row for row in extraction["files"] if row["path"] == original["path"]]
        if (len(retained) != 1 or any(retained[0][key] != original[key] for key in ("path", "bytes", "sha256"))
                or extraction.get("extracted") is not True or extraction.get("extraction_exit_code") != 0
                or not listing_complete or not source_matches or extraction.get("input_bytes_unchanged") is not True
                or inspection.get("target_execution") is not False):
            raise ValueError("Current kernel input extraction is incomplete or differs: " + suffix)
        audit.read(original)
        return original

    packages = [row for row in release["files"] if row.get("path", "").endswith("/RzComDriver_v23.0.6.0.exe")]
    if len(packages) != 1:
        raise ValueError("Current kernel common package is absent or ambiguous")
    common_package = packages[0]
    audit.artifact(audit.a.ROOT / common_package["path"], common_package)
    inputs = {"common": member(current, "Drivers/x64/RzCommon.sys", common_package),
        "common_inf": [member(current, "Drivers/x64/" + name, common_package)
                       for name in ("RzCommon.inf", "RzCommonU.inf")]}
    acquisition_path = audit.a.ROOT / ".analysis/inputs/official-native-current/acquisition.json"
    acquisition = json.loads(audit.artifact(acquisition_path))
    packages = [row for row in acquisition["resources"] if row.get("status") == "verified"
                and row.get("url") == "https://app-assets.razer.com/files/synapse/devices/226/PID00e2Drv_v26.0.2.0.exe"]
    if (len(packages) != 1 or acquisition.get("source_current_during_acquisition") is not True
            or acquisition.get("target_execution") is not False):
        raise ValueError("Current kernel product226 package is absent or unverified")
    package = packages[0]
    if (not package.get("path", "").startswith(".analysis/inputs/official-native-current/blobs/")
            or (package.get("sha256"), package.get("bytes")) !=
               (package.get("declared_sha256"), package.get("declared_bytes"))):
        raise ValueError("Current kernel product226 package declaration differs")
    audit.read(package)
    manifests = [row for row in package["manifests"]
                 if row.get("url") == "https://apps.razer.com/synapse/products/226/mw/manifest.json"
                 and row.get("resource_name") == "NormalDriver_PID00e2Drv"]
    if len(manifests) != 1:
        raise ValueError("Current kernel product226 manifest is absent or ambiguous")
    manifest = manifests[0]
    document = json.loads(audit.artifact(audit.a.ROOT / manifest["path"], manifest))
    declared = [row for row in document["resourceManifest"]["resources"]
                if row.get("resourceName") == manifest["resource_name"]]
    stability = [row for row in acquisition["stability"] if row["url"] == manifest["url"]]
    if (len(declared) != 1 or declared[0].get("sha256", "").lower() != package["sha256"]
            or declared[0].get("size") != package["bytes"] or declared[0].get("url") != package["url"]
            or declared[0].get("resourceVersion") != manifest["resource_version"]
            or len(stability) != 1 or stability[0].get("unchanged") is not True
            or stability[0].get("before_sha256") != manifest["sha256"]
            or stability[0].get("after_sha256") != manifest["sha256"]):
        raise ValueError("Current kernel product226 manifest declaration or deployment differs")
    candidates = [row for row in indexed["inputs"] if row.get("container") == package["path"]]
    inputs["product_226"] = member(candidates, "Drivers/x64/RzDev_00e2.sys", package, native=True)
    inputs["product_226_inf"] = [member(candidates, "Drivers/x64/" + name, package, native=True)
        for name in ("RzDevU_00e2_Mou.inf", "KB/RzDevU_00e2_Kbd.inf", "Lower/RzDevU_00e2_Dkm.inf")]
    return inputs, {"release_version": release["version"], "host_acquisition": release["receipt"],
        "common_package": common_package, "common_original": inputs["common"],
        "product_acquisition": audit.families.identity(acquisition_path), "product_package": package,
        "product_manifest": manifest, "product_original": inputs["product_226"],
        "product_deployment_stable_during_acquisition": True}


